        {
            "name": "admin_grant_points",
            "schema": "public",
            "language": "plpgsql",
            "arguments": "p_customer_id uuid, p_amount bigint, p_reason text, p_idempotency_key text",
            "definition": "CREATE OR REPLACE FUNCTION public.admin_grant_points(p_customer_id uuid, p_amount bigint, p_reason text, p_idempotency_key text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare\n  v_balance public.points_balance;\n  v_operation uuid;\nbegin\n  if not public.has_admin_permission('finance.write') then\n    raise exception 'FORBIDDEN';\n  end if;\n\n  if p_amount <= 0 then raise exception 'INVALID_AMOUNT'; end if;\n  if nullif(trim(p_reason),'') is null then raise exception 'REASON_REQUIRED'; end if;\n\n  insert into public.points_balance(customer_id)\n  values(p_customer_id)\n  on conflict(customer_id) do nothing;\n\n  select * into v_balance\n  from public.points_balance\n  where customer_id=p_customer_id\n  for update;\n\n  insert into public.points_ledger(\n    customer_id,direction,amount,balance_before,balance_after,\n    entry_type,source_type,description,created_by\n  )\n  values(\n    p_customer_id,'CREDIT',p_amount,v_balance.balance,\n    v_balance.balance+p_amount,'ADMIN_GRANT','admin_grant',\n    p_reason,public.current_admin_id()\n  );\n\n  update public.points_balance\n  set balance=balance+p_amount,updated_at=now()\n  where id=v_balance.id;\n\n  insert into public.operation(\n    operation_key,operation_type,actor_type,actor_id,\n    entity_type,entity_id,status,idempotency_key,completed_at\n  )\n  values(\n    public.generate_public_code('OP'),'ADMIN_GRANT','ADMIN',\n    public.current_admin_id(),'customer_profile',p_customer_id,\n    'COMPLETED',p_idempotency_key,now()\n  )\n  returning id into v_operation;\n\n  insert into public.audit_log(\n    actor_type,actor_id,operation_id,entity_type,entity_id,action,\n    permission_code,reason\n  )\n  values(\n    'ADMIN',public.current_admin_id(),v_operation,\n    'customer_profile',p_customer_id,'ADMIN_GRANT',\n    'finance.write',p_reason\n  );\n\n  return jsonb_build_object(\n    'customer_id',p_customer_id,\n    'balance',v_balance.balance+p_amount\n  );\nend;\n$function$\n",
            "return_type": "jsonb",
            "security_definer": true
        },
