        {
            "name": "admin_save_provider_tariff",
            "schema": "public",
            "language": "plpgsql",
            "arguments": "p_id uuid, p_provider_id uuid, p_tariff_mode tariff_mode, p_duration_unit_days integer, p_points_per_unit bigint, p_rate numeric, p_currency text, p_effective_from timestamp with time zone, p_effective_to timestamp with time zone, p_status text",
            "definition": "CREATE OR REPLACE FUNCTION public.admin_save_provider_tariff(p_id uuid, p_provider_id uuid, p_tariff_mode tariff_mode, p_duration_unit_days integer, p_points_per_unit bigint, p_rate numeric, p_currency text, p_effective_from timestamp with time zone, p_effective_to timestamp with time zone, p_status text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare\n  v_admin_id uuid;\n  v_tariff public.protection_tariff;\n  v_before jsonb;\n  v_operation_id uuid;\n  v_status public.generic_status;\nbegin\n  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;\n  if not public.has_admin_permission('providers.write') then raise exception 'FORBIDDEN'; end if;\n  if p_duration_unit_days is null or p_duration_unit_days not between 1 and 36500 then raise exception 'INVALID_DURATION_UNIT_DAYS'; end if;\n  if p_points_per_unit is null or p_points_per_unit<=0 or p_points_per_unit>76861433640456465 then raise exception 'INVALID_POINTS_PER_UNIT'; end if;\n  if p_rate is null or p_rate<0 then raise exception 'INVALID_TARIFF_RATE'; end if;\n  if nullif(trim(p_currency),'') is null then raise exception 'CURRENCY_REQUIRED'; end if;\n  if p_effective_from is null or (p_effective_to is not null and p_effective_to<=p_effective_from) then raise exception 'INVALID_EFFECTIVE_RANGE'; end if;\n  v_status:=case lower(coalesce(p_status,'')) when 'active' then 'ACTIVE'::public.generic_status when 'inactive' then 'INACTIVE'::public.generic_status else null end;\n  if v_status is null then raise exception 'INVALID_TARIFF_STATUS'; end if;\n  if not exists(select 1 from public.telecom_company where id=p_provider_id) then raise exception 'PROVIDER_NOT_FOUND'; end if;\n  v_admin_id:=public.current_admin_id();\n  if v_admin_id is null then raise exception 'ADMIN_NOT_FOUND'; end if;\n\n  if p_id is null then\n    insert into public.protection_tariff(\n      telecom_company_id,tariff_mode,rate,currency,effective_from,effective_to,status,\n      duration_unit_days,points_per_unit\n    ) values (\n      p_provider_id,p_tariff_mode,p_rate,trim(p_currency),p_effective_from,p_effective_to,v_status,\n      p_duration_unit_days,p_points_per_unit\n    ) returning * into v_tariff;\n  else\n    select * into v_tariff from public.protection_tariff\n      where id=p_id and telecom_company_id=p_provider_id for update;\n    if v_tariff.id is null then raise exception 'TARIFF_NOT_FOUND'; end if;\n    v_before:=to_jsonb(v_tariff);\n    update public.protection_tariff set\n      tariff_mode=p_tariff_mode,rate=p_rate,currency=trim(p_currency),\n      effective_from=p_effective_from,effective_to=p_effective_to,status=v_status,\n      duration_unit_days=p_duration_unit_days,points_per_unit=p_points_per_unit,updated_at=now()\n      where id=v_tariff.id returning * into v_tariff;\n  end if;\n\n  insert into public.operation(operation_key,operation_type,actor_type,actor_id,entity_type,entity_id,status,result_reference,completed_at)\n    values(public.generate_public_code('OP'),'SAVE_PROTECTION_TARIFF','ADMIN',v_admin_id,'protection_tariff',v_tariff.id,'COMPLETED',v_tariff.id::text,now())\n    returning id into v_operation_id;\n  insert into public.audit_log(actor_type,actor_id,operation_id,entity_type,entity_id,action,permission_code,before_state,after_state)\n    values('ADMIN',v_admin_id,v_operation_id,'protection_tariff',v_tariff.id,\n      case when p_id is null then 'CREATE_TARIFF' else 'UPDATE_TARIFF' end,\n      'providers.write',v_before,to_jsonb(v_tariff));\n  return jsonb_build_object('tariff_id',v_tariff.id,'tariff_mode',v_tariff.tariff_mode,\n    'duration_unit_days',v_tariff.duration_unit_days,'points_per_unit',v_tariff.points_per_unit,\n    'rate',v_tariff.rate,'currency',v_tariff.currency,'status',v_tariff.status,'operation_id',v_operation_id);\nend;\n$function$\n",
            "return_type": "jsonb",
            "security_definer": true
        },
        {
            "name": "admin_save_task_configuration",
            "schema": "public",
            "language": "plpgsql",
            "arguments": "p_telecom_company_id uuid, p_interval_days integer, p_task_amount numeric, p_currency text, p_visibility_days_before integer, p_allow_reschedule boolean, p_allow_post_expiry_creation boolean, p_post_expiry_grace_days integer, p_create_first_task_on_activation boolean, p_create_first_task_on_renewal boolean, p_effective_from timestamp with time zone, p_idempotency_key text",
            "definition": "CREATE OR REPLACE FUNCTION public.admin_save_task_configuration(p_telecom_company_id uuid, p_interval_days integer, p_task_amount numeric, p_currency text, p_visibility_days_before integer, p_allow_reschedule boolean, p_allow_post_expiry_creation boolean, p_post_expiry_grace_days integer, p_create_first_task_on_activation boolean, p_create_first_task_on_renewal boolean, p_effective_from timestamp with time zone, p_idempotency_key text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare v_row public.task_configuration; v_old public.task_configuration; v_operation uuid;\nbegin\n  if not public.has_admin_permission('task_settings.write') then raise exception 'FORBIDDEN'; end if;\n  if p_telecom_company_id is null or p_interval_days is null or p_interval_days<=0 or p_task_amount is null or p_task_amount<0 or nullif(trim(p_currency),'') is null or p_visibility_days_before is null or p_visibility_days_before<0 or p_post_expiry_grace_days is null or p_post_expiry_grace_days<0 or p_effective_from is null then raise exception 'INVALID_TASK_CONFIGURATION'; end if;\n  if not exists(select 1 from public.telecom_company where id=p_telecom_company_id) then raise exception 'COMPANY_NOT_FOUND'; end if;\n  select * into v_old from public.task_configuration where telecom_company_id=p_telecom_company_id and status='ACTIVE' and effective_to is null order by effective_from desc limit 1 for update;\n  if v_old.id is not null then\n    if p_effective_from<=v_old.effective_from then raise exception 'EFFECTIVE_FROM_MUST_ADVANCE'; end if;\n    update public.task_configuration set effective_to=p_effective_from,updated_at=now() where id=v_old.id;\n  end if;\n  insert into public.task_configuration(telecom_company_id,interval_days,task_amount,currency,visibility_days_before,\n    allow_reschedule,allow_post_expiry_creation,post_expiry_grace_days,create_first_task_on_activation,create_first_task_on_renewal,\n    status,effective_from)\n  values(p_telecom_company_id,p_interval_days,p_task_amount,trim(p_currency),p_visibility_days_before,\n    coalesce(p_allow_reschedule,false),coalesce(p_allow_post_expiry_creation,false),p_post_expiry_grace_days,\n    coalesce(p_create_first_task_on_activation,false),coalesce(p_create_first_task_on_renewal,false),'ACTIVE',p_effective_from)\n  returning * into v_row;\n  v_operation:=public.admin_record_change('CREATE_TASK_CONFIGURATION','task_configuration',v_row.id,'task_settings.write',\n    case when v_old.id is null then null else to_jsonb(v_old) end,to_jsonb(v_row),null,p_idempotency_key);\n  return jsonb_build_object('configuration',to_jsonb(v_row),'operation_id',v_operation,'existing_task_plans_rebuilt',false);\nend $function$\n",
            "return_type": "jsonb",
            "security_definer": true
        },
        {
            "name": "admin_save_telecom_company",
            "schema": "public",
            "language": "plpgsql",
            "arguments": "p_id uuid, p_code text, p_name text, p_status text, p_idempotency_key text",
            "definition": "CREATE OR REPLACE FUNCTION public.admin_save_telecom_company(p_id uuid, p_code text, p_name text, p_status text, p_idempotency_key text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare v_row public.telecom_company; v_before jsonb;\nbegin\n  if not public.has_admin_permission('providers.write') then raise exception 'FORBIDDEN'; end if;\n  if nullif(trim(p_code),'') is null or nullif(trim(p_name),'') is null then raise exception 'COMPANY_FIELDS_REQUIRED'; end if;\n  if upper(coalesce(p_status,'')) not in ('ACTIVE','INACTIVE') then raise exception 'INVALID_STATUS'; end if;\n  if p_id is null then\n    insert into public.telecom_company(code,name,status) values(trim(p_code),trim(p_name),upper(p_status)::public.generic_status) returning * into v_row;\n  else\n    select * into v_row from public.telecom_company where id=p_id for update;\n    if v_row.id is null then raise exception 'COMPANY_NOT_FOUND'; end if;\n    v_before:=to_jsonb(v_row);\n    update public.telecom_company set code=trim(p_code),name=trim(p_name),status=upper(p_status)::public.generic_status,updated_at=now()\n      where id=p_id returning * into v_row;\n  end if;\n  perform public.admin_record_change(case when p_id is null then 'CREATE_TELECOM_COMPANY' else 'UPDATE_TELECOM_COMPANY' end,\n    'telecom_company',v_row.id,'providers.write',v_before,to_jsonb(v_row),null,p_idempotency_key);\n  return to_jsonb(v_row);\nend $function$\n",
            "return_type": "jsonb",
            "security_definer": true
        },
        {
            "name": "admin_save_telecom_prefix",
            "schema": "public",
            "language": "plpgsql",
            "arguments": "p_id uuid, p_telecom_company_id uuid, p_prefix text, p_status text, p_idempotency_key text",
            "definition": "CREATE OR REPLACE FUNCTION public.admin_save_telecom_prefix(p_id uuid, p_telecom_company_id uuid, p_prefix text, p_status text, p_idempotency_key text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare v_row public.telecom_prefix; v_before jsonb;\nbegin\n  if not public.has_admin_permission('providers.write') then raise exception 'FORBIDDEN'; end if;\n  if p_telecom_company_id is null or nullif(trim(p_prefix),'') is null then raise exception 'PREFIX_FIELDS_REQUIRED'; end if;\n  if upper(coalesce(p_status,'')) not in ('ACTIVE','INACTIVE') then raise exception 'INVALID_STATUS'; end if;\n  if not exists(select 1 from public.telecom_company where id=p_telecom_company_id) then raise exception 'COMPANY_NOT_FOUND'; end if;\n  if p_id is null then\n    insert into public.telecom_prefix(telecom_company_id,prefix,status)\n      values(p_telecom_company_id,trim(p_prefix),upper(p_status)::public.generic_status) returning * into v_row;\n  else\n    select * into v_row from public.telecom_prefix where id=p_id and telecom_company_id=p_telecom_company_id for update;\n    if v_row.id is null then raise exception 'PREFIX_NOT_FOUND'; end if;\n    v_before:=to_jsonb(v_row);\n    update public.telecom_prefix set prefix=trim(p_prefix),status=upper(p_status)::public.generic_status,updated_at=now()\n      where id=p_id returning * into v_row;\n  end if;\n  perform public.admin_record_change(case when p_id is null then 'CREATE_TELECOM_PREFIX' else 'UPDATE_TELECOM_PREFIX' end,\n    'telecom_prefix',v_row.id,'providers.write',v_before,to_jsonb(v_row),null,p_idempotency_key);\n  return to_jsonb(v_row);\nend $function$\n",
            "return_type": "jsonb",
            "security_definer": true
        },
        {
            "name": "admin_send_notification",
            "schema": "public",
            "language": "plpgsql",
            "arguments": "p_target_type text, p_target_id uuid, p_title text, p_body text, p_idempotency_key text",
            "definition": "CREATE OR REPLACE FUNCTION public.admin_send_notification(p_target_type text, p_target_id uuid, p_title text, p_body text, p_idempotency_key text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare v_admin uuid; v_campaign public.admin_notification_campaign; v_event public.notification_event;\n  v_count integer; v_type text; v_profile public.customer_profile;\nbegin\n  if not public.has_admin_permission('notifications.send') then raise exception 'FORBIDDEN'; end if;\n  if nullif(trim(p_title),'') is null or length(trim(p_title))>160 or nullif(trim(p_body),'') is null or length(trim(p_body))>4000 then raise exception 'INVALID_NOTIFICATION'; end if;\n  if lower(coalesce(p_target_type,'')) not in ('all','all_subscribers','user','subscriber') then raise exception 'INVALID_TARGET_TYPE'; end if;\n  if lower(p_target_type) in ('user','subscriber') and p_target_id is null then raise exception 'TARGET_REQUIRED'; end if;\n  v_admin:=public.current_admin_id();\n  v_type:=upper(trim(p_target_type));\n  if v_type='USER' then\n    select * into v_profile from public.customer_profile where id=p_target_id and account_type='USER' and account_status='ACTIVE';\n    if v_profile.id is null then raise exception 'TARGET_NOT_FOUND'; end if;\n  elsif v_type='SUBSCRIBER' then\n    select * into v_profile from public.customer_profile where id=p_target_id and account_type='SUBSCRIBER' and account_status='ACTIVE';\n    if v_profile.id is null then raise exception 'TARGET_NOT_FOUND'; end if;\n  end if;\n  insert into public.admin_notification_campaign(created_by,target_type,target_definition,title,body,status,sent_at)\n  values(v_admin,v_type,jsonb_build_object('target_id',p_target_id),trim(p_title),trim(p_body),'SENT',now()) returning * into v_campaign;\n  insert into public.notification_event(event_type,source_type,source_id)\n  values('ADMIN_CAMPAIGN_SENT','admin_notification_campaign',v_campaign.id) returning * into v_event;\n  with recipients as (\n    select id from public.customer_profile where account_status='ACTIVE' and (\n      v_type='ALL' or (v_type='ALL_SUBSCRIBERS' and account_type='SUBSCRIBER') or\n      (v_type='USER' and id=p_target_id) or (v_type='SUBSCRIBER' and id=p_target_id)\n    )\n  ), ins as (\n    insert into public.admin_notification_recipient(campaign_id,customer_id,delivery_status)\n    select v_campaign.id,id,'SENT' from recipients returning customer_id\n  ), notifications as (\n    insert into public.customer_notification(customer_id,event_id,notification_type,title,body,reference_type,reference_id)\n    select customer_id,v_event.id,'ADMIN_CAMPAIGN',v_campaign.title,v_campaign.body,'admin_notification_campaign',v_campaign.id from ins\n    returning id\n  ) select count(*) into v_count from ins;\n  if coalesce(v_count,0)=0 then raise exception 'NO_RECIPIENTS'; end if;\n  perform public.admin_record_change('SEND_ADMIN_NOTIFICATION','admin_notification_campaign',v_campaign.id,'notifications.send',null,to_jsonb(v_campaign),null,p_idempotency_key);\n  return jsonb_build_object('campaign_id',v_campaign.id,'status',v_campaign.status,'recipient_count',v_count,'event_id',v_event.id);\nend $function$\n",
            "return_type": "jsonb",
            "security_definer": true
        },
        {
            "name": "admin_send_support_reply",
            "schema": "public",
            "language": "plpgsql",
            "arguments": "p_conversation_id uuid, p_body text, p_idempotency_key text",
            "definition": "CREATE OR REPLACE FUNCTION public.admin_send_support_reply(p_conversation_id uuid, p_body text, p_idempotency_key text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare v_conversation public.support_conversation; v_message public.support_message;\nbegin\n  if not public.has_admin_permission('support.write') then raise exception 'FORBIDDEN'; end if;\n  if nullif(trim(p_body),'') is null then raise exception 'MESSAGE_REQUIRED'; end if;\n  select * into v_conversation from public.support_conversation where id=p_conversation_id for update;\n  if v_conversation.id is null then raise exception 'CONVERSATION_NOT_FOUND'; end if;\n  if v_conversation.status<>'OPEN' then raise exception 'CONVERSATION_CLOSED'; end if;\n  insert into public.support_message(conversation_id,sender_type,sender_id,body)\n  values(p_conversation_id,'ADMIN',public.current_admin_id(),trim(p_body)) returning * into v_message;\n  update public.support_conversation set updated_at=now() where id=p_conversation_id;\n  perform public.admin_record_change('SEND_SUPPORT_REPLY','support_conversation',p_conversation_id,'support.write',null,to_jsonb(v_message),null,p_idempotency_key);\n  return to_jsonb(v_message);\nend $function$\n",
            "return_type": "jsonb",
            "security_definer": true
        },
        {
            "name": "admin_set_customer_number_status",
            "schema": "public",
            "language": "plpgsql",
            "arguments": "p_customer_number_id uuid, p_status text, p_reason text, p_idempotency_key text",
            "definition": "CREATE OR REPLACE FUNCTION public.admin_set_customer_number_status(p_customer_number_id uuid, p_status text, p_reason text, p_idempotency_key text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare v_row public.customer_number; v_before jsonb;\nbegin\n  if not public.has_admin_permission('numbers.update') then raise exception 'FORBIDDEN'; end if;\n  if upper(coalesce(p_status,'')) not in ('ACTIVE','INACTIVE','ARCHIVED') then raise exception 'INVALID_NUMBER_STATUS'; end if;\n  select * into v_row from public.customer_number where id=p_customer_number_id for update;\n  if v_row.id is null then raise exception 'CUSTOMER_NUMBER_NOT_FOUND'; end if;\n  v_before:=to_jsonb(v_row);\n  update public.customer_number set status=upper(p_status)::public.customer_number_status, updated_at=now()\n    where id=v_row.id returning * into v_row;\n  perform public.admin_record_change('SET_CUSTOMER_NUMBER_STATUS','customer_number',v_row.id,'numbers.update',v_before,to_jsonb(v_row),p_reason,p_idempotency_key);\n  return to_jsonb(v_row);\nend $function$\n",
            "return_type": "jsonb",
            "security_definer": true
        },
        {
            "name": "admin_update_customer_profile",
            "schema": "public",
            "language": "plpgsql",
            "arguments": "p_customer_id uuid, p_name text, p_email text, p_account_status text, p_reason text, p_idempotency_key text",
            "definition": "CREATE OR REPLACE FUNCTION public.admin_update_customer_profile(p_customer_id uuid, p_name text, p_email text, p_account_status text, p_reason text, p_idempotency_key text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare v_row public.customer_profile; v_before jsonb; v_permission text;\nbegin\n  select * into v_row from public.customer_profile where id=p_customer_id for update;\n  if v_row.id is null then raise exception 'CUSTOMER_NOT_FOUND'; end if;\n  v_permission := case when v_row.account_type='SUBSCRIBER' then 'customers.update' else 'users.update' end;\n  if not public.has_admin_permission(v_permission) then raise exception 'FORBIDDEN'; end if;\n  if nullif(trim(p_name),'') is null then raise exception 'NAME_REQUIRED'; end if;\n  if upper(coalesce(p_account_status,'')) not in ('ACTIVE','SUSPENDED','DISABLED') then raise exception 'INVALID_ACCOUNT_STATUS'; end if;\n  v_before := to_jsonb(v_row);\n  update public.customer_profile set name=trim(p_name), email=nullif(trim(p_email),''),\n    account_status=upper(p_account_status)::public.account_status, updated_at=now()\n  where id=p_customer_id returning * into v_row;\n  perform public.admin_record_change('UPDATE_CUSTOMER_PROFILE','customer_profile',v_row.id,v_permission,v_before,to_jsonb(v_row),p_reason,p_idempotency_key);\n  return to_jsonb(v_row);\nend $function$\n",
            "return_type": "jsonb",
            "security_definer": true
        },
        {
            "name": "approve_points_purchase",
            "schema": "public",
            "language": "plpgsql",
            "arguments": "p_purchase_id uuid, p_idempotency_key text",
            "definition": "CREATE OR REPLACE FUNCTION public.approve_points_purchase(p_purchase_id uuid, p_idempotency_key text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare\n  v_purchase public.points_purchase;\n  v_balance public.points_balance;\n  v_subscriber public.subscriber_identity;\n  v_customer public.customer_profile;\n  v_admin uuid;\n  v_operation uuid;\nbegin\n  if not public.has_admin_permission('points_purchases.approve') then\n    raise exception 'FORBIDDEN';\n  end if;\n\n  if nullif(trim(p_idempotency_key),'') is null then\n    raise exception 'IDEMPOTENCY_KEY_REQUIRED';\n  end if;\n\n  select * into v_purchase\n  from public.points_purchase\n  where id=p_purchase_id\n  for update;\n\n  if v_purchase.id is null then raise exception 'PURCHASE_NOT_FOUND'; end if;\n  if v_purchase.status <> 'PENDING' then raise exception 'PURCHASE_NOT_PENDING'; end if;\n\n  select * into v_customer\n  from public.customer_profile\n  where id=v_purchase.customer_id\n  for update;\n\n  insert into public.points_balance(customer_id)\n  values(v_customer.id)\n  on conflict(customer_id) do nothing;\n\n  select * into v_balance\n  from public.points_balance\n  where customer_id=v_customer.id\n  for update;\n\n  update public.points_purchase\n  set status='APPROVED',\n      reviewed_at=now(),\n      reviewed_by=public.current_admin_id(),\n      updated_at=now()\n  where id=v_purchase.id\n  returning * into v_purchase;\n\n  if not exists(\n    select 1 from public.subscriber_identity\n    where customer_profile_id=v_customer.id\n  ) then\n    insert into public.subscriber_identity(\n      customer_profile_id,public_subscriber_code\n    )\n    values(v_customer.id,public.generate_public_code('S'))\n    returning * into v_subscriber;\n  else\n    select * into v_subscriber\n    from public.subscriber_identity\n    where customer_profile_id=v_customer.id;\n  end if;\n\n  update public.customer_profile\n  set account_type='SUBSCRIBER',updated_at=now()\n  where id=v_customer.id;\n\n  insert into public.points_ledger(\n    customer_id,direction,amount,balance_before,balance_after,\n    entry_type,source_type,source_id,description,created_by\n  )\n  values(\n    v_customer.id,'CREDIT',v_purchase.points_snapshot,\n    v_balance.balance,v_balance.balance+v_purchase.points_snapshot,\n    'PURCHASE_CREDIT','points_purchase',v_purchase.id,\n    'Approved points purchase',public.current_admin_id()\n  );\n\n  update public.points_balance\n  set balance=balance+v_purchase.points_snapshot,updated_at=now()\n  where id=v_balance.id;\n\n  insert into public.financial_ledger(\n    entry_type,direction,amount,currency,source_type,source_id,\n    description,created_by\n  )\n  values(\n    'POINTS_SALE','INFLOW',v_purchase.price_snapshot,v_purchase.currency_snapshot,\n    'points_purchase',v_purchase.id,'Approved points purchase',public.current_admin_id()\n  );\n\n  insert into public.financial_account(currency,balance)\n  values(v_purchase.currency_snapshot,v_purchase.price_snapshot)\n  on conflict(currency)\n  do update set balance=public.financial_account.balance+excluded.balance,\n                updated_at=now();\n\n  insert into public.operation(\n    operation_key,operation_type,actor_type,actor_id,\n    entity_type,entity_id,status,idempotency_key,completed_at\n  )\n  values(\n    public.generate_public_code('OP'),'APPROVE_PURCHASE','ADMIN',\n    public.current_admin_id(),'points_purchase',v_purchase.id,\n    'COMPLETED',p_idempotency_key,now()\n  )\n  returning id into v_operation;\n\n  insert into public.notification_event(event_type,source_type,source_id)\n  values('POINTS_PURCHASE_APPROVED','points_purchase',v_purchase.id);\n\n  insert into public.audit_log(\n    actor_type,actor_id,operation_id,entity_type,entity_id,action,\n    permission_code,after_state\n  )\n  values(\n    'ADMIN',public.current_admin_id(),v_operation,\n    'points_purchase',v_purchase.id,'APPROVE_PURCHASE',\n    'points_purchases.approve',to_jsonb(v_purchase)\n  );\n\n  return jsonb_build_object(\n    'purchase_id',v_purchase.id,\n    'status',v_purchase.status,\n    'subscriber_id',v_subscriber.id,\n    'balance',v_balance.balance+v_purchase.points_snapshot\n  );\nend;\n$function$\n",
            "return_type": "jsonb",
            "security_definer": true
        },
        {
            "name": "close_support_conversation",
            "schema": "public",
            "language": "plpgsql",
            "arguments": "p_conversation_id uuid",
            "definition": "CREATE OR REPLACE FUNCTION public.close_support_conversation(p_conversation_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare v_customer_id uuid;\nbegin\n  v_customer_id:=public.current_customer_profile_id();\n  if v_customer_id is null then raise exception 'CUSTOMER_NOT_FOUND'; end if;\n  update public.support_conversation set status='CLOSED',closed_at=coalesce(closed_at,now()),closed_by=v_customer_id,updated_at=now()\n    where id=p_conversation_id and customer_id=v_customer_id and status='OPEN';\n  if not found then raise exception 'SUPPORT_CONVERSATION_NOT_OPEN_OR_OWNED'; end if;\n  return jsonb_build_object('conversation_id',p_conversation_id,'status','CLOSED');\nend $function$\n",
