        {
            "name": "delete_customer_number",
            "schema": "public",
            "language": "plpgsql",
            "arguments": "p_customer_number_id uuid, p_idempotency_key text",
            "definition": "CREATE OR REPLACE FUNCTION public.delete_customer_number(p_customer_number_id uuid, p_idempotency_key text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare v_customer_id uuid; v_number public.customer_number; v_op uuid; v_before jsonb;\nbegin\n  v_customer_id:=public.current_customer_profile_id();\n  if v_customer_id is null then raise exception 'CUSTOMER_NOT_FOUND'; end if;\n  if nullif(trim(p_idempotency_key),'') is null then raise exception 'IDEMPOTENCY_KEY_REQUIRED'; end if;\n  select o.id into v_op from public.operation_idempotency i join public.operation o on o.id=i.operation_id\n    where i.actor_id=v_customer_id and i.operation_type='ARCHIVE_CUSTOMER_NUMBER' and i.idempotency_key=p_idempotency_key;\n  if v_op is not null then return jsonb_build_object('operation_id',v_op,'idempotent',true); end if;\n  select * into v_number from public.customer_number where id=p_customer_number_id and customer_id=v_customer_id for update;\n  if v_number.id is null then raise exception 'CUSTOMER_NUMBER_NOT_FOUND'; end if;\n  if exists(select 1 from public.number_protection_identity where customer_number_id=v_number.id) then raise exception 'NUMBER_HAS_PROTECTION_HISTORY'; end if;\n  v_before:=jsonb_build_object('status',v_number.status::text);\n  update public.customer_number set status='ARCHIVED',updated_at=now() where id=v_number.id;\n  insert into public.operation(operation_key,operation_type,actor_type,actor_id,entity_type,entity_id,status,idempotency_key,result_reference,completed_at)\n    values(public.generate_public_code('OP'),'ARCHIVE_CUSTOMER_NUMBER','CUSTOMER',v_customer_id,'customer_number',v_number.id,'COMPLETED',p_idempotency_key,v_number.id::text,now()) returning id into v_op;\n  insert into public.operation_idempotency(actor_id,operation_type,idempotency_key,operation_id) values(v_customer_id,'ARCHIVE_CUSTOMER_NUMBER',p_idempotency_key,v_op);\n  insert into public.audit_log(actor_type,actor_id,operation_id,entity_type,entity_id,action,before_state,after_state)\n    values('CUSTOMER',v_customer_id,v_op,'customer_number',v_number.id,'ARCHIVE',v_before,jsonb_build_object('status','ARCHIVED'));\n  return jsonb_build_object('customer_number_id',v_number.id,'status','ARCHIVED','operation_id',v_op);\nend $function$\n",
            "return_type": "jsonb",
            "security_definer": true
        },
        {
            "name": "ensure_auth_account",
            "schema": "public",
            "language": "plpgsql",
            "arguments": "",
            "definition": "CREATE OR REPLACE FUNCTION public.ensure_auth_account()\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare v_id uuid;\nbegin\n  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;\n\n  insert into public.auth_account(auth_user_id)\n  values(auth.uid())\n  on conflict(auth_user_id) do update set updated_at=now()\n  returning id into v_id;\n\n  return v_id;\nend;\n$function$\n",
            "return_type": "uuid",
            "security_definer": true
        },
        {
            "name": "extend_protection",
            "schema": "public",
            "language": "plpgsql",
            "arguments": "p_protection_period_id uuid, p_tariff_id uuid, p_units integer, p_idempotency_key text",
            "definition": "CREATE OR REPLACE FUNCTION public.extend_protection(p_protection_period_id uuid, p_tariff_id uuid, p_units integer, p_idempotency_key text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare\n  v_customer_id uuid; v_period public.protection_period; v_number public.customer_number; v_company_id uuid;\n  v_tariff public.protection_tariff; v_balance public.points_balance; v_days bigint; v_cost bigint;\n  v_old_end timestamptz; v_new_end timestamptz; v_extension uuid; v_op uuid; v_event uuid;\nbegin\n  v_customer_id:=public.current_customer_profile_id();\n  if v_customer_id is null then raise exception 'CUSTOMER_NOT_FOUND'; end if;\n  if p_units is null or p_units<1 or p_units>120 then raise exception 'INVALID_TARIFF_UNITS'; end if;\n  if nullif(trim(p_idempotency_key),'') is null then raise exception 'IDEMPOTENCY_KEY_REQUIRED'; end if;\n  if not exists(select 1 from public.subscriber_identity where customer_profile_id=v_customer_id) then raise exception 'SUBSCRIPTION_REQUIRED'; end if;\n  select o.id into v_op from public.operation_idempotency i join public.operation o on o.id=i.operation_id\n    where i.actor_id=v_customer_id and i.operation_type='EXTEND_PROTECTION' and i.idempotency_key=p_idempotency_key;\n  if v_op is not null then return jsonb_build_object('operation_id',v_op,'idempotent',true); end if;\n  select * into v_period from public.protection_period where id=p_protection_period_id and customer_id=v_customer_id for update;\n  if v_period.id is null then raise exception 'PROTECTION_NOT_FOUND'; end if;\n  if v_period.status<>'ACTIVE' or v_period.end_at<=now() then raise exception 'PROTECTION_NOT_ACTIVE'; end if;\n  select cn.* into v_number from public.customer_number cn join public.number_protection_identity ni on ni.customer_number_id=cn.id\n    where ni.id=v_period.protection_identity_id and cn.customer_id=v_customer_id and cn.status='ACTIVE' for update of cn;\n  if v_number.id is null then raise exception 'CUSTOMER_NUMBER_NOT_FOUND_OR_INACTIVE'; end if;\n  select pn.telecom_company_id into v_company_id from public.phone_number pn where pn.id=v_number.phone_number_id;\n  select * into v_tariff from public.protection_tariff where id=p_tariff_id and telecom_company_id=v_company_id\n    and status='ACTIVE' and effective_from<=now() and (effective_to is null or effective_to>now()) for share;\n  if v_tariff.id is null then raise exception 'TARIFF_NOT_AVAILABLE'; end if;\n  if v_tariff.points_per_unit is null or v_tariff.points_per_unit<=0 then raise exception 'TARIFF_POINTS_NOT_CONFIGURED'; end if;\n  v_days:=p_units::bigint*v_tariff.duration_unit_days::bigint; v_cost:=p_units::bigint*v_tariff.points_per_unit;\n  if v_days<=0 or v_days>3650000 or v_cost<=0 then raise exception 'INVALID_TARIFF_TOTAL'; end if;\n  insert into public.points_balance(customer_id,balance) values(v_customer_id,0) on conflict(customer_id) do nothing;\n  select * into v_balance from public.points_balance where customer_id=v_customer_id for update;\n  if v_balance.balance<v_cost then raise exception 'INSUFFICIENT_POINTS'; end if;\n  v_old_end:=v_period.end_at; v_new_end:=v_old_end+make_interval(days=>v_days::integer);\n  update public.points_balance set balance=balance-v_cost,updated_at=now() where id=v_balance.id;\n  update public.protection_period set end_at=v_new_end,duration_days=duration_days+v_days::integer,updated_at=now() where id=v_period.id;\n  insert into public.operation(operation_key,operation_type,actor_type,actor_id,entity_type,entity_id,status,idempotency_key,result_reference,completed_at)\n    values(public.generate_public_code('OP'),'EXTEND_PROTECTION','CUSTOMER',v_customer_id,'protection_period',v_period.id,'COMPLETED',p_idempotency_key,v_period.id::text,now()) returning id into v_op;\n  insert into public.protection_extension(protection_period_id,days_added,tariff_mode_snapshot,tariff_value_snapshot,\n    currency_snapshot,points_cost,balance_before,balance_after,operation_id,tariff_id,units_added,duration_unit_days_snapshot,points_per_unit_snapshot)\n    values(v_period.id,v_days::integer,v_tariff.tariff_mode,v_tariff.rate,v_tariff.currency,v_cost,\n      v_balance.balance,v_balance.balance-v_cost,v_op,v_tariff.id,p_units,v_tariff.duration_unit_days,v_tariff.points_per_unit)\n    returning id into v_extension;\n  insert into public.operation_idempotency(actor_id,operation_type,idempotency_key,operation_id)\n    values(v_customer_id,'EXTEND_PROTECTION',p_idempotency_key,v_op);\n  insert into public.points_ledger(customer_id,direction,amount,balance_before,balance_after,entry_type,source_type,source_id,description,created_by)\n    values(v_customer_id,'DEBIT',v_cost,v_balance.balance,v_balance.balance-v_cost,'EXTENSION_DEBIT','protection_extension',v_extension,\n      'تمديد الحماية '||p_units||' وحدة / '||v_days||' يومًا',v_customer_id);\n  insert into public.audit_log(actor_type,actor_id,operation_id,entity_type,entity_id,action,before_state,after_state)\n    values('CUSTOMER',v_customer_id,v_op,'protection_period',v_period.id,'EXTEND',jsonb_build_object('end_at',v_old_end),\n      jsonb_build_object('end_at',v_new_end,'units',p_units,'duration_days',v_days,'points_cost',v_cost,'balance_after',v_balance.balance-v_cost));\n  insert into public.notification_event(event_type,source_type,source_id) values('PROTECTION_EXTENDED','protection_period',v_period.id) returning id into v_event;\n  insert into public.customer_notification(customer_id,event_id,notification_type,title,body,reference_type,reference_id)\n    values(v_customer_id,v_event,'PROTECTION','تم تمديد الحماية','تم تمديد فترة الحماية للرقم المرتبط بحسابك.','protection_period',v_period.id);\n  return jsonb_build_object('protection_period_id',v_period.id,'extension_id',v_extension,'end_at',v_new_end,\n    'units',p_units,'duration_unit_days',v_tariff.duration_unit_days,'duration_days',v_days,\n    'points_per_unit',v_tariff.points_per_unit,'points_cost',v_cost,'balance_after',v_balance.balance-v_cost,'operation_id',v_op);\nend $function$\n",
            "return_type": "jsonb",
            "security_definer": true
        },
        {
            "name": "generate_public_code",
            "schema": "public",
            "language": "plpgsql",
            "arguments": "p_prefix text",
            "definition": "CREATE OR REPLACE FUNCTION public.generate_public_code(p_prefix text)\n RETURNS text\n LANGUAGE plpgsql\nAS $function$\nbegin\n  return upper(coalesce(p_prefix,'X')) || '-' ||\n         to_char(clock_timestamp(),'YYMMDDHH24MISSMS') || '-' ||\n         upper(substr(replace(gen_random_uuid()::text,'-',''),1,6));\nend;\n$function$\n",
            "return_type": "text",
            "security_definer": false
        },
        {
            "name": "get_customer_screen_data",
            "schema": "public",
            "language": "plpgsql",
            "arguments": "p_screen_id text, p_query text DEFAULT NULL::text",
            "definition": "CREATE OR REPLACE FUNCTION public.get_customer_screen_data(p_screen_id text, p_query text DEFAULT NULL::text)\n RETURNS jsonb\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare\n  v_customer_id uuid;\n  v_profile jsonb;\n  v_balance jsonb;\n  v_numbers jsonb;\n  v_candidates jsonb;\n  v_protections jsonb;\n  v_tariffs jsonb;\n  v_prefixes jsonb;\n  v_packages jsonb;\n  v_methods jsonb;\n  v_purchases jsonb;\n  v_ledger jsonb;\n  v_operations jsonb;\n  v_notifications jsonb;\n  v_threads jsonb;\n  v_messages jsonb;\n  v_admin_messages jsonb;\n  v_content jsonb;\n  v_maintenance jsonb;\nbegin\n  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;\n  if p_screen_id not in ('C04','C05','C06','C07','C08','C09','C10','C11','C12','C13','C14','C15','C16','C17','C18','C19') then\n    raise exception 'INVALID_CUSTOMER_SCREEN';\n  end if;\n  v_customer_id := public.current_customer_profile_id();\n  if v_customer_id is null then raise exception 'CUSTOMER_NOT_FOUND'; end if;\n\n  select coalesce(jsonb_agg(to_jsonb(cp) - 'auth_account_id'), '[]'::jsonb) into v_profile\n  from public.customer_profile cp where cp.id=v_customer_id;\n  select coalesce(jsonb_agg(jsonb_build_object('balance',pb.balance,'updated_at',pb.updated_at)), '[]'::jsonb) into v_balance\n  from public.points_balance pb where pb.customer_id=v_customer_id;\n\n  select coalesce(jsonb_agg(x.row_data order by x.added_at desc), '[]'::jsonb) into v_numbers\n  from (\n    select cn.added_at,\n      jsonb_build_object(\n        'id',cn.id,'customer_id',cn.customer_id,'phone_number_id',pn.id,\n        'telecom_company_id',pn.telecom_company_id,'public_added_number_code',cn.public_added_number_code,\n        'status',cn.status::text,'added_at',cn.added_at,'updated_at',cn.updated_at,\n        'display_phone',pn.display_phone,'normalized_phone',pn.normalized_phone,\n        'company_name',tc.name,\n        'active_protection',exists(select 1 from public.number_protection_identity ni\n          join public.protection_period pp on pp.protection_identity_id=ni.id\n          where ni.customer_number_id=cn.id and pp.status='ACTIVE' and pp.end_at>now())\n      ) as row_data\n    from public.customer_number cn\n    join public.phone_number pn on pn.id=cn.phone_number_id\n    join public.telecom_company tc on tc.id=pn.telecom_company_id\n    where cn.customer_id=v_customer_id\n    order by cn.added_at desc limit 500\n  ) x;\n\n  select coalesce(jsonb_agg(x.row_data order by x.added_at desc), '[]'::jsonb) into v_candidates\n  from (\n    select cn.added_at,\n      jsonb_build_object('id',cn.id,'customer_number_id',cn.id,'customer_id',cn.customer_id,\n        'telecom_company_id',pn.telecom_company_id,'public_added_number_code',cn.public_added_number_code,\n        'display_phone',pn.display_phone,'normalized_phone',pn.normalized_phone,'company_name',tc.name,'status',cn.status::text) as row_data\n    from public.customer_number cn\n    join public.phone_number pn on pn.id=cn.phone_number_id\n    join public.telecom_company tc on tc.id=pn.telecom_company_id\n    where cn.customer_id=v_customer_id and cn.status='ACTIVE'\n      and not exists(select 1 from public.number_protection_identity ni\n        join public.protection_period pp on pp.protection_identity_id=ni.id\n        where ni.customer_number_id=cn.id and pp.status='ACTIVE' and pp.end_at>now())\n    order by cn.added_at desc limit 500\n  ) x;\n\n  select coalesce(jsonb_agg(x.row_data order by x.start_at desc), '[]'::jsonb) into v_protections\n  from (\n    select pp.start_at,\n      jsonb_build_object('id',pp.id,'protection_identity_id',ni.id,'customer_number_id',cn.id,\n        'telecom_company_id',pn.telecom_company_id,'public_activation_code',ni.public_activation_code,\n        'display_phone',pn.display_phone,'normalized_phone',pn.normalized_phone,'company_name',tc.name,\n        'status',case when pp.end_at<=now() then 'EXPIRED' else pp.status::text end,\n        'effective_status',case when pp.end_at<=now() then 'EXPIRED' else pp.status::text end,\n        'start_at',pp.start_at,'end_at',pp.end_at,'duration_days',pp.duration_days,\n        'tariff_id',pp.tariff_id,'tariff_mode_snapshot',pp.tariff_mode_snapshot::text,\n        'tariff_value_snapshot',pp.tariff_value_snapshot,'currency_snapshot',pp.currency_snapshot,\n        'points_cost_snapshot',pp.points_cost_snapshot,'units_snapshot',pp.units_snapshot,\n        'duration_unit_days_snapshot',pp.duration_unit_days_snapshot,\n        'points_per_unit_snapshot',pp.points_per_unit_snapshot)\n      as row_data\n    from public.protection_period pp\n    join public.number_protection_identity ni on ni.id=pp.protection_identity_id\n    join public.customer_number cn on cn.id=ni.customer_number_id\n    join public.phone_number pn on pn.id=cn.phone_number_id\n    join public.telecom_company tc on tc.id=pn.telecom_company_id\n    where pp.customer_id=v_customer_id\n    order by pp.start_at desc limit 500\n  ) x;\n\n  select coalesce(jsonb_agg(jsonb_build_object('id',t.id,'telecom_company_id',t.telecom_company_id,\n    'tariff_mode',t.tariff_mode::text,'duration_unit_days',t.duration_unit_days,\n    'points_per_unit',t.points_per_unit,'rate',t.rate,'currency',t.currency,\n    'effective_from',t.effective_from,'effective_to',t.effective_to,'status',t.status::text,\n    'company_name',tc.name) order by tc.name,t.duration_unit_days), '[]'::jsonb) into v_tariffs\n  from public.protection_tariff t\n  join public.telecom_company tc on tc.id=t.telecom_company_id\n  where t.status='ACTIVE' and t.effective_from<=now() and (t.effective_to is null or t.effective_to>now())\n    and t.telecom_company_id in (select pn.telecom_company_id from public.customer_number cn\n      join public.phone_number pn on pn.id=cn.phone_number_id where cn.customer_id=v_customer_id);\n\n  select coalesce(jsonb_agg(jsonb_build_object('id',tp.id,'telecom_company_id',tp.telecom_company_id,\n    'prefix',tp.prefix,'status',tp.status::text,'telecom_company',jsonb_build_object('name',tc.name))), '[]'::jsonb) into v_prefixes\n  from public.telecom_prefix tp join public.telecom_company tc on tc.id=tp.telecom_company_id\n  where tp.status='ACTIVE' and tc.status='ACTIVE';\n\n  select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'code',p.code,'name',p.name,\n    'points',p.points,'price',p.price,'currency',p.currency,'display_order',p.display_order)\n    order by p.display_order,p.name), '[]'::jsonb) into v_packages\n  from public.points_package p where p.is_active=true and p.is_visible=true;\n  select coalesce(jsonb_agg(jsonb_build_object('id',m.id,'code',m.code,'name',m.name,'type',m.type,\n    'receiving_account',m.receiving_account,'transfer_instructions',m.transfer_instructions)\n    order by m.display_order,m.name), '[]'::jsonb) into v_methods\n  from public.payment_method m where m.is_active=true and m.is_visible=true;\n\n  select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'public_purchase_code',p.public_purchase_code,\n    'package_name_snapshot',p.package_name_snapshot,'points_snapshot',p.points_snapshot,\n    'price_snapshot',p.price_snapshot,'currency_snapshot',p.currency_snapshot,\n    'payment_method_name_snapshot',p.payment_method_name_snapshot,'transfer_reference',p.transfer_reference,\n    'status',p.status::text,'rejection_reason',p.rejection_reason,'submitted_at',p.submitted_at)\n    order by p.submitted_at desc), '[]'::jsonb) into v_purchases\n  from (select * from public.points_purchase where customer_id=v_customer_id order by submitted_at desc limit 500) p;\n\n  select coalesce(jsonb_agg(jsonb_build_object('id',l.id,'direction',l.direction::text,'amount',l.amount,\n    'balance_before',l.balance_before,'balance_after',l.balance_after,'entry_type',l.entry_type::text,\n    'source_type',l.source_type,'source_id',l.source_id,'description',l.description,'created_at',l.created_at)\n    order by l.created_at desc), '[]'::jsonb) into v_ledger\n  from (select * from public.points_ledger where customer_id=v_customer_id order by created_at desc limit 1000) l;\n\n  select coalesce(jsonb_agg(jsonb_build_object('id',o.id,'operation_type',o.operation_type,\n    'entity_type',o.entity_type,'entity_id',o.entity_id,'status',o.status::text,\n    'result_reference',o.result_reference,'created_at',o.created_at,'completed_at',o.completed_at)\n    order by o.created_at desc), '[]'::jsonb) into v_operations\n  from (select * from public.operation where actor_type='CUSTOMER' and actor_id=v_customer_id order by created_at desc limit 100) o;\n\n  select coalesce(jsonb_agg(jsonb_build_object('id',n.id,'notification_type',n.notification_type,\n    'title',n.title,'body',n.body,'reference_type',n.reference_type,'reference_id',n.reference_id,\n    'is_read',n.is_read,'created_at',n.created_at,'read_at',n.read_at) order by n.created_at desc), '[]'::jsonb) into v_notifications\n  from (select * from public.customer_notification where customer_id=v_customer_id order by created_at desc limit 500) n;\n\n  select coalesce(jsonb_agg(jsonb_build_object('id',c.id,'subject',c.subject,'status',c.status::text,\n    'created_at',c.created_at,'updated_at',c.updated_at,'closed_at',c.closed_at) order by c.updated_at desc), '[]'::jsonb) into v_threads\n  from (select * from public.support_conversation where customer_id=v_customer_id order by updated_at desc limit 200) c;\n  select coalesce(jsonb_agg(jsonb_build_object('id',m.id,'conversation_id',m.conversation_id,\n    'sender_type',m.sender_type::text,'body',m.body,'sent_at',m.sent_at,'read_at',m.read_at)\n    order by m.sent_at), '[]'::jsonb) into v_messages\n  from public.support_message m join public.support_conversation c on c.id=m.conversation_id\n  where c.customer_id=v_customer_id;\n\n  select coalesce(jsonb_agg(jsonb_build_object('id',m.id,'thread_id',m.thread_id,\n    'title','رسالة من إدارة أمان','body',m.body,'sent_at',m.sent_at,'read_at',m.read_at,\n    'is_read',m.read_at is not null) order by m.sent_at desc), '[]'::jsonb) into v_admin_messages\n  from public.admin_message m join public.admin_message_thread t on t.id=m.thread_id\n  where t.customer_id=v_customer_id;\n\n  select coalesce(jsonb_agg(jsonb_build_object('id',c.id,'content_key',c.content_key,\n    'version',c.version,'title',c.title,'body',c.body,'published_at',c.published_at)\n    order by c.content_key), '[]'::jsonb) into v_content\n  from (select distinct on (content_key) * from public.app_content\n    where status='ACTIVE' and content_key in ('ABOUT','TERMS','PRIVACY')\n    order by content_key,version desc) c;\n  select coalesce(jsonb_agg(jsonb_build_object('id',m.id,'enabled',m.enabled,'customer_message',m.customer_message,\n    'updated_at',m.updated_at) order by m.updated_at desc), '[]'::jsonb) into v_maintenance\n  from (select * from public.maintenance_config order by updated_at desc limit 1) m;\n\n  return jsonb_build_object(\n    'profile',v_profile,'balance',v_balance,'numbers',v_numbers,'candidates',v_candidates,\n    'protections',v_protections,'tariffs',v_tariffs,'prefixes',v_prefixes,\n    'packages',v_packages,'methods',v_methods,'purchases',v_purchases,'ledger',v_ledger,\n    'operations',v_operations,'notifications',v_notifications,'threads',v_threads,\n    'messages',v_messages,'admin_messages',v_admin_messages,'content',v_content,'maintenance',v_maintenance\n  );\nend;\n$function$\n",
            "return_type": "jsonb",
            "security_definer": true
        },
        {
            "name": "get_public_content",
            "schema": "public",
            "language": "sql",
            "arguments": "p_content_key text DEFAULT 'ALL'::text",
            "definition": "CREATE OR REPLACE FUNCTION public.get_public_content(p_content_key text DEFAULT 'ALL'::text)\n RETURNS jsonb\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\n  select jsonb_build_object('content',coalesce(jsonb_agg(jsonb_build_object(\n    'id',c.id,'content_key',c.content_key,'version',c.version,'title',c.title,'body',c.body,'published_at',c.published_at\n  ) order by c.content_key),'[]'::jsonb))\n  from (select distinct on (content_key) * from public.app_content\n    where status='ACTIVE'\n      and (upper(coalesce(p_content_key,'ALL'))='ALL' or content_key=upper(p_content_key))\n      and content_key in ('ABOUT','TERMS','PRIVACY')\n    order by content_key,version desc) c\n$function$\n",
            "return_type": "jsonb",
            "security_definer": true
        },
        {
            "name": "has_admin_permission",
            "schema": "public",
            "language": "sql",
            "arguments": "p_permission text",
            "definition": "CREATE OR REPLACE FUNCTION public.has_admin_permission(p_permission text)\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\n  select exists(\n    select 1\n    from public.admin_identity ai\n    join public.auth_account aa on aa.id = ai.auth_account_id\n    join public.admin_assignments ass on ass.admin_id = ai.id and ass.status = 'ACTIVE'\n    join public.role_permissions rp on rp.role_id = ass.role_id\n    join public.permissions p on p.id = rp.permission_id and p.status = 'ACTIVE'\n    where aa.auth_user_id = auth.uid()\n      and ai.status = 'ACTIVE'\n      and p.code = p_permission\n  );\n$function$\n",
            "return_type": "boolean",
            "security_definer": true
        },
        {
            "name": "is_admin",
            "schema": "public",
            "language": "sql",
            "arguments": "",
            "definition": "CREATE OR REPLACE FUNCTION public.is_admin()\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\n  select exists(\n    select 1 from public.admin_identity ai\n    join public.auth_account aa on aa.id = ai.auth_account_id\n    where aa.auth_user_id = auth.uid()\n      and ai.status = 'ACTIVE'\n  );\n$function$\n",
            "return_type": "boolean",
            "security_definer": true
        },
        {
            "name": "mark_admin_message_read",
            "schema": "public",
            "language": "plpgsql",
            "arguments": "p_message_id uuid",
            "definition": "CREATE OR REPLACE FUNCTION public.mark_admin_message_read(p_message_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare v_customer_id uuid;\nbegin\n  v_customer_id:=public.current_customer_profile_id();\n  if v_customer_id is null then raise exception 'CUSTOMER_NOT_FOUND'; end if;\n  update public.admin_message m set read_at=coalesce(m.read_at,now())\n    from public.admin_message_thread t\n    where m.id=p_message_id and t.id=m.thread_id and t.customer_id=v_customer_id;\n  if not found then raise exception 'ADMIN_MESSAGE_NOT_FOUND'; end if;\n  return jsonb_build_object('message_id',p_message_id,'is_read',true);\nend $function$\n",
            "return_type": "jsonb",
            "security_definer": true
        },
        {
            "name": "mark_notification_read",
            "schema": "public",
            "language": "plpgsql",
            "arguments": "p_notification_id uuid",
            "definition": "CREATE OR REPLACE FUNCTION public.mark_notification_read(p_notification_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare\n  v_customer_id uuid;\nbegin\n  select cp.id into v_customer_id\n  from public.customer_profile cp\n  join public.auth_account aa on aa.id=cp.auth_account_id\n  where aa.auth_user_id=auth.uid();\n\n  if v_customer_id is null then raise exception 'CUSTOMER_NOT_FOUND'; end if;\n\n  update public.customer_notification\n  set is_read=true,read_at=coalesce(read_at,now())\n  where id=p_notification_id and customer_id=v_customer_id;\n\n  if not found then raise exception 'NOTIFICATION_NOT_FOUND'; end if;\n\n  return jsonb_build_object('notification_id',p_notification_id,'is_read',true);\nend;\n$function$\n",
            "return_type": "jsonb",
            "security_definer": true
        },
        {
            "name": "normalize_phone",
            "schema": "public",
            "language": "sql",
            "arguments": "p_phone text",
            "definition": "CREATE OR REPLACE FUNCTION public.normalize_phone(p_phone text)\n RETURNS text\n LANGUAGE sql\n IMMUTABLE\nAS $function$\n  select regexp_replace(coalesce(p_phone,''), '[^0-9]+', '', 'g');\n$function$\n",
            "return_type": "text",
            "security_definer": false
        },
        {
            "name": "reject_points_purchase",
            "schema": "public",
            "language": "plpgsql",
            "arguments": "p_purchase_id uuid, p_reason text, p_idempotency_key text",
            "definition": "CREATE OR REPLACE FUNCTION public.reject_points_purchase(p_purchase_id uuid, p_reason text, p_idempotency_key text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare\n  v_purchase public.points_purchase;\n  v_operation uuid;\nbegin\n  if not public.has_admin_permission('points_purchases.reject') then\n    raise exception 'FORBIDDEN';\n  end if;\n\n  if nullif(trim(p_reason),'') is null then\n    raise exception 'REJECTION_REASON_REQUIRED';\n  end if;\n\n  select * into v_purchase\n  from public.points_purchase\n  where id=p_purchase_id\n  for update;\n\n  if v_purchase.id is null then raise exception 'PURCHASE_NOT_FOUND'; end if;\n  if v_purchase.status <> 'PENDING' then raise exception 'PURCHASE_NOT_PENDING'; end if;\n\n  update public.points_purchase\n  set status='REJECTED',\n      rejection_reason=trim(p_reason),\n      reviewed_at=now(),\n      reviewed_by=public.current_admin_id(),\n      updated_at=now()\n  where id=v_purchase.id\n  returning * into v_purchase;\n\n  insert into public.operation(\n    operation_key,operation_type,actor_type,actor_id,\n    entity_type,entity_id,status,idempotency_key,completed_at\n  )\n  values(\n    public.generate_public_code('OP'),'REJECT_PURCHASE','ADMIN',\n    public.current_admin_id(),'points_purchase',v_purchase.id,\n    'COMPLETED',p_idempotency_key,now()\n  )\n  returning id into v_operation;\n\n  insert into public.notification_event(event_type,source_type,source_id)\n  values('POINTS_PURCHASE_REJECTED','points_purchase',v_purchase.id);\n\n  insert into public.audit_log(\n    actor_type,actor_id,operation_id,entity_type,entity_id,action,\n    permission_code,after_state,reason\n  )\n  values(\n    'ADMIN',public.current_admin_id(),v_operation,\n    'points_purchase',v_purchase.id,'REJECT_PURCHASE',\n    'points_purchases.reject',to_jsonb(v_purchase),p_reason\n  );\n\n  return jsonb_build_object(\n    'purchase_id',v_purchase.id,\n    'status',v_purchase.status,\n    'reason',v_purchase.rejection_reason\n  );\nend;\n$function$\n",
            "return_type": "jsonb",
            "security_definer": true
        },
        {
            "name": "renew_protection",
            "schema": "public",
            "language": "plpgsql",
            "arguments": "p_protection_period_id uuid, p_tariff_id uuid, p_units integer, p_idempotency_key text",
            "definition": "CREATE OR REPLACE FUNCTION public.renew_protection(p_protection_period_id uuid, p_tariff_id uuid, p_units integer, p_idempotency_key text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare\n  v_customer_id uuid; v_old public.protection_period; v_number public.customer_number; v_company_id uuid;\n  v_tariff public.protection_tariff; v_balance public.points_balance; v_days bigint; v_cost bigint;\n  v_identity_id uuid; v_new_period uuid; v_start timestamptz:=now(); v_end timestamptz; v_op uuid; v_event uuid;\nbegin\n  v_customer_id:=public.current_customer_profile_id();\n  if v_customer_id is null then raise exception 'CUSTOMER_NOT_FOUND'; end if;\n  if p_units is null or p_units<1 or p_units>120 then raise exception 'INVALID_TARIFF_UNITS'; end if;\n  if nullif(trim(p_idempotency_key),'') is null then raise exception 'IDEMPOTENCY_KEY_REQUIRED'; end if;\n  if not exists(select 1 from public.subscriber_identity where customer_profile_id=v_customer_id) then raise exception 'SUBSCRIPTION_REQUIRED'; end if;\n  select o.id into v_op from public.operation_idempotency i join public.operation o on o.id=i.operation_id\n    where i.actor_id=v_customer_id and i.operation_type='RENEW_PROTECTION' and i.idempotency_key=p_idempotency_key;\n  if v_op is not null then return jsonb_build_object('operation_id',v_op,'idempotent',true); end if;\n  select * into v_old from public.protection_period where id=p_protection_period_id and customer_id=v_customer_id for update;\n  if v_old.id is null then raise exception 'PROTECTION_NOT_FOUND'; end if;\n  if v_old.end_at>now() and v_old.status='ACTIVE' then raise exception 'PROTECTION_NOT_EXPIRED'; end if;\n  v_identity_id:=v_old.protection_identity_id;\n  select cn.* into v_number from public.customer_number cn join public.number_protection_identity ni on ni.customer_number_id=cn.id\n    where ni.id=v_identity_id and cn.customer_id=v_customer_id and cn.status='ACTIVE' for update of cn;\n  if v_number.id is null then raise exception 'CUSTOMER_NUMBER_NOT_FOUND_OR_INACTIVE'; end if;\n  if exists(select 1 from public.protection_period pp where pp.protection_identity_id=v_identity_id and pp.id<>v_old.id and pp.status='ACTIVE' and pp.end_at>now()) then\n    raise exception 'PROTECTION_ALREADY_ACTIVE';\n  end if;\n  select pn.telecom_company_id into v_company_id from public.phone_number pn where pn.id=v_number.phone_number_id;\n  select * into v_tariff from public.protection_tariff where id=p_tariff_id and telecom_company_id=v_company_id\n    and status='ACTIVE' and effective_from<=now() and (effective_to is null or effective_to>now()) for share;\n  if v_tariff.id is null then raise exception 'TARIFF_NOT_AVAILABLE'; end if;\n  if v_tariff.points_per_unit is null or v_tariff.points_per_unit<=0 then raise exception 'TARIFF_POINTS_NOT_CONFIGURED'; end if;\n  v_days:=p_units::bigint*v_tariff.duration_unit_days::bigint; v_cost:=p_units::bigint*v_tariff.points_per_unit;\n  if v_days<=0 or v_days>3650000 or v_cost<=0 then raise exception 'INVALID_TARIFF_TOTAL'; end if;\n  insert into public.points_balance(customer_id,balance) values(v_customer_id,0) on conflict(customer_id) do nothing;\n  select * into v_balance from public.points_balance where customer_id=v_customer_id for update;\n  if v_balance.balance<v_cost then raise exception 'INSUFFICIENT_POINTS'; end if;\n  update public.protection_period set status='EXPIRED',updated_at=now() where id=v_old.id and status='ACTIVE';\n  v_end:=v_start+make_interval(days=>v_days::integer);\n  update public.points_balance set balance=balance-v_cost,updated_at=now() where id=v_balance.id;\n  insert into public.protection_period(protection_identity_id,customer_id,start_at,end_at,duration_days,tariff_id,\n    tariff_mode_snapshot,tariff_value_snapshot,currency_snapshot,points_cost_snapshot,status,\n    units_snapshot,duration_unit_days_snapshot,points_per_unit_snapshot)\n    values(v_identity_id,v_customer_id,v_start,v_end,v_days::integer,v_tariff.id,v_tariff.tariff_mode,\n      v_tariff.rate,v_tariff.currency,v_cost,'ACTIVE',p_units,v_tariff.duration_unit_days,v_tariff.points_per_unit)\n    returning id into v_new_period;\n  insert into public.operation(operation_key,operation_type,actor_type,actor_id,entity_type,entity_id,status,idempotency_key,result_reference,completed_at)\n    values(public.generate_public_code('OP'),'RENEW_PROTECTION','CUSTOMER',v_customer_id,'protection_period',v_new_period,'COMPLETED',p_idempotency_key,v_new_period::text,now()) returning id into v_op;\n  insert into public.operation_idempotency(actor_id,operation_type,idempotency_key,operation_id)\n    values(v_customer_id,'RENEW_PROTECTION',p_idempotency_key,v_op);\n  insert into public.points_ledger(customer_id,direction,amount,balance_before,balance_after,entry_type,source_type,source_id,description,created_by)\n    values(v_customer_id,'DEBIT',v_cost,v_balance.balance,v_balance.balance-v_cost,'RENEWAL_DEBIT','protection_period',v_new_period,\n      'تجديد الحماية '||p_units||' وحدة / '||v_days||' يومًا',v_customer_id);\n  insert into public.audit_log(actor_type,actor_id,operation_id,entity_type,entity_id,action,before_state,after_state)\n    values('CUSTOMER',v_customer_id,v_op,'protection_period',v_new_period,'RENEW',jsonb_build_object('previous_period_id',v_old.id,'previous_end_at',v_old.end_at),\n      jsonb_build_object('units',p_units,'duration_days',v_days,'points_cost',v_cost,'balance_after',v_balance.balance-v_cost));\n  insert into public.notification_event(event_type,source_type,source_id) values('PROTECTION_RENEWED','protection_period',v_new_period) returning id into v_event;\n  insert into public.customer_notification(customer_id,event_id,notification_type,title,body,reference_type,reference_id)\n    values(v_customer_id,v_event,'PROTECTION','تم تجديد الحماية','تم إنشاء فترة حماية جديدة للرقم المرتبط بحسابك.','protection_period',v_new_period);\n  return jsonb_build_object('protection_period_id',v_new_period,'previous_period_id',v_old.id,'status','ACTIVE',\n    'start_at',v_start,'end_at',v_end,'units',p_units,'duration_unit_days',v_tariff.duration_unit_days,\n    'duration_days',v_days,'points_per_unit',v_tariff.points_per_unit,'points_cost',v_cost,\n    'balance_after',v_balance.balance-v_cost,'operation_id',v_op);\nend $function$\n",
            "return_type": "jsonb",
            "security_definer": true
        },
        {
            "name": "rls_auto_enable",
            "schema": "public",
            "language": "plpgsql",
            "arguments": "",
            "definition": "CREATE OR REPLACE FUNCTION public.rls_auto_enable()\n RETURNS event_trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog'\nAS $function$\nDECLARE\n  cmd record;\nBEGIN\n  FOR cmd IN\n    SELECT *\n    FROM pg_event_trigger_ddl_commands()\n    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')\n      AND object_type IN ('table','partitioned table')\n  LOOP\n     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN\n      BEGIN\n        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);\n        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;\n      EXCEPTION\n        WHEN OTHERS THEN\n          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;\n      END;\n     ELSE\n        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;\n     END IF;\n  END LOOP;\nEND;\n$function$\n",
            "return_type": "event_trigger",
            "security_definer": true
        },
        {
            "name": "send_support_message",
            "schema": "public",
            "language": "plpgsql",
            "arguments": "p_conversation_id uuid, p_body text, p_idempotency_key text",
            "definition": "CREATE OR REPLACE FUNCTION public.send_support_message(p_conversation_id uuid, p_body text, p_idempotency_key text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare v_customer_id uuid; v_message uuid; v_op uuid;\nbegin\n  v_customer_id:=public.current_customer_profile_id();\n  if v_customer_id is null then raise exception 'CUSTOMER_NOT_FOUND'; end if;\n  if nullif(trim(p_body),'') is null or length(trim(p_body))>10000 then raise exception 'INVALID_MESSAGE'; end if;\n  if nullif(trim(p_idempotency_key),'') is null then raise exception 'IDEMPOTENCY_KEY_REQUIRED'; end if;\n  select o.id into v_op from public.operation_idempotency i join public.operation o on o.id=i.operation_id\n    where i.actor_id=v_customer_id and i.operation_type='SEND_SUPPORT_MESSAGE' and i.idempotency_key=p_idempotency_key;\n  if v_op is not null then return jsonb_build_object('operation_id',v_op,'idempotent',true); end if;\n  perform 1 from public.support_conversation where id=p_conversation_id and customer_id=v_customer_id and status='OPEN' for update;\n  if not found then raise exception 'SUPPORT_CONVERSATION_NOT_OPEN_OR_OWNED'; end if;\n  insert into public.support_message(conversation_id,sender_type,sender_id,body)\n    values(p_conversation_id,'CUSTOMER',v_customer_id,trim(p_body)) returning id into v_message;\n  update public.support_conversation set updated_at=now() where id=p_conversation_id;\n  insert into public.operation(operation_key,operation_type,actor_type,actor_id,entity_type,entity_id,status,idempotency_key,result_reference,completed_at)\n    values(public.generate_public_code('OP'),'SEND_SUPPORT_MESSAGE','CUSTOMER',v_customer_id,'support_conversation',p_conversation_id,'COMPLETED',p_idempotency_key,v_message::text,now()) returning id into v_op;\n  insert into public.operation_idempotency(actor_id,operation_type,idempotency_key,operation_id) values(v_customer_id,'SEND_SUPPORT_MESSAGE',p_idempotency_key,v_op);\n  return jsonb_build_object('message_id',v_message,'operation_id',v_op);\nend $function$\n",
            "return_type": "jsonb",
            "security_definer": true
        },
        {
            "name": "set_updated_at",
            "schema": "public",
            "language": "plpgsql",
            "arguments": "",
            "definition": "CREATE OR REPLACE FUNCTION public.set_updated_at()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nbegin\n  new.updated_at = now();\n  return new;\nend;\n$function$\n",
            "return_type": "trigger",
            "security_definer": false
        },
        {
            "name": "submit_points_purchase",
            "schema": "public",
            "language": "plpgsql",
            "arguments": "p_package_id uuid, p_payment_method_id uuid, p_transfer_reference text, p_idempotency_key text",
            "definition": "CREATE OR REPLACE FUNCTION public.submit_points_purchase(p_package_id uuid, p_payment_method_id uuid, p_transfer_reference text, p_idempotency_key text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare\n  v_aa uuid;\n  v_customer_id uuid;\n  v_package public.points_package;\n  v_method public.payment_method;\n  v_purchase public.points_purchase;\nbegin\n  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;\n  if nullif(trim(p_idempotency_key),'') is null then raise exception 'IDEMPOTENCY_KEY_REQUIRED'; end if;\n  if nullif(trim(p_transfer_reference),'') is null then raise exception 'PAYMENT_REFERENCE_REQUIRED'; end if;\n\n  select id into v_aa from public.auth_account where auth_user_id=auth.uid();\n  select id into v_customer_id from public.customer_profile\n  where auth_account_id=v_aa and account_status='ACTIVE';\n\n  if v_customer_id is null then raise exception 'CUSTOMER_NOT_FOUND'; end if;\n\n  select * into v_package\n  from public.points_package\n  where id=p_package_id and is_active=true and is_visible=true;\n\n  if v_package.id is null then raise exception 'PACKAGE_NOT_AVAILABLE'; end if;\n\n  select * into v_method\n  from public.payment_method\n  where id=p_payment_method_id and is_active=true and is_visible=true;\n\n  if v_method.id is null then raise exception 'PAYMENT_METHOD_NOT_AVAILABLE'; end if;\n\n  if exists(\n    select 1 from public.points_purchase\n    where customer_id=v_customer_id\n      and transfer_reference=trim(p_transfer_reference)\n      and status in ('PENDING','APPROVED')\n  ) then\n    raise exception 'PAYMENT_REFERENCE_ALREADY_USED';\n  end if;\n\n  insert into public.points_purchase(\n    public_purchase_code,customer_id,package_id,payment_method_id,\n    package_name_snapshot,points_snapshot,price_snapshot,currency_snapshot,\n    payment_method_name_snapshot,receiving_account_snapshot,\n    payment_instructions_snapshot,transfer_reference\n  )\n  values(\n    public.generate_public_code('P'),\n    v_customer_id,v_package.id,v_method.id,\n    v_package.name,v_package.points,v_package.price,v_package.currency,\n    v_method.name,v_method.receiving_account,v_method.transfer_instructions,\n    trim(p_transfer_reference)\n  )\n  returning * into v_purchase;\n\n  insert into public.operation(\n    operation_key,operation_type,actor_type,actor_id,\n    entity_type,entity_id,status,idempotency_key,completed_at\n  )\n  values(\n    public.generate_public_code('OP'),'PURCHASE_POINTS','CUSTOMER',v_customer_id,\n    'points_purchase',v_purchase.id,'COMPLETED',p_idempotency_key,now()\n  );\n\n  return jsonb_build_object(\n    'purchase_id',v_purchase.id,\n    'purchase_code',v_purchase.public_purchase_code,\n    'status',v_purchase.status\n  );\nend;\n$function$\n",
            "return_type": "jsonb",
            "security_definer": true
        },
        {
            "name": "update_customer_number",
            "schema": "public",
            "language": "plpgsql",
            "arguments": "p_customer_number_id uuid, p_phone text, p_idempotency_key text",
            "definition": "CREATE OR REPLACE FUNCTION public.update_customer_number(p_customer_number_id uuid, p_phone text, p_idempotency_key text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare v_customer_id uuid; v_number public.customer_number; v_phone text; v_company_id uuid; v_phone_id uuid; v_op uuid; v_before jsonb;\nbegin\n  v_customer_id:=public.current_customer_profile_id();\n  if v_customer_id is null then raise exception 'CUSTOMER_NOT_FOUND'; end if;\n  if nullif(trim(p_idempotency_key),'') is null then raise exception 'IDEMPOTENCY_KEY_REQUIRED'; end if;\n  select o.id into v_op from public.operation_idempotency i join public.operation o on o.id=i.operation_id\n    where i.actor_id=v_customer_id and i.operation_type='UPDATE_CUSTOMER_NUMBER' and i.idempotency_key=p_idempotency_key;\n  if v_op is not null then return jsonb_build_object('operation_id',v_op,'idempotent',true); end if;\n  select * into v_number from public.customer_number where id=p_customer_number_id and customer_id=v_customer_id for update;\n  if v_number.id is null then raise exception 'CUSTOMER_NUMBER_NOT_FOUND'; end if;\n  if exists(select 1 from public.number_protection_identity where customer_number_id=v_number.id) then raise exception 'NUMBER_HAS_PROTECTION_HISTORY'; end if;\n  v_phone:=public.normalize_phone(p_phone);\n  if length(v_phone)<7 then raise exception 'INVALID_PHONE'; end if;\n  select telecom_company_id into v_company_id from public.telecom_prefix\n    where status='ACTIVE' and v_phone like prefix||'%' order by length(prefix) desc limit 1;\n  if v_company_id is null then raise exception 'TELECOM_COMPANY_NOT_DETECTED'; end if;\n  if exists(select 1 from public.customer_number other join public.phone_number pn on pn.id=other.phone_number_id\n      where other.customer_id=v_customer_id and other.id<>v_number.id and pn.normalized_phone=v_phone) then\n    raise exception 'NUMBER_ALREADY_LINKED';\n  end if;\n  select to_jsonb(pn) into v_before from public.phone_number pn where pn.id=v_number.phone_number_id;\n  insert into public.phone_number(normalized_phone,display_phone,telecom_company_id)\n    values(v_phone,trim(p_phone),v_company_id)\n    on conflict(normalized_phone) do update set display_phone=excluded.display_phone,telecom_company_id=excluded.telecom_company_id,updated_at=now()\n    returning id into v_phone_id;\n  update public.customer_number set phone_number_id=v_phone_id,updated_at=now() where id=v_number.id;\n  insert into public.operation(operation_key,operation_type,actor_type,actor_id,entity_type,entity_id,status,idempotency_key,result_reference,completed_at)\n    values(public.generate_public_code('OP'),'UPDATE_CUSTOMER_NUMBER','CUSTOMER',v_customer_id,'customer_number',v_number.id,'COMPLETED',p_idempotency_key,v_number.id::text,now()) returning id into v_op;\n  insert into public.operation_idempotency(actor_id,operation_type,idempotency_key,operation_id) values(v_customer_id,'UPDATE_CUSTOMER_NUMBER',p_idempotency_key,v_op);\n  insert into public.audit_log(actor_type,actor_id,operation_id,entity_type,entity_id,action,before_state,after_state)\n    values('CUSTOMER',v_customer_id,v_op,'customer_number',v_number.id,'UPDATE_PHONE',v_before,jsonb_build_object('normalized_phone',v_phone,'telecom_company_id',v_company_id));\n  return jsonb_build_object('customer_number_id',v_number.id,'phone_number_id',v_phone_id,'operation_id',v_op);\nend $function$\n",
            "return_type": "jsonb",
            "security_definer": true
        },
        {
            "name": "update_customer_profile",
            "schema": "public",
            "language": "plpgsql",
            "arguments": "p_name text, p_idempotency_key text",
            "definition": "CREATE OR REPLACE FUNCTION public.update_customer_profile(p_name text, p_idempotency_key text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare v_customer_id uuid; v_profile public.customer_profile; v_op uuid; v_before jsonb;\nbegin\n  v_customer_id:=public.current_customer_profile_id();\n  if v_customer_id is null then raise exception 'CUSTOMER_NOT_FOUND'; end if;\n  if nullif(trim(p_name),'') is null or length(trim(p_name))>120 then raise exception 'INVALID_NAME'; end if;\n  if nullif(trim(p_idempotency_key),'') is null then raise exception 'IDEMPOTENCY_KEY_REQUIRED'; end if;\n  select o.id into v_op from public.operation_idempotency i join public.operation o on o.id=i.operation_id\n    where i.actor_id=v_customer_id and i.operation_type='UPDATE_CUSTOMER_PROFILE' and i.idempotency_key=p_idempotency_key;\n  if v_op is not null then return jsonb_build_object('operation_id',v_op,'idempotent',true); end if;\n  select * into v_profile from public.customer_profile where id=v_customer_id for update;\n  v_before:=jsonb_build_object('name',v_profile.name);\n  update public.customer_profile set name=trim(p_name),updated_at=now() where id=v_customer_id returning * into v_profile;\n  insert into public.operation(operation_key,operation_type,actor_type,actor_id,entity_type,entity_id,status,idempotency_key,result_reference,completed_at)\n    values(public.generate_public_code('OP'),'UPDATE_CUSTOMER_PROFILE','CUSTOMER',v_customer_id,'customer_profile',v_customer_id,'COMPLETED',p_idempotency_key,v_customer_id::text,now()) returning id into v_op;\n  insert into public.operation_idempotency(actor_id,operation_type,idempotency_key,operation_id) values(v_customer_id,'UPDATE_CUSTOMER_PROFILE',p_idempotency_key,v_op);\n  insert into public.audit_log(actor_type,actor_id,operation_id,entity_type,entity_id,action,before_state,after_state)\n    values('CUSTOMER',v_customer_id,v_op,'customer_profile',v_customer_id,'UPDATE_NAME',v_before,jsonb_build_object('name',v_profile.name));\n  return jsonb_build_object('customer_id',v_customer_id,'name',v_profile.name,'operation_id',v_op);\nend $function$\n",
            "return_type": "jsonb",
            "security_definer": true
        },
        {
            "name": "apply_rls",
            "schema": "realtime",
            "language": "plpgsql",
            "arguments": "wal jsonb, max_record_bytes integer DEFAULT (1024 * 1024)",
            "definition": "CREATE OR REPLACE FUNCTION realtime.apply_rls(wal jsonb, max_record_bytes integer DEFAULT (1024 * 1024))\n RETURNS SETOF realtime.wal_rls\n LANGUAGE plpgsql\nAS $function$\ndeclare\n    -- Regclass of the table e.g. public.notes\n    entity_ regclass = (quote_ident(wal ->> 'schema') || '.' || quote_ident(wal ->> 'table'))::regclass;\n\n    -- I, U, D, T: insert, update ...\n    action realtime.action = (\n        case wal ->> 'action'\n            when 'I' then 'INSERT'\n            when 'U' then 'UPDATE'\n            when 'D' then 'DELETE'\n            else 'ERROR'\n        end\n    );\n\n    -- Is row level security enabled for the table\n    is_rls_enabled bool = relrowsecurity from pg_class where oid = entity_;\n\n    subscriptions realtime.subscription[] = array_agg(subs)\n        from\n            realtime.subscription subs\n        where\n            subs.entity = entity_\n            -- Filter by action early - only get subscriptions interested in this action\n            -- action_filter column can be: '*' (all), 'INSERT', 'UPDATE', or 'DELETE'\n            and (subs.action_filter = '*' or subs.action_filter = action::text);\n\n    -- Subscription vars\n    working_role regrole;\n    working_selected_columns text[];\n    claimed_role regrole;\n    claims jsonb;\n\n    subscription_id uuid;\n    subscription_has_access bool;\n    visible_to_subscription_ids uuid[] = '{}';\n\n    -- structured info for wal's columns\n    columns realtime.wal_column[];\n    -- previous identity values for update/delete\n    old_columns realtime.wal_column[];\n\n    error_record_exceeds_max_size boolean = octet_length(wal::text) > max_record_bytes;\n\n    -- Primary jsonb output for record\n    output jsonb;\n\n    -- Loop record for iterating unique roles (outer loop)\n    role_record record;\n    -- Loop record for iterating unique selected_columns within a role (inner loop)\n    cols_record record;\n    -- Subscription ids visible at the role level (before fanning out by selected_columns)\n    visible_role_sub_ids uuid[] = '{}';\n\nbegin\n    perform set_config('role', null, true);\n\n    columns =\n        array_agg(\n            (\n                x->>'name',\n                x->>'type',\n                x->>'typeoid',\n                realtime.cast(\n                    (x->'value') #>> '{}',\n                    coalesce(\n                        (x->>'typeoid')::regtype, -- null when wal2json version <= 2.4\n                        (x->>'type')::regtype\n                    )\n                ),\n                (pks ->> 'name') is not null,\n                true\n            )::realtime.wal_column\n        )\n        from\n            jsonb_array_elements(wal -> 'columns') x\n            left join jsonb_array_elements(wal -> 'pk') pks\n                on (x ->> 'name') = (pks ->> 'name');\n\n    old_columns =\n        array_agg(\n            (\n                x->>'name',\n                x->>'type',\n                x->>'typeoid',\n                realtime.cast(\n                    (x->'value') #>> '{}',\n                    coalesce(\n                        (x->>'typeoid')::regtype, -- null when wal2json version <= 2.4\n                        (x->>'type')::regtype\n                    )\n                ),\n                (pks ->> 'name') is not null,\n                true\n            )::realtime.wal_column\n        )\n        from\n            jsonb_array_elements(wal -> 'identity') x\n            left join jsonb_array_elements(wal -> 'pk') pks\n                on (x ->> 'name') = (pks ->> 'name');\n\n    for role_record in\n        select claims_role\n        from (select distinct claims_role from unnest(subscriptions)) t\n        order by claims_role::text\n    loop\n        working_role := role_record.claims_role;\n\n        -- Update `is_selectable` for columns and old_columns (once per role)\n        columns =\n            array_agg(\n                (\n                    c.name,\n                    c.type_name,\n                    c.type_oid,\n                    c.value,\n                    c.is_pkey,\n                    pg_catalog.has_column_privilege(working_role, entity_, c.name, 'SELECT')\n                )::realtime.wal_column\n            )\n            from\n                unnest(columns) c;\n\n        old_columns =\n                array_agg(\n                    (\n                        c.name,\n                        c.type_name,\n                        c.type_oid,\n                        c.value,\n                        c.is_pkey,\n                        pg_catalog.has_column_privilege(working_role, entity_, c.name, 'SELECT')\n                    )::realtime.wal_column\n                )\n                from\n                    unnest(old_columns) c;\n\n        if action <> 'DELETE' and count(1) = 0 from unnest(columns) c where c.is_pkey then\n            -- Fan out 400 error per distinct selected_columns for this role\n            for cols_record in\n                select selected_columns\n                from (select distinct selected_columns from unnest(subscriptions) s where s.claims_role = working_role) t\n                order by coalesce(array_to_string(selected_columns, ','), '')\n            loop\n                working_selected_columns := cols_record.selected_columns;\n                return next (\n                    jsonb_build_object(\n                        'schema', wal ->> 'schema',\n                        'table', wal ->> 'table',\n                        'type', action\n                    ),\n                    is_rls_enabled,\n                    (select array_agg(s.subscription_id) from unnest(subscriptions) as s where s.claims_role = working_role and (s.selected_columns is not distinct from working_selected_columns)),\n                    array['Error 400: Bad Request, no primary key']\n                )::realtime.wal_rls;\n            end loop;\n\n        -- The claims role does not have SELECT permission to the primary key of entity\n        elsif action <> 'DELETE' and sum(c.is_selectable::int) <> count(1) from unnest(columns) c where c.is_pkey then\n            -- Fan out 401 error per distinct selected_columns for this role\n            for cols_record in\n                select selected_columns\n                from (select distinct selected_columns from unnest(subscriptions) s where s.claims_role = working_role) t\n                order by coalesce(array_to_string(selected_columns, ','), '')\n            loop\n                working_selected_columns := cols_record.selected_columns;\n                return next (\n                    jsonb_build_object(\n                        'schema', wal ->> 'schema',\n                        'table', wal ->> 'table',\n                        'type', action\n                    ),\n                    is_rls_enabled,\n                    (select array_agg(s.subscription_id) from unnest(subscriptions) as s where s.claims_role = working_role and (s.selected_columns is not distinct from working_selected_columns)),\n                    array['Error 401: Unauthorized']\n                )::realtime.wal_rls;\n            end loop;\n\n        else\n            -- Create the prepared statement (once per role)\n            if is_rls_enabled and action <> 'DELETE' then\n                if (select 1 from pg_prepared_statements where name = 'walrus_rls_stmt' limit 1) > 0 then\n                    deallocate walrus_rls_stmt;\n                end if;\n                execute realtime.build_prepared_statement_sql('walrus_rls_stmt', entity_, columns);\n            end if;\n\n            -- Collect all visible subscription IDs for this role (filter check + RLS check)\n            visible_role_sub_ids = '{}';\n\n            for subscription_id, claims in (\n                    select\n                        subs.subscription_id,\n                        subs.claims\n                    from\n                        unnest(subscriptions) subs\n                    where\n                        subs.entity = entity_\n                        and subs.claims_role = working_role\n                        and (\n                            realtime.is_visible_through_filters(columns, subs.filters)\n                            or (\n                              action = 'DELETE'\n                              and realtime.is_visible_through_filters(old_columns, subs.filters)\n                            )\n                        )\n            ) loop\n\n                if not is_rls_enabled or action = 'DELETE' then\n                    visible_role_sub_ids = visible_role_sub_ids || subscription_id;\n                else\n                    -- Check if RLS allows the role to see the record\n                    perform\n                        -- Trim leading and trailing quotes from working_role because set_config\n                        -- doesn't recognize the role as valid if they are included\n                        set_config('role', trim(both '\"' from working_role::text), true),\n                        set_config('request.jwt.claims', claims::text, true);\n\n                    execute 'execute walrus_rls_stmt' into subscription_has_access;\n\n                    -- Reset the role on every FOR..LOOP batch execution.\n                    -- The first batch of 10 rows is pre-fetched using the current connection role (PG internal behaviour)\n                    -- then we have to reset it again otherwise it would use the role defined in the `set_config` above\n                    -- to fetch the remaining rows when rows>10, which could be a user-defined role that lacks execution grants.\n                    -- The flow is:\n                    --   1. run batch with conn role\n                    --   2. set_config working_role\n                    --   3. execute walrus\n                    --   4. reset role (revert)\n                    --   5. repeat\n                    perform set_config('role', null, true);\n\n                    if subscription_has_access then\n                        visible_role_sub_ids = visible_role_sub_ids || subscription_id;\n                    end if;\n                end if;\n            end loop;\n\n            perform set_config('role', null, true);\n\n            -- Inner loop: per distinct selected_columns for this role\n            for cols_record in\n                select selected_columns\n                from (select distinct selected_columns from unnest(subscriptions) s where s.claims_role = working_role) t\n                order by coalesce(array_to_string(selected_columns, ','), '')\n            loop\n                working_selected_columns := cols_record.selected_columns;\n\n                output = jsonb_build_object(\n                    'schema', wal ->> 'schema',\n                    'table', wal ->> 'table',\n                    'type', action,\n                    'commit_timestamp', to_char(\n                        ((wal ->> 'timestamp')::timestamptz at time zone 'utc'),\n                        'YYYY-MM-DD\"T\"HH24:MI:SS.MS\"Z\"'\n                    ),\n                    'columns', (\n                        select\n                            jsonb_agg(\n                                jsonb_build_object(\n                                    'name', pa.attname,\n                                    'type', pt.typname\n                                )\n                                order by pa.attnum asc\n                            )\n                        from\n                            pg_attribute pa\n                            join pg_type pt\n                                on pa.atttypid = pt.oid\n                            left join (\n                                select unnest(conkey) as pkey_attnum\n                                from pg_constraint\n                                where conrelid = entity_ and contype = 'p'\n                            ) pk on pk.pkey_attnum = pa.attnum\n                        where\n                            attrelid = entity_\n                            and attnum > 0\n                            and pg_catalog.has_column_privilege(working_role, entity_, pa.attname, 'SELECT')\n                            and (working_selected_columns is null or pa.attname = any(working_selected_columns) or pk.pkey_attnum is not null)\n                    )\n                )\n                -- Add \"record\" key for insert and update\n                || case\n                    when action in ('INSERT', 'UPDATE') then\n                        jsonb_build_object(\n                            'record',\n                            (\n                                select\n                                    jsonb_object_agg(\n                                        -- if unchanged toast, get column name and value from old record\n                                        coalesce((c).name, (oc).name),\n                                        case\n                                            when (c).name is null then (oc).value\n                                            else (c).value\n                                        end\n                                    )\n                                from\n                                    unnest(columns) c\n                                    full outer join unnest(old_columns) oc\n                                        on (c).name = (oc).name\n                                where\n                                    coalesce((c).is_selectable, (oc).is_selectable)\n                                    and (working_selected_columns is null or coalesce((c).name, (oc).name) = any(working_selected_columns) or coalesce((c).is_pkey, (oc).is_pkey))\n                                    and ( not error_record_exceeds_max_size or (octet_length((c).value::text) <= 64))\n                            )\n                        )\n                    else '{}'::jsonb\n                end\n                -- Add \"old_record\" key for update and delete\n                || case\n                    when action = 'UPDATE' then\n                        jsonb_build_object(\n                                'old_record',\n                                (\n                                    select jsonb_object_agg((c).name, (c).value)\n                                    from unnest(old_columns) c\n                                    where\n                                        (c).is_selectable\n                                        and (working_selected_columns is null or (c).name = any(working_selected_columns) or (c).is_pkey)\n                                        and ( not error_record_exceeds_max_size or (octet_length((c).value::text) <= 64))\n                                )\n                            )\n                    when action = 'DELETE' then\n                        jsonb_build_object(\n                            'old_record',\n                            (\n                                select jsonb_object_agg((c).name, (c).value)\n                                from unnest(old_columns) c\n                                where\n                                    (c).is_selectable\n                                    and (working_selected_columns is null or (c).name = any(working_selected_columns) or (c).is_pkey)\n                                    and ( not error_record_exceeds_max_size or (octet_length((c).value::text) <= 64))\n                                    and ( not is_rls_enabled or (c).is_pkey ) -- if RLS enabled, we can't secure deletes so filter to pkey\n                            )\n                        )\n                    else '{}'::jsonb\n                end;\n\n                -- Filter visible_role_sub_ids to those matching the current selected_columns group\n                visible_to_subscription_ids = coalesce(\n                    (\n                        select array_agg(s.subscription_id)\n                        from unnest(subscriptions) s\n                        where s.claims_role = working_role\n                          and (s.selected_columns is not distinct from working_selected_columns)\n                          and s.subscription_id = any(visible_role_sub_ids)\n                    ),\n                    '{}'::uuid[]\n                );\n\n                return next (\n                    output,\n                    is_rls_enabled,\n                    visible_to_subscription_ids,\n                    case\n                        when error_record_exceeds_max_size then array['Error 413: Payload Too Large']\n                        else '{}'\n                    end\n                )::realtime.wal_rls;\n            end loop;\n\n        end if;\n    end loop;\n\n    perform set_config('role', null, true);\nend;\n$function$\n",
            "return_type": "SETOF realtime.wal_rls",
            "security_definer": false
        },
        {
            "name": "broadcast_changes",
            "schema": "realtime",
            "language": "plpgsql",
            "arguments": "topic_name text, event_name text, operation text, table_name text, table_schema text, new record, old record, level text DEFAULT 'ROW'::text",
            "definition": "CREATE OR REPLACE FUNCTION realtime.broadcast_changes(topic_name text, event_name text, operation text, table_name text, table_schema text, new record, old record, level text DEFAULT 'ROW'::text)\n RETURNS void\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n    -- Declare a variable to hold the JSONB representation of the row\n    row_data jsonb := '{}'::jsonb;\nBEGIN\n    IF level = 'STATEMENT' THEN\n        RAISE EXCEPTION 'function can only be triggered for each row, not for each statement';\n    END IF;\n    -- Check the operation type and handle accordingly\n    IF operation = 'INSERT' OR operation = 'UPDATE' OR operation = 'DELETE' THEN\n        row_data := jsonb_build_object('old_record', OLD, 'record', NEW, 'operation', operation, 'table', table_name, 'schema', table_schema);\n        PERFORM realtime.send (row_data, event_name, topic_name);\n    ELSE\n        RAISE EXCEPTION 'Unexpected operation type: %', operation;\n    END IF;\nEXCEPTION\n    WHEN OTHERS THEN\n        RAISE EXCEPTION 'Failed to process the row: %', SQLERRM;\nEND;\n\n$function$\n",
            "return_type": "void",
            "security_definer": false
        },
        {
            "name": "build_prepared_statement_sql",
            "schema": "realtime",
            "language": "sql",
            "arguments": "prepared_statement_name text, entity regclass, columns realtime.wal_column[]",
            "definition": "CREATE OR REPLACE FUNCTION realtime.build_prepared_statement_sql(prepared_statement_name text, entity regclass, columns realtime.wal_column[])\n RETURNS text\n LANGUAGE sql\nAS $function$\n      /*\n      Builds a sql string that, if executed, creates a prepared statement to\n      tests retrive a row from *entity* by its primary key columns.\n      Example\n          select realtime.build_prepared_statement_sql('public.notes', '{\"id\"}'::text[], '{\"bigint\"}'::text[])\n      */\n          select\n      'prepare ' || prepared_statement_name || ' as\n          select\n              exists(\n                  select\n                      1\n                  from\n                      ' || entity || '\n                  where\n                      ' || string_agg(quote_ident(pkc.name) || '=' || quote_nullable(pkc.value #>> '{}') , ' and ') || '\n              )'\n          from\n              unnest(columns) pkc\n          where\n              pkc.is_pkey\n          group by\n              entity\n      $function$\n",
            "return_type": "text",
            "security_definer": false
        },
        {
            "name": "cast",
            "schema": "realtime",
            "language": "plpgsql",
            "arguments": "val text, type_ regtype",
            "definition": "CREATE OR REPLACE FUNCTION realtime.\"cast\"(val text, type_ regtype)\n RETURNS jsonb\n LANGUAGE plpgsql\n IMMUTABLE\nAS $function$\ndeclare\n  res jsonb;\nbegin\n  if type_::text = 'bytea' then\n    return to_jsonb(val);\n  end if;\n  execute format('select to_jsonb(%L::'|| type_::text || ')', val) into res;\n  return res;\nend\n$function$\n",
            "return_type": "jsonb",
            "security_definer": false
        },
        {
            "name": "check_equality_op",
            "schema": "realtime",
            "language": "plpgsql",
            "arguments": "op realtime.equality_op, type_ regtype, val_1 text, val_2 text, negate boolean",
            "definition": "CREATE OR REPLACE FUNCTION realtime.check_equality_op(op realtime.equality_op, type_ regtype, val_1 text, val_2 text, negate boolean)\n RETURNS boolean\n LANGUAGE plpgsql\n STABLE\nAS $function$\ndeclare\n    op_symbol text;\n    res boolean;\nbegin\n    -- IS DISTINCT FROM / IS NOT DISTINCT FROM: infix, both sides typed literals\n    if op = 'isdistinct' then\n        execute format(\n            'select %L::%s %s %L::%s',\n            val_1,\n            type_::text,\n            case when negate then 'IS NOT DISTINCT FROM' else 'IS DISTINCT FROM' end,\n            val_2,\n            type_::text\n        ) into res;\n        return res;\n    end if;\n\n    -- IS requires a keyword RHS (NULL, TRUE, FALSE, UNKNOWN), not a typed literal\n    if op = 'is' then\n        if val_2 not in ('null', 'true', 'false', 'unknown') then\n            raise exception 'invalid value for is filter: must be null, true, false, or unknown';\n        end if;\n        execute format(\n            'select %L::%s %s %s',\n            val_1,\n            type_::text,\n            case when negate then 'IS NOT' else 'IS' end,\n            upper(val_2)\n        ) into res;\n        return res;\n    end if;\n\n    op_symbol = case\n        when op = 'eq'    then '='\n        when op = 'neq'   then '!='\n        when op = 'lt'    then '<'\n        when op = 'lte'   then '<='\n        when op = 'gt'    then '>'\n        when op = 'gte'   then '>='\n        when op = 'in'    then '= any'\n        when op = 'like'   then 'LIKE'\n        when op = 'ilike'  then 'ILIKE'\n        when op = 'match'  then '~'\n        when op = 'imatch' then '~*'\n        else null\n    end;\n\n    if op_symbol is null then\n        raise exception 'unsupported equality operator: %', op::text;\n    end if;\n\n    execute format(\n        'select %L::%s %s (%L::%s)',\n        val_1,\n        type_::text,\n        op_symbol,\n        val_2,\n        case when op = 'in' then type_::text || '[]' else type_::text end\n    ) into res;\n\n    return case when negate then not res else res end;\nend;\n$function$\n",
            "return_type": "boolean",
            "security_definer": false
        },
        {
            "name": "check_equality_op",
            "schema": "realtime",
            "language": "plpgsql",
            "arguments": "op realtime.equality_op, type_ regtype, val_1 text, val_2 text",
            "definition": "CREATE OR REPLACE FUNCTION realtime.check_equality_op(op realtime.equality_op, type_ regtype, val_1 text, val_2 text)\n RETURNS boolean\n LANGUAGE plpgsql\n IMMUTABLE\nAS $function$\n/*\nCasts *val_1* and *val_2* as type *type_* and check the *op* condition for truthiness\n*/\ndeclare\n    op_symbol text = (\n        case\n            when op = 'eq' then '='\n            when op = 'neq' then '!='\n            when op = 'lt' then '<'\n            when op = 'lte' then '<='\n            when op = 'gt' then '>'\n            when op = 'gte' then '>='\n            when op = 'in' then '= any'\n            else 'UNKNOWN OP'\n        end\n    );\n    res boolean;\nbegin\n    execute format(\n        'select %L::'|| type_::text || ' ' || op_symbol\n        || ' ( %L::'\n        || (\n            case\n                when op = 'in' then type_::text || '[]'\n                else type_::text end\n        )\n        || ')', val_1, val_2) into res;\n    return res;\nend;\n$function$\n",
            "return_type": "boolean",
            "security_definer": false
        },
        {
            "name": "is_visible_through_filters",
            "schema": "realtime",
            "language": "sql",
            "arguments": "columns realtime.wal_column[], filters realtime.user_defined_filter[]",
            "definition": "CREATE OR REPLACE FUNCTION realtime.is_visible_through_filters(columns realtime.wal_column[], filters realtime.user_defined_filter[])\n RETURNS boolean\n LANGUAGE sql\n STABLE\nAS $function$\n    select\n        filters is null\n        or array_length(filters, 1) is null\n        or coalesce(\n            count(col.name) = count(1)\n            and sum(\n                realtime.check_equality_op(\n                    op:=f.op,\n                    type_:=coalesce(col.type_oid::regtype, col.type_name::regtype),\n                    val_1:=col.value #>> '{}',\n                    val_2:=f.value,\n                    negate:=coalesce(f.negate, false)\n                )::int\n            ) filter (where col.name is not null) = count(col.name),\n            false\n        )\n    from\n        unnest(filters) f\n        left join unnest(columns) col\n            on f.column_name = col.name;\n$function$\n",
            "return_type": "boolean",
            "security_definer": false
        },
        {
            "name": "list_changes",
            "schema": "realtime",
            "language": "sql",
            "arguments": "publication name, slot_name name, max_changes integer, max_record_bytes integer",
            "definition": "CREATE OR REPLACE FUNCTION realtime.list_changes(publication name, slot_name name, max_changes integer, max_record_bytes integer)\n RETURNS TABLE(wal jsonb, is_rls_enabled boolean, subscription_ids uuid[], errors text[], slot_changes_count bigint)\n LANGUAGE sql\n SET log_min_messages TO 'fatal'\nAS $function$\n  WITH pub AS (\n    SELECT\n      concat_ws(\n        ',',\n        CASE WHEN bool_or(pubinsert) THEN 'insert' ELSE NULL END,\n        CASE WHEN bool_or(pubupdate) THEN 'update' ELSE NULL END,\n        CASE WHEN bool_or(pubdelete) THEN 'delete' ELSE NULL END\n      ) AS w2j_actions,\n      coalesce(\n        string_agg(\n          realtime.quote_wal2json(format('%I.%I', schemaname, tablename)::regclass),\n          ','\n        ) filter (WHERE ppt.tablename IS NOT NULL),\n        ''\n      ) AS w2j_add_tables\n    FROM pg_publication pp\n    LEFT JOIN pg_publication_tables ppt ON pp.pubname = ppt.pubname\n    WHERE pp.pubname = publication\n    GROUP BY pp.pubname\n    LIMIT 1\n  ),\n  -- MATERIALIZED ensures pg_logical_slot_get_changes is called exactly once\n  w2j AS MATERIALIZED (\n    SELECT x.*, pub.w2j_add_tables\n    FROM pub,\n         pg_logical_slot_get_changes(\n           slot_name, null, max_changes,\n           'include-pk', 'true',\n           'include-transaction', 'false',\n           'include-timestamp', 'true',\n           'include-type-oids', 'true',\n           'format-version', '2',\n           'actions', pub.w2j_actions,\n           'add-tables', pub.w2j_add_tables\n         ) x\n  ),\n  slot_count AS (\n    SELECT count(*)::bigint AS cnt\n    FROM w2j\n    WHERE w2j.w2j_add_tables <> ''\n  ),\n  rls_filtered AS (\n    SELECT xyz.wal, xyz.is_rls_enabled, xyz.subscription_ids, xyz.errors\n    FROM w2j,\n         realtime.apply_rls(\n           wal := w2j.data::jsonb,\n           max_record_bytes := max_record_bytes\n         ) xyz(wal, is_rls_enabled, subscription_ids, errors)\n    WHERE w2j.w2j_add_tables <> ''\n      AND xyz.subscription_ids[1] IS NOT NULL\n  )\n  SELECT rf.wal, rf.is_rls_enabled, rf.subscription_ids, rf.errors, sc.cnt\n  FROM rls_filtered rf, slot_count sc\n\n  UNION ALL\n\n  SELECT null, null, null, null, sc.cnt\n  FROM slot_count sc\n  WHERE NOT EXISTS (SELECT 1 FROM rls_filtered)\n$function$\n",
            "return_type": "TABLE(wal jsonb, is_rls_enabled boolean, subscription_ids uuid[], errors text[], slot_changes_count bigint)",
            "security_definer": false
        },
        {
            "name": "list_changes_sync",
            "schema": "realtime",
            "language": "sql",
            "arguments": "publication name, slot_name name, max_changes integer, max_record_bytes integer",
            "definition": "CREATE OR REPLACE FUNCTION realtime.list_changes_sync(publication name, slot_name name, max_changes integer, max_record_bytes integer)\n RETURNS TABLE(wal jsonb, is_rls_enabled boolean, subscription_ids uuid[], errors text[], slot_changes_count bigint)\n LANGUAGE sql\n SET log_min_messages TO 'fatal'\nAS $function$\n  WITH pub AS (\n    SELECT\n      concat_ws(\n        ',',\n        CASE WHEN bool_or(pubinsert) THEN 'insert' ELSE NULL END,\n        CASE WHEN bool_or(pubupdate) THEN 'update' ELSE NULL END,\n        CASE WHEN bool_or(pubdelete) THEN 'delete' ELSE NULL END\n      ) AS w2j_actions,\n      coalesce(\n        string_agg(\n          realtime.quote_wal2json(format('%I.%I', schemaname, tablename)::regclass),\n          ','\n        ) filter (WHERE ppt.tablename IS NOT NULL),\n        ''\n      ) AS w2j_add_tables\n    FROM pg_publication pp\n    LEFT JOIN pg_publication_tables ppt ON pp.pubname = ppt.pubname\n    WHERE pp.pubname = publication\n    GROUP BY pp.pubname\n    LIMIT 1\n  ),\n  -- MATERIALIZED ensures the slot is read exactly once.\n  consumed AS MATERIALIZED (\n    SELECT x.*, pub.w2j_add_tables\n    FROM pub,\n         realtime.settled_changes(\n           slot_name, max_changes,\n           'include-pk', 'true',\n           'include-transaction', 'false',\n           'include-timestamp', 'true',\n           'include-type-oids', 'true',\n           'format-version', '2',\n           'actions', pub.w2j_actions,\n           'add-tables', pub.w2j_add_tables\n         ) x\n  ),\n  slot_count AS (\n    SELECT count(*)::bigint AS cnt\n    FROM consumed\n    WHERE consumed.w2j_add_tables <> ''\n  ),\n  rls_filtered AS (\n    SELECT xyz.wal, xyz.is_rls_enabled, xyz.subscription_ids, xyz.errors\n    FROM consumed,\n         realtime.apply_rls(\n           wal := consumed.data::jsonb,\n           max_record_bytes := max_record_bytes\n         ) xyz(wal, is_rls_enabled, subscription_ids, errors)\n    WHERE consumed.w2j_add_tables <> ''\n      AND xyz.subscription_ids[1] IS NOT NULL\n  )\n  SELECT rf.wal, rf.is_rls_enabled, rf.subscription_ids, rf.errors, sc.cnt\n  FROM rls_filtered rf, slot_count sc\n\n  UNION ALL\n\n  SELECT null, null, null, null, sc.cnt\n  FROM slot_count sc\n  WHERE NOT EXISTS (SELECT 1 FROM rls_filtered)\n$function$\n",
            "return_type": "TABLE(wal jsonb, is_rls_enabled boolean, subscription_ids uuid[], errors text[], slot_changes_count bigint)",
            "security_definer": false
        },
        {
            "name": "quote_wal2json",
            "schema": "realtime",
            "language": "sql",
            "arguments": "entity regclass",
            "definition": "CREATE OR REPLACE FUNCTION realtime.quote_wal2json(entity regclass)\n RETURNS text\n LANGUAGE sql\n IMMUTABLE STRICT\nAS $function$\n  SELECT\n    realtime.wal2json_escape_identifier(nsp.nspname::text)\n    || '.'\n    || realtime.wal2json_escape_identifier(pc.relname::text)\n  FROM pg_class pc\n  JOIN pg_namespace nsp ON pc.relnamespace = nsp.oid\n  WHERE pc.oid = entity\n$function$\n",
            "return_type": "text",
            "security_definer": false
        },
        {
            "name": "send",
            "schema": "realtime",
            "language": "plpgsql",
            "arguments": "payload jsonb, event text, topic text, private boolean DEFAULT true",
            "definition": "CREATE OR REPLACE FUNCTION realtime.send(payload jsonb, event text, topic text, private boolean DEFAULT true)\n RETURNS void\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n  generated_id uuid;\n  final_payload jsonb;\nBEGIN\n  BEGIN\n    generated_id := gen_random_uuid();\n\n    -- Check if payload has an 'id' key, if not, add the generated UUID\n    IF payload ? 'id' THEN\n      final_payload := payload;\n    ELSE\n      final_payload := jsonb_set(payload, '{id}', to_jsonb(generated_id));\n    END IF;\n\n    -- Set the topic configuration\n    EXECUTE format('SET LOCAL realtime.topic TO %L', topic);\n\n    INSERT INTO realtime.messages (id, payload, event, topic, private, extension)\n    VALUES (generated_id, final_payload, event, topic, private, 'broadcast');\n  EXCEPTION\n    WHEN OTHERS THEN\n      RAISE WARNING 'WarnSendingBroadcastMessage: %', SQLERRM;\n  END;\nEND;\n$function$\n",
            "return_type": "void",
            "security_definer": false
        },
        {
            "name": "send_binary",
            "schema": "realtime",
            "language": "plpgsql",
            "arguments": "payload bytea, event text, topic text, private boolean DEFAULT true",
            "definition": "CREATE OR REPLACE FUNCTION realtime.send_binary(payload bytea, event text, topic text, private boolean DEFAULT true)\n RETURNS void\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n  generated_id uuid;\nBEGIN\n  BEGIN\n    generated_id := gen_random_uuid();\n\n    EXECUTE format('SET LOCAL realtime.topic TO %L', topic);\n\n    INSERT INTO realtime.messages (id, binary_payload, event, topic, private, extension)\n    VALUES (generated_id, payload, event, topic, private, 'broadcast');\n  EXCEPTION\n    WHEN OTHERS THEN\n      RAISE WARNING 'WarnSendingBroadcastMessage: %', SQLERRM;\n  END;\nEND;\n$function$\n",
            "return_type": "void",
            "security_definer": false
        },
        {
            "name": "settled_changes",
            "schema": "realtime",
            "language": "plpgsql",
            "arguments": "slot_name name, max_changes integer, VARIADIC opts text[]",
            "definition": "CREATE OR REPLACE FUNCTION realtime.settled_changes(slot_name name, max_changes integer, VARIADIC opts text[])\n RETURNS TABLE(lsn pg_lsn, xid xid, data text)\n LANGUAGE plpgsql\nAS $function$\ndeclare\n  upto pg_lsn;\n  total bigint;\n  xids xid[];\n  starts bigint[];\n  snapshot pg_snapshot;\n  running_xids xid[];\n  xmax_age int;\n  cut bigint;\nbegin\n  -- Each statement in a volatile function takes its own snapshot, which is what lets the\n  -- check below see a writer that was still in flight when the peek ran. Under REPEATABLE\n  -- READ the snapshot never advances, so a deferred change would never be released.\n  if current_setting('transaction_isolation') <> 'read committed' then\n    raise exception 'realtime.settled_changes requires READ COMMITTED';\n  end if;\n\n  -- The peek and the read below cover the same WAL, so the read cannot reach a commit the\n  -- check never saw.\n  upto := pg_current_wal_flush_lsn();\n\n  -- One entry per transaction, in commit order: its xid and the position of its first\n  -- change. The peek uses the caller's own options, so max_changes counts exactly what the\n  -- read counts. A non-transactional logical message is emitted as soon as it is decoded,\n  -- tagged with the xid of whatever transaction wrote it, so it does not mark where that\n  -- transaction starts.\n  select coalesce(sum(g.n), 0),\n         array_agg(g.x order by g.first) filter (where g.first is not null),\n         array_agg(g.first order by g.first) filter (where g.first is not null)\n    into total, xids, starts\n    from (\n      select p.xid as x, count(*) as n,\n             min(p.ord) filter (where not case\n               when starts_with(p.data, '{\"action\":\"M\"') then (p.data::jsonb->>'transactional')::boolean is false\n               else false\n             end) as first\n      from pg_logical_slot_peek_changes(slot_name, upto, max_changes, variadic opts)\n           with ordinality as p(lsn, xid, data, ord)\n      group by p.xid\n    ) g;\n\n  -- Nothing for the caller, but the slot still has to move past what the peek covered.\n  if total = 0 then\n    perform pg_replication_slot_advance(slot_name, upto);\n    return;\n  end if;\n\n  if xids is not null then\n    -- Taken after the peek is materialized, so a writer that was still in flight during\n    -- decoding is guaranteed to show up here.\n    snapshot := pg_current_snapshot();\n\n    -- A commit record reaches the WAL before the writer leaves the proc array, so a change\n    -- can be decoded while its row is invisible. apply_rls would resolve a policy against a\n    -- row it cannot see and authorize it for nobody, while the read consumed it regardless.\n    --\n    -- xip lists transactions running when the snapshot was taken. It does not cover a writer\n    -- whose xid sits at or beyond xmax, which never appears there, so the horizon is checked\n    -- too. age() counts backwards from the current xid and so compares correctly across\n    -- wraparound.\n    select coalesce(array_agg(running.x::xid), array[]::xid[])\n      into running_xids\n      from pg_snapshot_xip(snapshot) running(x);\n    xmax_age := age(pg_snapshot_xmax(snapshot)::xid);\n\n    select min(u.s) into cut\n      from unnest(xids, starts) as u(x, s)\n      where u.x = any(running_xids) or age(u.x) <= xmax_age;\n  end if;\n\n  -- The read stops right after the commit that brings its count to upto_nchanges, so the\n  -- count of changes in front of the first unsettled transaction stops it just before that\n  -- transaction.\n  if cut is null then\n    return query\n      select p.* from pg_logical_slot_get_changes(slot_name, upto, max_changes, variadic opts) p;\n  elsif cut > 1 then\n    return query\n      select p.* from pg_logical_slot_get_changes(slot_name, upto, (cut - 1)::int, variadic opts) p;\n  end if;\nend;\n$function$\n",
            "return_type": "TABLE(lsn pg_lsn, xid xid, data text)",
            "security_definer": false
        },
        {
            "name": "subscription_check_filters",
            "schema": "realtime",
            "language": "plpgsql",
            "arguments": "",
            "definition": "CREATE OR REPLACE FUNCTION realtime.subscription_check_filters()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\ndeclare\n    col_names text[] = coalesce(\n            array_agg(a.attname order by a.attnum),\n            '{}'::text[]\n        )\n        from\n            pg_catalog.pg_attribute a\n        where\n            a.attrelid = new.entity\n            and a.attnum > 0\n            and not a.attisdropped\n            and pg_catalog.has_column_privilege(\n                (new.claims ->> 'role'),\n                a.attrelid,\n                a.attnum,\n                'SELECT'\n            );\n    filter realtime.user_defined_filter;\n    col_type regtype;\n    in_val jsonb;\n    selected_col text;\nbegin\n    for filter in select * from unnest(new.filters) loop\n        if not filter.column_name = any(col_names) then\n            raise exception 'invalid column for filter %', filter.column_name;\n        end if;\n\n        col_type = (\n            select atttypid::regtype\n            from pg_catalog.pg_attribute\n            where attrelid = new.entity\n                  and attname = filter.column_name\n        );\n        if col_type is null then\n            raise exception 'failed to lookup type for column %', filter.column_name;\n        end if;\n\n        if filter.op = 'in'::realtime.equality_op then\n            in_val = realtime.cast(filter.value, (col_type::text || '[]')::regtype);\n            if coalesce(jsonb_array_length(in_val), 0) > 100 then\n                raise exception 'too many values for `in` filter. Maximum 100';\n            end if;\n        elsif filter.op = 'is'::realtime.equality_op then\n            -- `is` requires a keyword RHS rather than a typed literal\n            if filter.value not in ('null', 'true', 'false', 'unknown') then\n                raise exception 'invalid value for is filter: must be null, true, false, or unknown';\n            end if;\n            -- IS NULL works for any type, but IS TRUE/FALSE/UNKNOWN require a boolean\n            -- operand. Reject the non-null keywords on non-boolean columns here so they\n            -- don't abort apply_rls at WAL time.\n            if filter.value <> 'null' and col_type <> 'boolean'::regtype then\n                raise exception 'is % filter requires a boolean column, got %', filter.value, col_type::text;\n            end if;\n        elsif filter.op in ('like'::realtime.equality_op, 'ilike'::realtime.equality_op) then\n            -- like/ilike apply the text pattern operator (~~); reject column types that\n            -- have no such operator instead of failing at WAL time\n            if not exists (\n                select 1 from pg_catalog.pg_operator\n                where oprname = '~~' and oprleft = col_type\n            ) then\n                raise exception 'operator % requires a text-compatible column type, got %', filter.op::text, col_type::text;\n            end if;\n        elsif filter.op in ('match'::realtime.equality_op, 'imatch'::realtime.equality_op) then\n            -- match/imatch apply the regex operators ~ / ~*; reject column types that have\n            -- no such operator (e.g. integer) instead of failing at WAL time, mirroring the\n            -- like/ilike guard above.\n            if not exists (\n                select 1 from pg_catalog.pg_operator\n                where oprname = case when filter.op = 'imatch'::realtime.equality_op then '~*' else '~' end\n                  and oprleft = col_type\n                  and oprright = col_type\n                  and oprresult = 'boolean'::regtype\n            ) then\n                raise exception 'operator % requires a text-compatible column type, got %', filter.op::text, col_type::text;\n            end if;\n            -- validate the regex eagerly so a bad pattern is rejected here, not inside\n            -- apply_rls where it would abort the WAL stream for the entity\n            begin\n                perform '' ~ filter.value;\n            exception when others then\n                raise exception 'invalid regular expression for % filter: %', filter.op::text, sqlerrm;\n            end;\n        else\n            -- eq/neq/lt/lte/gt/gte: value must be coercable to the type\n            perform realtime.cast(filter.value, col_type);\n        end if;\n    end loop;\n\n    if new.selected_columns is not null then\n        for selected_col in select * from unnest(new.selected_columns) loop\n            if not selected_col = any(col_names) then\n                raise exception 'invalid column for select %', selected_col;\n            end if;\n        end loop;\n    end if;\n\n    -- Apply consistent order to filters so the unique constraint can't be tricked by a\n    -- different filter order. negate is part of the sort key.\n    new.filters = coalesce(\n        array_agg(f order by f.column_name, f.op, f.value, f.negate),\n        '{}'\n    ) from unnest(new.filters) f;\n\n    -- Normalize selected_columns order so ARRAY['a','b'] and ARRAY['b','a'] are treated\n    -- as the same subscription group in apply_rls. Preserve an empty array as '{}'\n    -- (\"primary keys only\") so it stays distinct from NULL (\"all columns\"); array_agg\n    -- over an empty set would otherwise collapse '{}' back to NULL.\n    if new.selected_columns is not null then\n        new.selected_columns = coalesce(\n            (\n                select array_agg(c order by c)\n                from unnest(new.selected_columns) c\n            ),\n            '{}'::text[]\n        );\n    end if;\n\n    return new;\nend;\n$function$\n",
            "return_type": "trigger",
            "security_definer": false
        },
        {
            "name": "to_regrole",
            "schema": "realtime",
            "language": "sql",
            "arguments": "role_name text",
            "definition": "CREATE OR REPLACE FUNCTION realtime.to_regrole(role_name text)\n RETURNS regrole\n LANGUAGE sql\n IMMUTABLE\nAS $function$ select role_name::regrole $function$\n",
            "return_type": "regrole",
            "security_definer": false
        },
        {
            "name": "topic",
            "schema": "realtime",
            "language": "sql",
            "arguments": "",
            "definition": "CREATE OR REPLACE FUNCTION realtime.topic()\n RETURNS text\n LANGUAGE sql\n STABLE\nAS $function$\nselect nullif(current_setting('realtime.topic', true), '')::text;\n$function$\n",
            "return_type": "text",
            "security_definer": false
        },
        {
            "name": "wal2json_escape_identifier",
            "schema": "realtime",
            "language": "sql",
            "arguments": "name text",
            "definition": "CREATE OR REPLACE FUNCTION realtime.wal2json_escape_identifier(name text)\n RETURNS text\n LANGUAGE sql\n IMMUTABLE STRICT\nAS $function$\n  -- Prefix `\\`, `,`, `.`, and any whitespace with `\\`\n  SELECT regexp_replace(name, '([\\\\,.[:space:]])', '\\\\\\1', 'g')\n$function$\n",
            "return_type": "text",
            "security_definer": false
        },
        {
            "name": "allow_any_operation",
            "schema": "storage",
            "language": "sql",
            "arguments": "expected_operations text[]",
            "definition": "CREATE OR REPLACE FUNCTION storage.allow_any_operation(expected_operations text[])\n RETURNS boolean\n LANGUAGE sql\n STABLE\nAS $function$\n  WITH current_operation AS (\n    SELECT storage.operation() AS raw_operation\n  ),\n  normalized AS (\n    SELECT CASE\n      WHEN raw_operation LIKE 'storage.%' THEN substr(raw_operation, 9)\n      ELSE raw_operation\n    END AS current_operation\n    FROM current_operation\n  )\n  SELECT EXISTS (\n    SELECT 1\n    FROM normalized n\n    CROSS JOIN LATERAL unnest(expected_operations) AS expected_operation\n    WHERE expected_operation IS NOT NULL\n      AND expected_operation <> ''\n      AND n.current_operation = CASE\n        WHEN expected_operation LIKE 'storage.%' THEN substr(expected_operation, 9)\n        ELSE expected_operation\n      END\n  );\n$function$\n",
            "return_type": "boolean",
            "security_definer": false
        },
        {
            "name": "allow_only_operation",
            "schema": "storage",
            "language": "sql",
            "arguments": "expected_operation text",
            "definition": "CREATE OR REPLACE FUNCTION storage.allow_only_operation(expected_operation text)\n RETURNS boolean\n LANGUAGE sql\n STABLE\nAS $function$\n  WITH current_operation AS (\n    SELECT storage.operation() AS raw_operation\n  ),\n  normalized AS (\n    SELECT\n      CASE\n        WHEN raw_operation LIKE 'storage.%' THEN substr(raw_operation, 9)\n        ELSE raw_operation\n      END AS current_operation,\n      CASE\n        WHEN expected_operation LIKE 'storage.%' THEN substr(expected_operation, 9)\n        ELSE expected_operation\n      END AS requested_operation\n    FROM current_operation\n  )\n  SELECT CASE\n    WHEN requested_operation IS NULL OR requested_operation = '' THEN FALSE\n    ELSE COALESCE(current_operation = requested_operation, FALSE)\n  END\n  FROM normalized;\n$function$\n",
            "return_type": "boolean",
            "security_definer": false
        },
        {
            "name": "can_insert_object",
            "schema": "storage",
            "language": "plpgsql",
            "arguments": "bucketid text, name text, owner uuid, metadata jsonb",
            "definition": "CREATE OR REPLACE FUNCTION storage.can_insert_object(bucketid text, name text, owner uuid, metadata jsonb)\n RETURNS void\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n  INSERT INTO \"storage\".\"objects\" (\"bucket_id\", \"name\", \"owner\", \"metadata\") VALUES (bucketid, name, owner, metadata);\n  -- hack to rollback the successful insert\n  RAISE sqlstate 'PT200' using\n  message = 'ROLLBACK',\n  detail = 'rollback successful insert';\nEND\n$function$\n",
            "return_type": "void",
            "security_definer": false
        },
        {
            "name": "enforce_bucket_lifecycle_service_role",
            "schema": "storage",
            "language": "plpgsql",
            "arguments": "",
            "definition": "CREATE OR REPLACE FUNCTION storage.enforce_bucket_lifecycle_service_role()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO 'pg_catalog'\nAS $function$\nBEGIN\n  IF current_user::text IS DISTINCT FROM TG_ARGV[0]\n     AND (\n       OLD.lifecycle_configuration IS DISTINCT FROM NEW.lifecycle_configuration\n       OR OLD.lifecycle_configuration_generation IS DISTINCT FROM NEW.lifecycle_configuration_generation\n     ) THEN\n    -- AFTER runs only after caller RLS has accepted the proposed row. The API\n    -- recognizes this specific error after rolling back its permission probe;\n    -- direct non-service writes still fail and cannot persist the change.\n    RAISE EXCEPTION 'bucket control columns may only be changed by the configured storage service role'\n      USING ERRCODE = 'PST01',\n            SCHEMA = TG_TABLE_SCHEMA,\n            TABLE = TG_TABLE_NAME,\n            CONSTRAINT = TG_NAME;\n  END IF;\n\n  RETURN NULL;\nEND;\n$function$\n",
            "return_type": "trigger",
            "security_definer": false
        },
        {
            "name": "enforce_bucket_name_length",
            "schema": "storage",
            "language": "plpgsql",
            "arguments": "",
            "definition": "CREATE OR REPLACE FUNCTION storage.enforce_bucket_name_length()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nbegin\n    if length(new.name) > 100 then\n        raise exception 'bucket name \"%\" is too long (% characters). Max is 100.', new.name, length(new.name);\n    end if;\n    return new;\nend;\n$function$\n",
            "return_type": "trigger",
            "security_definer": false
        },
        {
            "name": "extension",
            "schema": "storage",
            "language": "plpgsql",
            "arguments": "name text",
            "definition": "CREATE OR REPLACE FUNCTION storage.extension(name text)\n RETURNS text\n LANGUAGE plpgsql\n IMMUTABLE\nAS $function$\nDECLARE\n    _parts text[];\n    _filename text;\nBEGIN\n    -- Split on \"/\" to get path segments\n    SELECT string_to_array(name, '/') INTO _parts;\n    -- Get the last path segment (the actual filename)\n    SELECT _parts[array_length(_parts, 1)] INTO _filename;\n    -- Extract extension: reverse, split on '.', then reverse again\n    RETURN reverse(split_part(reverse(_filename), '.', 1));\nEND\n$function$\n",
            "return_type": "text",
            "security_definer": false
        },
        {
            "name": "filename",
            "schema": "storage",
            "language": "plpgsql",
            "arguments": "name text",
            "definition": "CREATE OR REPLACE FUNCTION storage.filename(name text)\n RETURNS text\n LANGUAGE plpgsql\n IMMUTABLE\nAS $function$\nDECLARE\n    _parts text[];\nBEGIN\n    SELECT string_to_array(name, '/') INTO _parts;\n    RETURN _parts[array_length(_parts, 1)];\nEND\n$function$\n",
            "return_type": "text",
            "security_definer": false
        },
        {
            "name": "foldername",
            "schema": "storage",
            "language": "plpgsql",
            "arguments": "name text",
            "definition": "CREATE OR REPLACE FUNCTION storage.foldername(name text)\n RETURNS text[]\n LANGUAGE plpgsql\n IMMUTABLE\nAS $function$\nDECLARE\n    _parts text[];\nBEGIN\n    -- Split on \"/\" to get path segments\n    SELECT string_to_array(name, '/') INTO _parts;\n    -- Return everything except the last segment\n    RETURN _parts[1 : array_length(_parts,1) - 1];\nEND\n$function$\n",
            "return_type": "text[]",
            "security_definer": false
        },
        {
            "name": "get_common_prefix",
            "schema": "storage",
            "language": "sql",
            "arguments": "p_key text, p_prefix text, p_delimiter text",
            "definition": "CREATE OR REPLACE FUNCTION storage.get_common_prefix(p_key text, p_prefix text, p_delimiter text)\n RETURNS text\n LANGUAGE sql\n IMMUTABLE\nAS $function$\nSELECT CASE\n    WHEN p_delimiter <> ''\n         AND position(p_delimiter IN substring(p_key FROM length(p_prefix) + 1)) > 0\n    THEN left(\n        p_key,\n        length(p_prefix)\n            + position(p_delimiter IN substring(p_key FROM length(p_prefix) + 1))\n            + length(p_delimiter) - 1\n    )\n    ELSE NULL\nEND;\n$function$\n",
            "return_type": "text",
            "security_definer": false
        },
        {
            "name": "get_size_by_bucket",
            "schema": "storage",
            "language": "plpgsql",
            "arguments": "noncurrent_versions text DEFAULT 'include'::text, delete_markers text DEFAULT 'include'::text",
            "definition": "CREATE OR REPLACE FUNCTION storage.get_size_by_bucket(noncurrent_versions text DEFAULT 'include'::text, delete_markers text DEFAULT 'include'::text)\n RETURNS TABLE(size bigint, bucket_id text)\n LANGUAGE plpgsql\n STABLE\nAS $function$\nBEGIN\n    -- COALESCE first: NULL NOT IN (...) evaluates to NULL (not TRUE), so a\n    -- bare NOT IN check silently leaves an explicit NULL argument unreset.\n    noncurrent_versions := COALESCE(noncurrent_versions, 'include');\n    delete_markers := COALESCE(delete_markers, 'include');\n    IF noncurrent_versions NOT IN ('exclude', 'only', 'include') THEN\n        noncurrent_versions := 'include';\n    END IF;\n    IF delete_markers NOT IN ('exclude', 'only', 'include') THEN\n        delete_markers := 'include';\n    END IF;\n\n    return query\n        select sum((metadata->>'size')::bigint)::bigint as size, obj.bucket_id\n        from \"storage\".objects as obj\n        where (noncurrent_versions != 'exclude' OR obj.archived_at IS NULL)\n          and (noncurrent_versions != 'only' OR obj.archived_at IS NOT NULL)\n          and (delete_markers != 'exclude' OR NOT obj.is_delete_marker)\n          and (delete_markers != 'only' OR obj.is_delete_marker)\n        group by obj.bucket_id;\nEND\n$function$\n",
            "return_type": "TABLE(size bigint, bucket_id text)",
            "security_definer": false
        },
        {
            "name": "list_multipart_uploads_with_delimiter",
            "schema": "storage",
            "language": "sql",
            "arguments": "bucket_id text, prefix_param text, delimiter_param text, max_keys integer DEFAULT 100, next_key_token text DEFAULT ''::text, next_upload_token text DEFAULT ''::text, raw_prefix_param text DEFAULT NULL::text",
            "definition": "CREATE OR REPLACE FUNCTION storage.list_multipart_uploads_with_delimiter(bucket_id text, prefix_param text, delimiter_param text, max_keys integer DEFAULT 100, next_key_token text DEFAULT ''::text, next_upload_token text DEFAULT ''::text, raw_prefix_param text DEFAULT NULL::text)\n RETURNS TABLE(key text, id text, created_at timestamp with time zone)\n LANGUAGE sql\n STABLE\nAS $function$\nWITH candidates AS (\n    SELECT\n        upload.key AS object_key,\n        CASE\n            WHEN position($3 IN substring(upload.key FROM length(coalesce($7, $2)) + 1)) > 0\n            THEN left(\n                upload.key,\n                length(coalesce($7, $2))\n                    + position($3 IN substring(upload.key FROM length(coalesce($7, $2)) + 1))\n                    + length($3) - 1\n            )\n            ELSE upload.key\n        END AS result_key,\n        upload.id,\n        upload.created_at,\n        position($3 IN substring(upload.key FROM length(coalesce($7, $2)) + 1)) > 0 AS is_common_prefix\n    FROM storage.s3_multipart_uploads AS upload\n    WHERE upload.bucket_id = $1\n      AND upload.key COLLATE \"C\" LIKE $2 || '%'\n), filtered AS (\n    SELECT candidate.*\n    FROM candidates AS candidate\n    WHERE $5 = ''\n       OR candidate.result_key COLLATE \"C\" > $5\n       OR (\n           candidate.result_key COLLATE \"C\" = $5\n           AND NOT candidate.is_common_prefix\n           AND $6 <> ''\n           -- A completed or aborted marker repeats the remaining same-key uploads.\n           AND COALESCE(\n               (candidate.created_at, candidate.id COLLATE \"C\") > (\n                   SELECT marker.created_at, marker.id COLLATE \"C\"\n                   FROM storage.s3_multipart_uploads AS marker\n                   WHERE marker.bucket_id = $1\n                     AND marker.key COLLATE \"C\" = $5\n                     AND marker.id = $6\n               ),\n               TRUE\n           )\n       )\n), ranked AS (\n    SELECT\n        filtered.*,\n        row_number() OVER (\n            PARTITION BY filtered.result_key COLLATE \"C\"\n            ORDER BY filtered.created_at, filtered.id COLLATE \"C\"\n        ) AS prefix_rank\n    FROM filtered\n)\nSELECT ranked.result_key, ranked.id, ranked.created_at\nFROM ranked\nWHERE NOT ranked.is_common_prefix OR ranked.prefix_rank = 1\nORDER BY ranked.result_key COLLATE \"C\", ranked.created_at, ranked.id COLLATE \"C\"\nLIMIT $4;\n$function$\n",
            "return_type": "TABLE(key text, id text, created_at timestamp with time zone)",
            "security_definer": false
        },
        {
            "name": "list_objects_with_delimiter",
            "schema": "storage",
            "language": "plpgsql",
            "arguments": "_bucket_id text, prefix_param text, delimiter_param text, max_keys integer DEFAULT 100, start_after text DEFAULT ''::text, next_token text DEFAULT ''::text, sort_order text DEFAULT 'asc'::text, noncurrent_versions text DEFAULT 'exclude'::text, delete_markers text DEFAULT 'exclude'::text, next_token_archived_at timestamp with time zone DEFAULT NULL::timestamp with time zone, next_token_version text DEFAULT ''::text",
            "definition": "CREATE OR REPLACE FUNCTION storage.list_objects_with_delimiter(_bucket_id text, prefix_param text, delimiter_param text, max_keys integer DEFAULT 100, start_after text DEFAULT ''::text, next_token text DEFAULT ''::text, sort_order text DEFAULT 'asc'::text, noncurrent_versions text DEFAULT 'exclude'::text, delete_markers text DEFAULT 'exclude'::text, next_token_archived_at timestamp with time zone DEFAULT NULL::timestamp with time zone, next_token_version text DEFAULT ''::text)\n RETURNS TABLE(name text, id uuid, metadata jsonb, updated_at timestamp with time zone, created_at timestamp with time zone, last_accessed_at timestamp with time zone, version text, archived_at timestamp with time zone, is_delete_marker boolean, is_versioned boolean)\n LANGUAGE plpgsql\n STABLE\nAS $function$\nDECLARE\n    v_peek_name TEXT;\n    v_current RECORD;\n    v_common_prefix TEXT;\n\n    -- Configuration\n    v_is_asc BOOLEAN;\n    v_prefix TEXT;\n    v_start TEXT;\n    v_start_relative TEXT;\n    v_upper_bound TEXT;\n    v_file_batch_size INT;\n    v_version_filter TEXT;\n\n    -- true when noncurrent_versions can return >1 row per name; keeps them\n    -- ordered most-recent-first and lets pagination resume mid-key\n    v_multi_row BOOLEAN;\n    v_name_order TEXT;\n    v_exact_range_predicate TEXT;\n    v_strict_range_predicate TEXT;\n    v_inclusive_range_predicate TEXT;\n\n    -- Seek state for the current name. archived_at is normalized to JavaScript's\n    -- millisecond precision and version breaks ties within the same millisecond.\n    -- Current rows use 'infinity'; NULL means no tiebreak has been established.\n    v_next_seek TEXT;\n    v_next_seek_at TIMESTAMPTZ;\n    v_next_seek_version TEXT;\n    v_next_seek_strict BOOLEAN := false;\n    v_cursor_is_folder BOOLEAN;\n    v_count INT := 0;\n    v_previous_seek TEXT;\n    v_previous_seek_at TIMESTAMPTZ;\n    v_previous_seek_version TEXT;\n    v_previous_count INT;\n\n    -- Dynamic SQL for batch query only\n    v_batch_query TEXT;\n    v_batch_query_strict TEXT;\n    v_delete_marker_peek_query TEXT;\n    v_delete_marker_peek_query_strict TEXT;\n\nBEGIN\n    -- ========================================================================\n    -- INITIALIZATION\n    -- ========================================================================\n    v_is_asc := lower(coalesce(sort_order, 'asc')) = 'asc';\n    v_prefix := coalesce(prefix_param, '');\n    v_start := CASE WHEN coalesce(next_token, '') <> '' THEN next_token ELSE coalesce(start_after, '') END;\n    v_file_batch_size := LEAST(GREATEST(max_keys * 2, 100), 1000);\n    v_next_seek_at := NULL;\n    v_next_seek_version := '';\n\n    -- COALESCE first: NULL NOT IN (...) evaluates to NULL (not TRUE), so a\n    -- bare NOT IN check silently leaves an explicit NULL argument unreset.\n    noncurrent_versions := COALESCE(noncurrent_versions, 'exclude');\n    delete_markers := COALESCE(delete_markers, 'exclude');\n    IF noncurrent_versions NOT IN ('exclude', 'only', 'include') THEN\n        noncurrent_versions := 'exclude';\n    END IF;\n    IF delete_markers NOT IN ('exclude', 'only', 'include') THEN\n        delete_markers := 'exclude';\n    END IF;\n\n    v_multi_row := noncurrent_versions IN ('only', 'include');\n    v_name_order := CASE WHEN v_is_asc THEN 'ASC' ELSE 'DESC' END;\n\n    v_version_filter := '';\n    IF noncurrent_versions = 'exclude' THEN\n        v_version_filter := v_version_filter || ' AND o.archived_at IS NULL';\n    ELSIF noncurrent_versions = 'only' THEN\n        v_version_filter := v_version_filter || ' AND o.archived_at IS NOT NULL';\n    END IF;\n    IF delete_markers = 'exclude' THEN\n        v_version_filter := v_version_filter || ' AND NOT o.is_delete_marker';\n    ELSIF delete_markers = 'only' THEN\n        v_version_filter := v_version_filter || ' AND o.is_delete_marker';\n    END IF;\n\n    -- Calculate upper bound for prefix filtering (bytewise, using COLLATE \"C\")\n    IF v_prefix = '' THEN\n        v_upper_bound := NULL;\n    ELSE\n        v_upper_bound := left(v_prefix, -1) || chr(ascii(right(v_prefix, 1)) + 1);\n    END IF;\n\n    -- Keep caller-provided cursors inside the requested prefix range.\n    IF v_start <> '' AND v_upper_bound IS NOT NULL THEN\n        IF v_is_asc THEN\n            IF v_start COLLATE \"C\" < v_prefix COLLATE \"C\" THEN\n                v_start := '';\n            ELSIF v_start COLLATE \"C\" >= v_upper_bound COLLATE \"C\" THEN\n                RETURN;\n            END IF;\n        ELSE\n            IF v_start COLLATE \"C\" < v_prefix COLLATE \"C\" THEN\n                RETURN;\n            ELSIF v_start COLLATE \"C\" >= v_upper_bound COLLATE \"C\" THEN\n                v_start := '';\n            END IF;\n        END IF;\n    END IF;\n\n    v_start_relative := substring(v_start FROM length(v_prefix) + 1);\n\n    -- Direction affects only the indexed name range and its ordering. Cursor\n    -- state transitions and within-key version ordering stay shared.\n    IF v_is_asc THEN\n        v_exact_range_predicate := 'TRUE';\n        v_strict_range_predicate := 'o.name COLLATE \"C\" > $2';\n        v_inclusive_range_predicate := 'o.name COLLATE \"C\" >= $2';\n        IF v_upper_bound IS NOT NULL THEN\n            v_exact_range_predicate := 'o.name COLLATE \"C\" < $3';\n            v_strict_range_predicate := v_strict_range_predicate || ' AND o.name COLLATE \"C\" < $3';\n            v_inclusive_range_predicate := v_inclusive_range_predicate || ' AND o.name COLLATE \"C\" < $3';\n        END IF;\n    ELSE\n        v_exact_range_predicate := 'TRUE';\n        v_strict_range_predicate := 'o.name COLLATE \"C\" < $2';\n        v_inclusive_range_predicate := 'o.name COLLATE \"C\" < $2';\n        IF v_prefix <> '' THEN\n            v_exact_range_predicate := 'o.name COLLATE \"C\" >= $3';\n            v_strict_range_predicate := v_strict_range_predicate || ' AND o.name COLLATE \"C\" >= $3';\n            v_inclusive_range_predicate := v_inclusive_range_predicate || ' AND o.name COLLATE \"C\" >= $3';\n        END IF;\n    END IF;\n\n    -- Build batch query (dynamic SQL - called infrequently, amortized over many rows)\n    -- The multi-row order matches the externally serialized cursor exactly:\n    -- archived_at at millisecond precision, then version as the final tiebreak.\n    --\n    -- When v_multi_row, the seek is a keyset tuple comparison (\"name > $2 OR\n    -- (name = $2 AND tiebreak)\") - Postgres won't split that OR into indexable\n    -- form (confirmed even with fully literal values), so as one WHERE clause\n    -- it forces a full bucket scan filtered row-by-row. Splitting it into two\n    -- independently-indexable branches (exact name match with the tiebreak\n    -- filter, vs. strictly-past names) combined with UNION ALL lets each\n    -- branch keep name as a real index condition; the outer ORDER BY/LIMIT\n    -- re-merges them into the same page the single query used to produce.\n    IF v_multi_row THEN\n        v_batch_query := format(\n            $sql$\n            SELECT *\n            FROM (\n                (\n                    SELECT o.name, o.id, o.updated_at, o.created_at,\n                           o.last_accessed_at, o.metadata, o.version,\n                           o.archived_at, o.is_delete_marker, o.is_versioned\n                    FROM storage.objects o\n                    WHERE o.bucket_id = $1\n                      AND o.name COLLATE \"C\" = $2\n                      AND %s\n                      AND NOT $7::boolean\n                      AND (\n                          $5::timestamptz IS NULL\n                          OR COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) < $5\n                          OR (\n                              COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) = $5\n                              AND COALESCE(o.version, '') > $6\n                          )\n                      )\n                      %s\n                    ORDER BY\n                        COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) DESC,\n                        COALESCE(o.version, '') ASC\n                    LIMIT $4\n                )\n                UNION ALL\n                (\n                    SELECT o.name, o.id, o.updated_at, o.created_at,\n                           o.last_accessed_at, o.metadata, o.version,\n                           o.archived_at, o.is_delete_marker, o.is_versioned\n                    FROM storage.objects o\n                    WHERE o.bucket_id = $1\n                      AND %s\n                      %s\n                    ORDER BY\n                        o.name COLLATE \"C\" %s,\n                        COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) DESC,\n                        COALESCE(o.version, '') ASC\n                    LIMIT $4\n                )\n            ) sub\n            ORDER BY\n                sub.name COLLATE \"C\" %s,\n                COALESCE(date_trunc('milliseconds', sub.archived_at), 'infinity'::timestamptz) DESC,\n                COALESCE(sub.version, '') ASC\n            LIMIT $4\n            $sql$,\n            v_exact_range_predicate,\n            v_version_filter,\n            v_strict_range_predicate,\n            v_version_filter,\n            v_name_order,\n            v_name_order\n        );\n    ELSE\n        v_batch_query := format(\n            $sql$\n            SELECT o.name, o.id, o.updated_at, o.created_at,\n                   o.last_accessed_at, o.metadata, o.version,\n                   o.archived_at, o.is_delete_marker, o.is_versioned\n            FROM storage.objects o\n            WHERE o.bucket_id = $1\n              AND %s\n              %s\n            ORDER BY o.name COLLATE \"C\" %s, o.archived_at DESC\n            LIMIT $4\n            $sql$,\n            v_inclusive_range_predicate,\n            v_version_filter,\n            v_name_order\n        );\n\n        -- Strict counterpart of the query above: used once the single-row\n        -- ASC batch advance (below) has left v_next_seek pointing at the\n        -- last row already emitted, so an inclusive predicate would\n        -- re-match it forever. Only single-row mode ever sets strict mode,\n        -- so this variant is never needed when v_multi_row.\n        v_batch_query_strict := format(\n            $sql$\n            SELECT o.name, o.id, o.updated_at, o.created_at,\n                   o.last_accessed_at, o.metadata, o.version,\n                   o.archived_at, o.is_delete_marker, o.is_versioned\n            FROM storage.objects o\n            WHERE o.bucket_id = $1\n              AND %s\n              %s\n            ORDER BY o.name COLLATE \"C\" %s, o.archived_at DESC\n            LIMIT $4\n            $sql$,\n            v_strict_range_predicate,\n            v_version_filter,\n            v_name_order\n        );\n    END IF;\n\n    -- The static peek predicates cannot use the partial delete-marker index\n    -- once PL/pgSQL switches to a generic plan because whether\n    -- is_delete_marker is required remains parameter-dependent. Reuse the\n    -- already-specialized batch query with a one-row limit for this sparse\n    -- filter so the plan sees a literal `o.is_delete_marker` predicate.\n    IF delete_markers = 'only' THEN\n        v_delete_marker_peek_query :=\n            'SELECT marker_page.name FROM (' || v_batch_query || ') marker_page LIMIT 1';\n        IF NOT v_multi_row THEN\n            v_delete_marker_peek_query_strict :=\n                'SELECT marker_page.name FROM (' || v_batch_query_strict || ') marker_page LIMIT 1';\n        END IF;\n    END IF;\n\n    -- ========================================================================\n    -- SEEK INITIALIZATION: Determine starting position\n    -- ========================================================================\n    IF v_start = '' THEN\n        IF v_is_asc THEN\n            v_next_seek := v_prefix;\n        ELSE\n            -- DESC without cursor performs one specialized initial seek so\n            -- partial current-version and delete-marker indexes remain available.\n            EXECUTE format(\n                'SELECT o.name FROM storage.objects o WHERE o.bucket_id = $1%s%s ORDER BY o.name COLLATE \"C\" DESC LIMIT 1',\n                CASE WHEN v_upper_bound IS NOT NULL\n                    THEN ' AND o.name COLLATE \"C\" >= $2 AND o.name COLLATE \"C\" < $3'\n                    ELSE ''\n                END,\n                v_version_filter\n            )\n            INTO v_next_seek\n            USING _bucket_id, v_prefix, v_upper_bound;\n\n            IF v_next_seek IS NOT NULL THEN\n                v_next_seek := v_next_seek || delimiter_param;\n            ELSE\n                RETURN;\n            END IF;\n        END IF;\n    ELSE\n        -- Folder continuation tokens retain their trailing delimiter. A\n        -- delimiter-less startAfter is always a literal key boundary.\n        v_cursor_is_folder := delimiter_param <> ''\n            AND v_start_relative <> ''\n            AND right(v_start_relative, length(delimiter_param)) = delimiter_param;\n\n        IF v_cursor_is_folder THEN\n            v_next_seek := CASE\n                WHEN right(v_start, length(delimiter_param)) = delimiter_param\n                    THEN v_start\n                ELSE v_start || delimiter_param\n            END;\n            IF v_is_asc THEN\n                v_next_seek := left(v_next_seek, -1)\n                    || chr(ascii(right(v_next_seek, 1)) + 1);\n            END IF;\n            v_next_seek_strict := NOT v_is_asc;\n        ELSE\n            -- leaf object: when v_multi_row, stay on v_start with the\n            -- caller-supplied tiebreak so a page boundary mid-key resumes\n            -- that key's remaining rows instead of skipping them. Truncate\n            -- to milliseconds like every other v_next_seek_at assignment -\n            -- harmless today since object.ts's cursor always round-trips\n            -- through JS Date first, but this shouldn't rely on that.\n            IF v_multi_row THEN\n                v_next_seek := v_start;\n                v_next_seek_at := date_trunc('milliseconds', next_token_archived_at);\n                v_next_seek_version := coalesce(next_token_version, '');\n                v_next_seek_strict := coalesce(next_token, '') = '';\n            ELSIF v_is_asc THEN\n                v_next_seek := v_start;\n                v_next_seek_strict := true;\n            ELSE\n                v_next_seek := v_start;\n            END IF;\n        END IF;\n    END IF;\n\n    -- ========================================================================\n    -- MAIN LOOP: Hybrid peek-then-batch algorithm\n    -- Uses STATIC SQL for peek (hot path) and DYNAMIC SQL for batch\n    -- ========================================================================\n    LOOP\n        EXIT WHEN v_count >= max_keys;\n\n        v_previous_seek := v_next_seek;\n        v_previous_seek_at := v_next_seek_at;\n        v_previous_seek_version := v_next_seek_version;\n        v_previous_count := v_count;\n\n        -- STEP 1: PEEK using STATIC SQL (plan cached, very fast)\n        -- v_multi_row is branched here (rather than folded into the WHERE\n        -- clause as a bound parameter) so each concrete query keeps an\n        -- unconditional seek predicate - once PL/pgSQL switches to its\n        -- cached generic plan (after 5 calls), a parameter-gated\n        -- \"(NOT v_multi_row AND name >= $x) OR (v_multi_row AND ...)\"\n        -- predicate stops the planner from using name as an index\n        -- condition at all, degrading every subsequent peek to a full\n        -- index scan filtered row-by-row instead of a bounded range scan.\n        -- v_multi_row's seek predicate is a keyset tuple comparison\n        -- (\"name > x OR (name = x AND tiebreak)\") - Postgres does not\n        -- split this OR into indexable form even with fully literal\n        -- values, so it falls back to a full scan filtered row-by-row.\n        -- Splitting it into two independently-indexable branches (exact\n        -- name match with the tiebreak filter, vs. strictly-past name)\n        -- combined with UNION ALL lets each branch keep name as a real\n        -- index condition; the outer ORDER BY/LIMIT picks whichever of\n        -- the (at most 2) rows sorts first.\n        IF delete_markers = 'only' THEN\n            EXECUTE CASE WHEN v_next_seek_strict AND NOT v_multi_row\n                THEN v_delete_marker_peek_query_strict\n                ELSE v_delete_marker_peek_query\n            END\n                INTO v_peek_name\n                USING _bucket_id, v_next_seek,\n                    CASE WHEN v_is_asc THEN COALESCE(v_upper_bound, v_prefix) ELSE v_prefix END,\n                    1, v_next_seek_at, v_next_seek_version, v_next_seek_strict;\n        ELSIF v_multi_row THEN\n            IF v_is_asc THEN\n                IF v_upper_bound IS NOT NULL THEN\n                    SELECT sub.name INTO v_peek_name FROM (\n                        (SELECT o.name FROM storage.objects o\n                         WHERE o.bucket_id = _bucket_id AND o.name COLLATE \"C\" = v_next_seek\n                           AND o.name COLLATE \"C\" < v_upper_bound\n                           AND NOT v_next_seek_strict\n                           AND (v_next_seek_at IS NULL\n                                OR COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) < v_next_seek_at\n                                OR (COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) = v_next_seek_at\n                                    AND COALESCE(o.version, '') > v_next_seek_version))\n                           AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)\n                           AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)\n                           AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                           AND (delete_markers != 'only' OR o.is_delete_marker)\n                         ORDER BY COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) DESC, COALESCE(o.version, '') ASC LIMIT 1)\n                        UNION ALL\n                        (SELECT o.name FROM storage.objects o\n                         WHERE o.bucket_id = _bucket_id AND o.name COLLATE \"C\" > v_next_seek AND o.name COLLATE \"C\" < v_upper_bound\n                           AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)\n                           AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)\n                           AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                           AND (delete_markers != 'only' OR o.is_delete_marker)\n                         ORDER BY o.name COLLATE \"C\" ASC LIMIT 1)\n                    ) sub ORDER BY sub.name COLLATE \"C\" ASC LIMIT 1;\n                ELSE\n                    SELECT sub.name INTO v_peek_name FROM (\n                        (SELECT o.name FROM storage.objects o\n                         WHERE o.bucket_id = _bucket_id AND o.name COLLATE \"C\" = v_next_seek\n                           AND NOT v_next_seek_strict\n                           AND (v_next_seek_at IS NULL\n                                OR COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) < v_next_seek_at\n                                OR (COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) = v_next_seek_at\n                                    AND COALESCE(o.version, '') > v_next_seek_version))\n                           AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)\n                           AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)\n                           AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                           AND (delete_markers != 'only' OR o.is_delete_marker)\n                         ORDER BY COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) DESC, COALESCE(o.version, '') ASC LIMIT 1)\n                        UNION ALL\n                        (SELECT o.name FROM storage.objects o\n                         WHERE o.bucket_id = _bucket_id AND o.name COLLATE \"C\" > v_next_seek\n                           AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)\n                           AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)\n                           AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                           AND (delete_markers != 'only' OR o.is_delete_marker)\n                         ORDER BY o.name COLLATE \"C\" ASC LIMIT 1)\n                    ) sub ORDER BY sub.name COLLATE \"C\" ASC LIMIT 1;\n                END IF;\n            ELSE\n                IF v_upper_bound IS NOT NULL THEN\n                    SELECT sub.name INTO v_peek_name FROM (\n                        (SELECT o.name FROM storage.objects o\n                         WHERE o.bucket_id = _bucket_id AND o.name COLLATE \"C\" = v_next_seek\n                           AND o.name COLLATE \"C\" >= v_prefix\n                           AND NOT v_next_seek_strict\n                           AND (v_next_seek_at IS NULL\n                                OR COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) < v_next_seek_at\n                                OR (COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) = v_next_seek_at\n                                    AND COALESCE(o.version, '') > v_next_seek_version))\n                           AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)\n                           AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)\n                           AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                           AND (delete_markers != 'only' OR o.is_delete_marker)\n                         ORDER BY COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) DESC, COALESCE(o.version, '') ASC LIMIT 1)\n                        UNION ALL\n                        (SELECT o.name FROM storage.objects o\n                         WHERE o.bucket_id = _bucket_id AND o.name COLLATE \"C\" < v_next_seek AND o.name COLLATE \"C\" >= v_prefix\n                           AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)\n                           AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)\n                           AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                           AND (delete_markers != 'only' OR o.is_delete_marker)\n                         ORDER BY o.name COLLATE \"C\" DESC LIMIT 1)\n                    ) sub ORDER BY sub.name COLLATE \"C\" DESC LIMIT 1;\n                ELSE\n                    SELECT sub.name INTO v_peek_name FROM (\n                        (SELECT o.name FROM storage.objects o\n                         WHERE o.bucket_id = _bucket_id AND o.name COLLATE \"C\" = v_next_seek\n                           AND NOT v_next_seek_strict\n                           AND (v_next_seek_at IS NULL\n                                OR COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) < v_next_seek_at\n                                OR (COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) = v_next_seek_at\n                                    AND COALESCE(o.version, '') > v_next_seek_version))\n                           AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)\n                           AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)\n                           AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                           AND (delete_markers != 'only' OR o.is_delete_marker)\n                         ORDER BY COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) DESC, COALESCE(o.version, '') ASC LIMIT 1)\n                        UNION ALL\n                        (SELECT o.name FROM storage.objects o\n                         WHERE o.bucket_id = _bucket_id AND o.name COLLATE \"C\" < v_next_seek\n                           AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)\n                           AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)\n                           AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                           AND (delete_markers != 'only' OR o.is_delete_marker)\n                         ORDER BY o.name COLLATE \"C\" DESC LIMIT 1)\n                    ) sub ORDER BY sub.name COLLATE \"C\" DESC LIMIT 1;\n                END IF;\n            END IF;\n        ELSE\n            -- Single-row mode is always noncurrent_versions='exclude'. Keep\n            -- this predicate literal so generic plans use the current index.\n            IF v_is_asc THEN\n                IF v_next_seek_strict AND v_upper_bound IS NOT NULL THEN\n                    SELECT o.name INTO v_peek_name FROM storage.objects o\n                    WHERE o.bucket_id = _bucket_id\n                      AND o.name COLLATE \"C\" > v_next_seek\n                      AND o.name COLLATE \"C\" < v_upper_bound\n                      AND o.archived_at IS NULL\n                      AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                      AND (delete_markers != 'only' OR o.is_delete_marker)\n                    ORDER BY o.name COLLATE \"C\" ASC LIMIT 1;\n                ELSIF v_next_seek_strict THEN\n                    SELECT o.name INTO v_peek_name FROM storage.objects o\n                    WHERE o.bucket_id = _bucket_id\n                      AND o.name COLLATE \"C\" > v_next_seek\n                      AND o.archived_at IS NULL\n                      AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                      AND (delete_markers != 'only' OR o.is_delete_marker)\n                    ORDER BY o.name COLLATE \"C\" ASC LIMIT 1;\n                ELSIF v_upper_bound IS NOT NULL THEN\n                    SELECT o.name INTO v_peek_name FROM storage.objects o\n                    WHERE o.bucket_id = _bucket_id\n                      AND o.name COLLATE \"C\" >= v_next_seek\n                      AND o.name COLLATE \"C\" < v_upper_bound\n                      AND o.archived_at IS NULL\n                      AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                      AND (delete_markers != 'only' OR o.is_delete_marker)\n                    ORDER BY o.name COLLATE \"C\" ASC LIMIT 1;\n                ELSE\n                    SELECT o.name INTO v_peek_name FROM storage.objects o\n                    WHERE o.bucket_id = _bucket_id\n                      AND o.name COLLATE \"C\" >= v_next_seek\n                      AND o.archived_at IS NULL\n                      AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                      AND (delete_markers != 'only' OR o.is_delete_marker)\n                    ORDER BY o.name COLLATE \"C\" ASC LIMIT 1;\n                END IF;\n            ELSE\n                IF v_upper_bound IS NOT NULL THEN\n                    SELECT o.name INTO v_peek_name FROM storage.objects o\n                    WHERE o.bucket_id = _bucket_id\n                      AND o.name COLLATE \"C\" < v_next_seek\n                      AND o.name COLLATE \"C\" >= v_prefix\n                      AND o.archived_at IS NULL\n                      AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                      AND (delete_markers != 'only' OR o.is_delete_marker)\n                    ORDER BY o.name COLLATE \"C\" DESC LIMIT 1;\n                ELSE\n                    SELECT o.name INTO v_peek_name FROM storage.objects o\n                    WHERE o.bucket_id = _bucket_id\n                      AND o.name COLLATE \"C\" < v_next_seek\n                      AND o.archived_at IS NULL\n                      AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                      AND (delete_markers != 'only' OR o.is_delete_marker)\n                    ORDER BY o.name COLLATE \"C\" DESC LIMIT 1;\n                END IF;\n            END IF;\n        END IF;\n\n        EXIT WHEN v_peek_name IS NULL;\n\n        -- STEP 2: Check if this is a FOLDER or FILE\n        v_common_prefix := storage.get_common_prefix(v_peek_name, v_prefix, delimiter_param);\n\n        IF v_common_prefix IS NOT NULL THEN\n            -- FOLDER: Emit and skip to next folder (no heap access needed)\n            name := v_common_prefix;\n            id := NULL;\n            updated_at := NULL;\n            created_at := NULL;\n            last_accessed_at := NULL;\n            metadata := NULL;\n            version := NULL;\n            archived_at := NULL;\n            is_delete_marker := NULL;\n            is_versioned := NULL;\n            RETURN NEXT;\n            v_count := v_count + 1;\n\n            -- Advance seek past the folder range\n            IF v_is_asc THEN\n                v_next_seek := left(v_common_prefix, -1)\n                    || chr(ascii(right(v_common_prefix, 1)) + 1);\n            ELSE\n                v_next_seek := v_common_prefix;\n            END IF;\n            v_next_seek_at := NULL;\n            v_next_seek_version := '';\n            v_next_seek_strict := NOT v_is_asc;\n        ELSE\n            -- FILE: Batch fetch using DYNAMIC SQL (overhead amortized over many rows)\n            -- For ASC: upper_bound is the exclusive upper limit (< condition)\n            -- For DESC: prefix is the inclusive lower limit (>= condition)\n            FOR v_current IN EXECUTE CASE WHEN v_next_seek_strict AND NOT v_multi_row THEN v_batch_query_strict ELSE v_batch_query END\n                USING _bucket_id, v_next_seek,\n                CASE WHEN v_is_asc THEN COALESCE(v_upper_bound, v_prefix) ELSE v_prefix END, v_file_batch_size, v_next_seek_at, v_next_seek_version,\n                v_next_seek_strict\n            LOOP\n                v_common_prefix := storage.get_common_prefix(v_current.name, v_prefix, delimiter_param);\n\n                IF v_common_prefix IS NOT NULL THEN\n                    -- Hit a folder: exit batch, let peek handle it. Reset\n                    -- strict mode too it may have been set by an earlier\n                    -- row in this same batch (see the single-row ASC advance\n                    -- below), and v_next_seek here is the folder-triggering\n                    -- row's own name, which the next peek must find inclusively.\n                    v_next_seek := CASE\n                        WHEN v_is_asc THEN v_current.name\n                        ELSE v_current.name || delimiter_param\n                    END;\n                    v_next_seek_at := NULL;\n                    v_next_seek_version := '';\n                    v_next_seek_strict := false;\n                    EXIT;\n                END IF;\n\n                -- Emit file\n                name := v_current.name;\n                id := v_current.id;\n                updated_at := v_current.updated_at;\n                created_at := v_current.created_at;\n                last_accessed_at := v_current.last_accessed_at;\n                metadata := v_current.metadata;\n                version := v_current.version;\n                archived_at := v_current.archived_at;\n                is_delete_marker := v_current.is_delete_marker;\n                is_versioned := v_current.is_versioned;\n                RETURN NEXT;\n                v_count := v_count + 1;\n\n                -- when v_multi_row, stay on this name and record its\n                -- archived_at as the new tiebreak so remaining rows for the\n                -- same key are picked up before moving to the next name\n                IF v_multi_row THEN\n                    v_next_seek := v_current.name;\n                    v_next_seek_at := COALESCE(date_trunc('milliseconds', v_current.archived_at), 'infinity'::timestamptz);\n                    v_next_seek_version := COALESCE(v_current.version, '');\n                    v_next_seek_strict := false;\n                ELSIF v_is_asc THEN\n                    -- Appending the delimiter as a fake lexical successor\n                    -- would skip a real key like `name || '!'` (or any\n                    -- character sorting below the delimiter), which sorts\n                    -- between `name` and `name || delimiter`. Track the real\n                    -- name and mark the next comparison strict instead.\n                    v_next_seek := v_current.name;\n                    v_next_seek_strict := true;\n                ELSE\n                    v_next_seek := v_current.name;\n                END IF;\n\n                EXIT WHEN v_count >= max_keys;\n            END LOOP;\n        END IF;\n\n        IF v_count = v_previous_count\n           AND v_next_seek IS NOT DISTINCT FROM v_previous_seek\n           AND v_next_seek_at IS NOT DISTINCT FROM v_previous_seek_at\n           AND v_next_seek_version IS NOT DISTINCT FROM v_previous_seek_version THEN\n            RAISE EXCEPTION 'storage.list_objects_with_delimiter made no progress at seek (%, %, %)',\n                v_next_seek, v_next_seek_at, v_next_seek_version;\n        END IF;\n    END LOOP;\nEND;\n$function$\n",
            "return_type": "TABLE(name text, id uuid, metadata jsonb, updated_at timestamp with time zone, created_at timestamp with time zone, last_accessed_at timestamp with time zone, version text, archived_at timestamp with time zone, is_delete_marker boolean, is_versioned boolean)",
            "security_definer": false
        },
        {
            "name": "operation",
            "schema": "storage",
            "language": "plpgsql",
            "arguments": "",
            "definition": "CREATE OR REPLACE FUNCTION storage.operation()\n RETURNS text\n LANGUAGE plpgsql\n STABLE\nAS $function$\nBEGIN\n    RETURN current_setting('storage.operation', true);\nEND;\n$function$\n",
            "return_type": "text",
            "security_definer": false
        },
        {
            "name": "protect_bucket_control_columns",
            "schema": "storage",
            "language": "plpgsql",
            "arguments": "",
            "definition": "CREATE OR REPLACE FUNCTION storage.protect_bucket_control_columns()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO 'pg_catalog'\nAS $function$\nDECLARE\n  configuration_changed boolean;\nBEGIN\n  IF TG_OP = 'INSERT' THEN\n    IF NEW.lifecycle_configuration IS NOT NULL\n       OR NEW.lifecycle_configuration_generation IS NOT NULL THEN\n      IF NOT pg_has_role(current_user, TG_ARGV[0], 'MEMBER') THEN\n        RAISE EXCEPTION 'only members of the configured storage service role may insert lifecycle policy state'\n          USING ERRCODE = '42501',\n                HINT = format(\n                  'Insert with both lifecycle columns NULL and configure lifecycle through the Storage API afterward, or insert as a member of %I.',\n                  TG_ARGV[0]\n                );\n      END IF;\n    END IF;\n\n    RETURN NEW;\n  END IF;\n\n  configuration_changed =\n    OLD.lifecycle_configuration IS DISTINCT FROM NEW.lifecycle_configuration\n    OR OLD.lifecycle_configuration_generation IS DISTINCT FROM NEW.lifecycle_configuration_generation;\n\n  IF NOT configuration_changed THEN\n    RETURN NEW;\n  END IF;\n\n  IF NEW.type IS DISTINCT FROM 'STANDARD' THEN\n    RAISE EXCEPTION 'bucket versioning and lifecycle controls require a Standard bucket'\n      USING ERRCODE = '0A000';\n  END IF;\n\n  IF NEW.lifecycle_configuration IS NULL\n     AND NEW.lifecycle_configuration_generation IS NULL THEN\n    RETURN NEW;\n  END IF;\n\n  IF NEW.lifecycle_configuration IS NULL\n     OR NEW.lifecycle_configuration_generation IS NULL\n     OR OLD.lifecycle_configuration IS NOT DISTINCT FROM NEW.lifecycle_configuration\n     OR OLD.lifecycle_configuration_generation IS NOT DISTINCT FROM NEW.lifecycle_configuration_generation THEN\n    RAISE EXCEPTION 'a changed lifecycle policy requires a new non-null generation'\n      USING ERRCODE = '22023';\n  END IF;\n\n  RETURN NEW;\nEND;\n$function$\n",
            "return_type": "trigger",
            "security_definer": false
        },
        {
            "name": "protect_delete",
            "schema": "storage",
            "language": "plpgsql",
            "arguments": "",
            "definition": "CREATE OR REPLACE FUNCTION storage.protect_delete()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    -- Check if storage.allow_delete_query is set to 'true'\n    IF COALESCE(current_setting('storage.allow_delete_query', true), 'false') != 'true' THEN\n        RAISE EXCEPTION 'Direct deletion from storage tables is not allowed. Use the Storage API instead.'\n            USING HINT = 'This prevents accidental data loss from orphaned objects.',\n                  ERRCODE = '42501';\n    END IF;\n    RETURN NULL;\nEND;\n$function$\n",
            "return_type": "trigger",
            "security_definer": false
        },
        {
            "name": "search",
            "schema": "storage",
            "language": "plpgsql",
            "arguments": "prefix text, bucketname text, limits integer DEFAULT 100, levels integer DEFAULT 1, offsets integer DEFAULT 0, search text DEFAULT ''::text, sortcolumn text DEFAULT 'name'::text, sortorder text DEFAULT 'asc'::text, noncurrent_versions text DEFAULT 'exclude'::text, delete_markers text DEFAULT 'exclude'::text",
            "definition": "CREATE OR REPLACE FUNCTION storage.search(prefix text, bucketname text, limits integer DEFAULT 100, levels integer DEFAULT 1, offsets integer DEFAULT 0, search text DEFAULT ''::text, sortcolumn text DEFAULT 'name'::text, sortorder text DEFAULT 'asc'::text, noncurrent_versions text DEFAULT 'exclude'::text, delete_markers text DEFAULT 'exclude'::text)\n RETURNS TABLE(name text, id uuid, updated_at timestamp with time zone, created_at timestamp with time zone, last_accessed_at timestamp with time zone, metadata jsonb, version text, archived_at timestamp with time zone, is_delete_marker boolean, is_versioned boolean)\n LANGUAGE plpgsql\n STABLE\nAS $function$\nDECLARE\n    v_peek_name TEXT;\n    v_current RECORD;\n    v_common_prefix TEXT;\n    v_delimiter CONSTANT TEXT := '/';\n\n    -- Configuration\n    v_limit INT;\n    v_prefix TEXT;\n    v_prefix_lower TEXT;\n    v_prefix_len INT;\n    v_prefix_start INT;\n    v_combined_levels INT;\n    v_is_asc BOOLEAN;\n    v_order_by TEXT;\n    v_sort_order TEXT;\n    v_upper_bound TEXT;\n    v_file_batch_size INT;\n    v_version_filter TEXT;\n    v_multi_row BOOLEAN;\n\n    -- Dynamic SQL for batch query only\n    v_batch_query TEXT;\n    v_delete_marker_peek_query TEXT;\n    v_delete_marker_peek_query_strict TEXT;\n\n    -- Seek state\n    v_next_seek TEXT;\n    v_next_seek_at TIMESTAMPTZ;\n    v_next_seek_version TEXT;\n    v_next_seek_strict BOOLEAN := false;\n    v_count INT := 0;\n    v_skipped INT := 0;\n    v_previous_seek TEXT;\n    v_previous_seek_at TIMESTAMPTZ;\n    v_previous_seek_version TEXT;\n    v_previous_count INT;\n    v_previous_skipped INT;\nBEGIN\n    -- ========================================================================\n    -- INITIALIZATION\n    -- ========================================================================\n    v_limit := LEAST(coalesce(limits, 100), 1500);\n    v_prefix := coalesce(prefix, '') || coalesce(search, '');\n    v_prefix_lower := lower(v_prefix);\n    v_prefix_len := length(coalesce(prefix, ''));\n    v_prefix_start := coalesce(array_length(string_to_array(coalesce(prefix, ''), v_delimiter), 1), 1);\n    v_combined_levels := coalesce(array_length(string_to_array(v_prefix, v_delimiter), 1), 1);\n    v_is_asc := lower(coalesce(sortorder, 'asc')) = 'asc';\n    v_file_batch_size := LEAST(GREATEST(v_limit * 2, 100), 1000);\n    v_next_seek_at := NULL;\n    v_next_seek_version := '';\n\n    -- COALESCE first: NULL NOT IN (...) evaluates to NULL (not TRUE), so a\n    -- bare NOT IN check silently leaves an explicit NULL argument unreset.\n    noncurrent_versions := COALESCE(noncurrent_versions, 'exclude');\n    delete_markers := COALESCE(delete_markers, 'exclude');\n    IF noncurrent_versions NOT IN ('exclude', 'only', 'include') THEN\n        noncurrent_versions := 'exclude';\n    END IF;\n    IF delete_markers NOT IN ('exclude', 'only', 'include') THEN\n        delete_markers := 'exclude';\n    END IF;\n\n    v_multi_row := noncurrent_versions IN ('only', 'include');\n\n    v_version_filter := '';\n    IF noncurrent_versions = 'exclude' THEN\n        v_version_filter := v_version_filter || ' AND o.archived_at IS NULL';\n    ELSIF noncurrent_versions = 'only' THEN\n        v_version_filter := v_version_filter || ' AND o.archived_at IS NOT NULL';\n    END IF;\n    IF delete_markers = 'exclude' THEN\n        v_version_filter := v_version_filter || ' AND NOT o.is_delete_marker';\n    ELSIF delete_markers = 'only' THEN\n        v_version_filter := v_version_filter || ' AND o.is_delete_marker';\n    END IF;\n\n    -- Validate sort column\n    CASE lower(coalesce(sortcolumn, 'name'))\n        WHEN 'name' THEN v_order_by := 'name';\n        WHEN 'updated_at' THEN v_order_by := 'updated_at';\n        WHEN 'created_at' THEN v_order_by := 'created_at';\n        WHEN 'last_accessed_at' THEN v_order_by := 'last_accessed_at';\n        ELSE v_order_by := 'name';\n    END CASE;\n\n    v_sort_order := CASE WHEN v_is_asc THEN 'asc' ELSE 'desc' END;\n\n    -- ========================================================================\n    -- NON-NAME SORTING: Use path_tokens approach\n    -- ========================================================================\n    IF v_order_by != 'name' THEN\n        RETURN QUERY EXECUTE format(\n            $sql$\n            WITH folders AS (\n                SELECT array_to_string(path_tokens[$1:$2], '/') AS folder\n                FROM storage.objects\n                WHERE objects.name ILIKE $3 || '%%'\n                  AND bucket_id = $4\n                  AND array_length(objects.path_tokens, 1) <> $2\n                  AND ($7 != 'exclude' OR objects.archived_at IS NULL)\n                  AND ($7 != 'only' OR objects.archived_at IS NOT NULL)\n                  AND ($8 != 'exclude' OR NOT objects.is_delete_marker)\n                  AND ($8 != 'only' OR objects.is_delete_marker)\n                GROUP BY folder\n                ORDER BY folder %s\n            )\n            (SELECT folder AS \"name\",\n                   NULL::uuid AS id,\n                   NULL::timestamptz AS updated_at,\n                   NULL::timestamptz AS created_at,\n                   NULL::timestamptz AS last_accessed_at,\n                   NULL::jsonb AS metadata,\n                   NULL::text AS version,\n                   NULL::timestamptz AS archived_at,\n                   NULL::boolean AS is_delete_marker,\n                   NULL::boolean AS is_versioned FROM folders)\n            UNION ALL\n            (SELECT array_to_string(path_tokens[$1:$2], '/') AS \"name\",\n                   id, updated_at, created_at, last_accessed_at, metadata,\n                   version, archived_at, is_delete_marker, is_versioned\n             FROM storage.objects\n             WHERE objects.name ILIKE $3 || '%%'\n               AND bucket_id = $4\n               AND array_length(objects.path_tokens, 1) = $2\n               AND ($7 != 'exclude' OR objects.archived_at IS NULL)\n               AND ($7 != 'only' OR objects.archived_at IS NOT NULL)\n               AND ($8 != 'exclude' OR NOT objects.is_delete_marker)\n               AND ($8 != 'only' OR objects.is_delete_marker)\n             -- name, then version, as tiebreaks so two versions of the same\n             -- key tying on the sort column still sort deterministically\n             ORDER BY %I %s, name COLLATE \"C\" %s, COALESCE(version, '') %s)\n            LIMIT $5 OFFSET $6\n            $sql$, v_sort_order, v_order_by, v_sort_order, v_sort_order, v_sort_order\n        ) USING v_prefix_start, v_combined_levels, v_prefix, bucketname, v_limit, offsets, noncurrent_versions, delete_markers;\n        RETURN;\n    END IF;\n\n    -- ========================================================================\n    -- NAME SORTING: Hybrid skip-scan with batch optimization\n    -- ========================================================================\n\n    -- Calculate upper bound for prefix filtering\n    IF v_prefix_lower = '' THEN\n        v_upper_bound := NULL;\n    ELSIF right(v_prefix_lower, 1) = v_delimiter THEN\n        v_upper_bound := left(v_prefix_lower, -1) || chr(ascii(v_delimiter) + 1);\n    ELSE\n        v_upper_bound := left(v_prefix_lower, -1) || chr(ascii(right(v_prefix_lower, 1)) + 1);\n    END IF;\n\n    -- Build a resume-safe batch query. The exact-name branch returns remaining\n    -- versions after the current (archived_at, version) boundary; the strict\n    -- name branch returns subsequent keys. UNION ALL keeps both predicates\n    -- independently indexable.\n    IF v_is_asc THEN\n        IF v_upper_bound IS NOT NULL THEN\n            v_batch_query := 'SELECT * FROM (' ||\n                '(SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata, o.version, o.archived_at, o.is_delete_marker, o.is_versioned FROM storage.objects o ' ||\n                'WHERE o.bucket_id = $1 AND lower(o.name) COLLATE \"C\" = $2 AND ($5::timestamptz IS NULL OR COALESCE(o.archived_at, ''infinity''::timestamptz) < $5 OR (COALESCE(o.archived_at, ''infinity''::timestamptz) = $5 AND COALESCE(o.version, '''') > $6))' ||\n                v_version_filter || ' ORDER BY COALESCE(o.archived_at, ''infinity''::timestamptz) DESC, COALESCE(o.version, '''') ASC LIMIT $4) UNION ALL ' ||\n                '(SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata, o.version, o.archived_at, o.is_delete_marker, o.is_versioned FROM storage.objects o ' ||\n                'WHERE o.bucket_id = $1 AND lower(o.name) COLLATE \"C\" > $2 AND lower(o.name) COLLATE \"C\" < $3' || v_version_filter ||\n                ' ORDER BY lower(o.name) COLLATE \"C\" ASC, COALESCE(o.archived_at, ''infinity''::timestamptz) DESC, COALESCE(o.version, '''') ASC LIMIT $4)' ||\n                ') sub ORDER BY lower(sub.name) COLLATE \"C\" ASC, COALESCE(sub.archived_at, ''infinity''::timestamptz) DESC, COALESCE(sub.version, '''') ASC LIMIT $4';\n        ELSE\n            v_batch_query := 'SELECT * FROM (' ||\n                '(SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata, o.version, o.archived_at, o.is_delete_marker, o.is_versioned FROM storage.objects o ' ||\n                'WHERE o.bucket_id = $1 AND lower(o.name) COLLATE \"C\" = $2 AND ($5::timestamptz IS NULL OR COALESCE(o.archived_at, ''infinity''::timestamptz) < $5 OR (COALESCE(o.archived_at, ''infinity''::timestamptz) = $5 AND COALESCE(o.version, '''') > $6))' ||\n                v_version_filter || ' ORDER BY COALESCE(o.archived_at, ''infinity''::timestamptz) DESC, COALESCE(o.version, '''') ASC LIMIT $4) UNION ALL ' ||\n                '(SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata, o.version, o.archived_at, o.is_delete_marker, o.is_versioned FROM storage.objects o ' ||\n                'WHERE o.bucket_id = $1 AND lower(o.name) COLLATE \"C\" > $2' || v_version_filter ||\n                ' ORDER BY lower(o.name) COLLATE \"C\" ASC, COALESCE(o.archived_at, ''infinity''::timestamptz) DESC, COALESCE(o.version, '''') ASC LIMIT $4)' ||\n                ') sub ORDER BY lower(sub.name) COLLATE \"C\" ASC, COALESCE(sub.archived_at, ''infinity''::timestamptz) DESC, COALESCE(sub.version, '''') ASC LIMIT $4';\n        END IF;\n    ELSE\n        IF v_upper_bound IS NOT NULL THEN\n            v_batch_query := 'SELECT * FROM (' ||\n                '(SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata, o.version, o.archived_at, o.is_delete_marker, o.is_versioned FROM storage.objects o ' ||\n                'WHERE o.bucket_id = $1 AND lower(o.name) COLLATE \"C\" = $2 AND ($5::timestamptz IS NULL OR COALESCE(o.archived_at, ''infinity''::timestamptz) < $5 OR (COALESCE(o.archived_at, ''infinity''::timestamptz) = $5 AND COALESCE(o.version, '''') > $6))' ||\n                v_version_filter || ' ORDER BY COALESCE(o.archived_at, ''infinity''::timestamptz) DESC, COALESCE(o.version, '''') ASC LIMIT $4) UNION ALL ' ||\n                '(SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata, o.version, o.archived_at, o.is_delete_marker, o.is_versioned FROM storage.objects o ' ||\n                'WHERE o.bucket_id = $1 AND lower(o.name) COLLATE \"C\" < $2 AND lower(o.name) COLLATE \"C\" >= $3' || v_version_filter ||\n                ' ORDER BY lower(o.name) COLLATE \"C\" DESC, COALESCE(o.archived_at, ''infinity''::timestamptz) DESC, COALESCE(o.version, '''') ASC LIMIT $4)' ||\n                ') sub ORDER BY lower(sub.name) COLLATE \"C\" DESC, COALESCE(sub.archived_at, ''infinity''::timestamptz) DESC, COALESCE(sub.version, '''') ASC LIMIT $4';\n        ELSE\n            v_batch_query := 'SELECT * FROM (' ||\n                '(SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata, o.version, o.archived_at, o.is_delete_marker, o.is_versioned FROM storage.objects o ' ||\n                'WHERE o.bucket_id = $1 AND lower(o.name) COLLATE \"C\" = $2 AND ($5::timestamptz IS NULL OR COALESCE(o.archived_at, ''infinity''::timestamptz) < $5 OR (COALESCE(o.archived_at, ''infinity''::timestamptz) = $5 AND COALESCE(o.version, '''') > $6))' ||\n                v_version_filter || ' ORDER BY COALESCE(o.archived_at, ''infinity''::timestamptz) DESC, COALESCE(o.version, '''') ASC LIMIT $4) UNION ALL ' ||\n                '(SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata, o.version, o.archived_at, o.is_delete_marker, o.is_versioned FROM storage.objects o ' ||\n                'WHERE o.bucket_id = $1 AND lower(o.name) COLLATE \"C\" < $2' || v_version_filter ||\n                ' ORDER BY lower(o.name) COLLATE \"C\" DESC, COALESCE(o.archived_at, ''infinity''::timestamptz) DESC, COALESCE(o.version, '''') ASC LIMIT $4)' ||\n                ') sub ORDER BY lower(sub.name) COLLATE \"C\" DESC, COALESCE(sub.archived_at, ''infinity''::timestamptz) DESC, COALESCE(sub.version, '''') ASC LIMIT $4';\n        END IF;\n    END IF;\n\n    -- Keep the delete-marker predicate literal so the cached generic\n    -- plan can use idx_objects_delete_markers during the main-loop peek.\n    IF delete_markers = 'only' THEN\n        IF v_multi_row THEN\n            v_delete_marker_peek_query :=\n                'SELECT marker_page.name FROM (' || v_batch_query || ') marker_page LIMIT 1';\n        ELSIF v_is_asc THEN\n            -- Two separate literal query strings, not one gated by a bound\n            -- boolean: folding \"$n AND op1 OR NOT $n AND op2\" into a single\n            -- query defeats the generic plan's ability to push either\n            -- comparison into the index. Branching in PL/pgSQL control flow\n            -- instead keeps each query's index condition intact.\n            v_delete_marker_peek_query :=\n                'SELECT o.name FROM storage.objects o WHERE o.bucket_id = $1 ' ||\n                'AND lower(o.name) COLLATE \"C\" >= $2' ||\n                CASE WHEN v_upper_bound IS NOT NULL\n                    THEN ' AND lower(o.name) COLLATE \"C\" < $3'\n                    ELSE ''\n                END ||\n                v_version_filter ||\n                ' ORDER BY lower(o.name) COLLATE \"C\" ASC LIMIT 1';\n            -- Strict variant: used once the single-row ASC batch advance\n            -- (below) has left v_next_seek pointing at the last row already\n            -- emitted, so a plain >= would re-match it forever.\n            v_delete_marker_peek_query_strict :=\n                'SELECT o.name FROM storage.objects o WHERE o.bucket_id = $1 ' ||\n                'AND lower(o.name) COLLATE \"C\" > $2' ||\n                CASE WHEN v_upper_bound IS NOT NULL\n                    THEN ' AND lower(o.name) COLLATE \"C\" < $3'\n                    ELSE ''\n                END ||\n                v_version_filter ||\n                ' ORDER BY lower(o.name) COLLATE \"C\" ASC LIMIT 1';\n        ELSE\n            v_delete_marker_peek_query :=\n                'SELECT o.name FROM storage.objects o WHERE o.bucket_id = $1 ' ||\n                'AND lower(o.name) COLLATE \"C\" < $2' ||\n                CASE WHEN v_upper_bound IS NOT NULL\n                    THEN ' AND lower(o.name) COLLATE \"C\" >= $3'\n                    ELSE ''\n                END ||\n                v_version_filter ||\n                ' ORDER BY lower(o.name) COLLATE \"C\" DESC LIMIT 1';\n        END IF;\n    END IF;\n\n    -- Initialize seek position\n    IF v_is_asc THEN\n        v_next_seek := v_prefix_lower;\n    ELSE\n        -- DESC performs one specialized initial seek so partial current-version\n        -- and delete-marker indexes remain available.\n        EXECUTE format(\n            'SELECT o.name FROM storage.objects o WHERE o.bucket_id = $1%s%s ORDER BY lower(o.name) COLLATE \"C\" DESC LIMIT 1',\n            CASE WHEN v_upper_bound IS NOT NULL\n                THEN ' AND lower(o.name) COLLATE \"C\" >= $2 AND lower(o.name) COLLATE \"C\" < $3'\n                ELSE ''\n            END,\n            v_version_filter\n        )\n        INTO v_peek_name\n        USING bucketname, v_prefix_lower, v_upper_bound;\n\n        IF v_peek_name IS NOT NULL THEN\n            v_next_seek := lower(v_peek_name) || v_delimiter;\n        ELSE\n            RETURN;\n        END IF;\n    END IF;\n\n    -- ========================================================================\n    -- MAIN LOOP: Hybrid peek-then-batch algorithm\n    -- Uses STATIC SQL for peek (hot path) and DYNAMIC SQL for batch and\n    -- the delete-marker-only path\n    -- ========================================================================\n    LOOP\n        EXIT WHEN v_count >= v_limit;\n\n        v_previous_seek := v_next_seek;\n        v_previous_seek_at := v_next_seek_at;\n        v_previous_seek_version := v_next_seek_version;\n        v_previous_count := v_count;\n        v_previous_skipped := v_skipped;\n\n        -- STEP 1: PEEK\n        v_peek_name := NULL;\n        IF delete_markers = 'only' THEN\n            EXECUTE CASE WHEN v_next_seek_strict\n                THEN v_delete_marker_peek_query_strict\n                ELSE v_delete_marker_peek_query\n            END\n                INTO v_peek_name\n                USING bucketname, v_next_seek,\n                    CASE WHEN v_is_asc THEN COALESCE(v_upper_bound, v_prefix_lower) ELSE v_prefix_lower END,\n                    1, v_next_seek_at, v_next_seek_version;\n        ELSIF v_multi_row AND v_next_seek_at IS NOT NULL THEN\n            SELECT o.name INTO v_peek_name\n            FROM storage.objects o\n            WHERE o.bucket_id = bucketname\n              AND lower(o.name) COLLATE \"C\" = v_next_seek\n              AND (COALESCE(o.archived_at, 'infinity'::timestamptz) < v_next_seek_at\n                   OR (COALESCE(o.archived_at, 'infinity'::timestamptz) = v_next_seek_at\n                       AND COALESCE(o.version, '') > v_next_seek_version))\n              AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)\n              AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)\n              AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n              AND (delete_markers != 'only' OR o.is_delete_marker)\n            ORDER BY COALESCE(o.archived_at, 'infinity'::timestamptz) DESC,\n                     COALESCE(o.version, '') ASC\n            LIMIT 1;\n\n            -- The current key is exhausted. Clear its version boundary and\n            -- make the following ASC name peek strict. Appending '/' is not a\n            -- valid lexical successor because keys ending in characters such\n            -- as '!' sort between the exhausted name and name || '/'.\n            IF v_peek_name IS NULL THEN\n                IF v_is_asc THEN\n                    v_next_seek_strict := true;\n                END IF;\n                v_next_seek_at := NULL;\n                v_next_seek_version := '';\n            END IF;\n        END IF;\n\n        -- Single-row mode is always noncurrent_versions='exclude'. Keep the\n        -- current-row predicate literal so generic plans use the current index.\n        IF delete_markers != 'only' AND v_peek_name IS NULL AND NOT v_multi_row THEN\n            IF v_is_asc THEN\n                IF v_next_seek_strict AND v_upper_bound IS NOT NULL THEN\n                    SELECT o.name INTO v_peek_name FROM storage.objects o\n                    WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE \"C\" > v_next_seek AND lower(o.name) COLLATE \"C\" < v_upper_bound\n                      AND o.archived_at IS NULL\n                      AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                    ORDER BY lower(o.name) COLLATE \"C\" ASC LIMIT 1;\n                ELSIF v_next_seek_strict THEN\n                    SELECT o.name INTO v_peek_name FROM storage.objects o\n                    WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE \"C\" > v_next_seek\n                      AND o.archived_at IS NULL\n                      AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                    ORDER BY lower(o.name) COLLATE \"C\" ASC LIMIT 1;\n                ELSIF v_upper_bound IS NOT NULL THEN\n                    SELECT o.name INTO v_peek_name FROM storage.objects o\n                    WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE \"C\" >= v_next_seek AND lower(o.name) COLLATE \"C\" < v_upper_bound\n                      AND o.archived_at IS NULL\n                      AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                    ORDER BY lower(o.name) COLLATE \"C\" ASC LIMIT 1;\n                ELSE\n                    SELECT o.name INTO v_peek_name FROM storage.objects o\n                    WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE \"C\" >= v_next_seek\n                      AND o.archived_at IS NULL\n                      AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                    ORDER BY lower(o.name) COLLATE \"C\" ASC LIMIT 1;\n                END IF;\n            ELSIF v_upper_bound IS NOT NULL THEN\n                SELECT o.name INTO v_peek_name FROM storage.objects o\n                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE \"C\" < v_next_seek AND lower(o.name) COLLATE \"C\" >= v_prefix_lower\n                  AND o.archived_at IS NULL\n                  AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                ORDER BY lower(o.name) COLLATE \"C\" DESC LIMIT 1;\n            ELSE\n                SELECT o.name INTO v_peek_name FROM storage.objects o\n                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE \"C\" < v_next_seek\n                  AND o.archived_at IS NULL\n                  AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                ORDER BY lower(o.name) COLLATE \"C\" DESC LIMIT 1;\n            END IF;\n        ELSIF delete_markers != 'only' AND v_peek_name IS NULL AND v_is_asc THEN\n            IF v_next_seek_strict AND v_upper_bound IS NOT NULL THEN\n                SELECT o.name INTO v_peek_name FROM storage.objects o\n                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE \"C\" > v_next_seek AND lower(o.name) COLLATE \"C\" < v_upper_bound\n                  AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)\n                  AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)\n                  AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                  AND (delete_markers != 'only' OR o.is_delete_marker)\n                ORDER BY lower(o.name) COLLATE \"C\" ASC LIMIT 1;\n            ELSIF v_next_seek_strict THEN\n                SELECT o.name INTO v_peek_name FROM storage.objects o\n                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE \"C\" > v_next_seek\n                  AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)\n                  AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)\n                  AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                  AND (delete_markers != 'only' OR o.is_delete_marker)\n                ORDER BY lower(o.name) COLLATE \"C\" ASC LIMIT 1;\n            ELSIF v_upper_bound IS NOT NULL THEN\n                SELECT o.name INTO v_peek_name FROM storage.objects o\n                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE \"C\" >= v_next_seek AND lower(o.name) COLLATE \"C\" < v_upper_bound\n                  AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)\n                  AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)\n                  AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                  AND (delete_markers != 'only' OR o.is_delete_marker)\n                ORDER BY lower(o.name) COLLATE \"C\" ASC LIMIT 1;\n            ELSE\n                SELECT o.name INTO v_peek_name FROM storage.objects o\n                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE \"C\" >= v_next_seek\n                  AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)\n                  AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)\n                  AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                  AND (delete_markers != 'only' OR o.is_delete_marker)\n                ORDER BY lower(o.name) COLLATE \"C\" ASC LIMIT 1;\n            END IF;\n        ELSIF delete_markers != 'only' AND v_peek_name IS NULL THEN\n            IF v_upper_bound IS NOT NULL THEN\n                SELECT o.name INTO v_peek_name FROM storage.objects o\n                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE \"C\" < v_next_seek AND lower(o.name) COLLATE \"C\" >= v_prefix_lower\n                  AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)\n                  AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)\n                  AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                  AND (delete_markers != 'only' OR o.is_delete_marker)\n                ORDER BY lower(o.name) COLLATE \"C\" DESC LIMIT 1;\n            ELSE\n                SELECT o.name INTO v_peek_name FROM storage.objects o\n                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE \"C\" < v_next_seek\n                  AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)\n                  AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)\n                  AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                  AND (delete_markers != 'only' OR o.is_delete_marker)\n                ORDER BY lower(o.name) COLLATE \"C\" DESC LIMIT 1;\n            END IF;\n        END IF;\n\n        EXIT WHEN v_peek_name IS NULL;\n\n        -- If the peek landed on a different key than we were tracking, any\n        -- version boundary belongs to the OLD key and must not leak into the\n        -- new one - e.g. the deleteMarkers='only' peek doesn't know or care\n        -- whether it's continuing the same key or jumping to a new one, so\n        -- it never clears these itself.\n        IF lower(v_peek_name) IS DISTINCT FROM v_next_seek THEN\n            v_next_seek_at := NULL;\n            v_next_seek_version := '';\n        END IF;\n\n        -- The peek is authoritative for the next key to process. This is\n        -- especially important after exhausting a multi-version key: the\n        -- version boundary has been cleared, so executing the batch against\n        -- a stale v_next_seek would replay every version of that old key.\n        v_next_seek := lower(v_peek_name);\n        v_next_seek_strict := false;\n\n        -- STEP 2: Check if this is a FOLDER or FILE\n        v_common_prefix := storage.get_common_prefix(lower(v_peek_name), v_prefix_lower, v_delimiter);\n\n        IF v_common_prefix IS NOT NULL THEN\n            -- FOLDER: Handle offset, emit if needed, skip to next folder\n            IF v_skipped < offsets THEN\n                v_skipped := v_skipped + 1;\n            ELSE\n                name := substring(rtrim(storage.get_common_prefix(v_peek_name, v_prefix, v_delimiter), v_delimiter) from v_prefix_len + 1);\n                id := NULL;\n                updated_at := NULL;\n                created_at := NULL;\n                last_accessed_at := NULL;\n                metadata := NULL;\n                version := NULL;\n                archived_at := NULL;\n                is_delete_marker := NULL;\n                is_versioned := NULL;\n                RETURN NEXT;\n                v_count := v_count + 1;\n            END IF;\n\n            -- Advance seek past the folder range\n            IF v_is_asc THEN\n                v_next_seek := lower(left(v_common_prefix, -1)) || chr(ascii(v_delimiter) + 1);\n            ELSE\n                v_next_seek := lower(v_common_prefix);\n            END IF;\n            v_next_seek_at := NULL;\n            v_next_seek_version := '';\n        ELSE\n            -- FILE: Batch fetch using DYNAMIC SQL (overhead amortized over many rows)\n            -- For ASC: upper_bound is the exclusive upper limit (< condition)\n            -- For DESC: prefix_lower is the inclusive lower limit (>= condition)\n            FOR v_current IN EXECUTE v_batch_query\n                USING bucketname, v_next_seek,\n                    CASE WHEN v_is_asc THEN COALESCE(v_upper_bound, v_prefix_lower) ELSE v_prefix_lower END, v_file_batch_size,\n                    v_next_seek_at, v_next_seek_version\n            LOOP\n                v_common_prefix := storage.get_common_prefix(lower(v_current.name), v_prefix_lower, v_delimiter);\n\n                IF v_common_prefix IS NOT NULL THEN\n                    -- Hit a folder: exit batch, let peek handle it. Reset\n                    -- strict mode too - it may have been set by an earlier\n                    -- row in this same batch (see the single-row ASC advance\n                    -- below), and v_next_seek here is the folder-triggering\n                    -- row's own name, which the next peek must find inclusively.\n                    v_next_seek := CASE\n                        WHEN v_is_asc THEN lower(v_current.name)\n                        ELSE lower(v_current.name) || v_delimiter\n                    END;\n                    v_next_seek_at := NULL;\n                    v_next_seek_version := '';\n                    v_next_seek_strict := false;\n                    EXIT;\n                END IF;\n\n                -- Handle offset skipping\n                IF v_skipped < offsets THEN\n                    v_skipped := v_skipped + 1;\n                ELSE\n                    -- Emit file\n                    name := substring(v_current.name from v_prefix_len + 1);\n                    id := v_current.id;\n                    updated_at := v_current.updated_at;\n                    created_at := v_current.created_at;\n                    last_accessed_at := v_current.last_accessed_at;\n                    metadata := v_current.metadata;\n                    version := v_current.version;\n                    archived_at := v_current.archived_at;\n                    is_delete_marker := v_current.is_delete_marker;\n                    is_versioned := v_current.is_versioned;\n                    RETURN NEXT;\n                    v_count := v_count + 1;\n                END IF;\n\n                -- Multi-row mode must remain on this key until all of its\n                -- versions have crossed the internal batch boundary.\n                IF v_multi_row THEN\n                    v_next_seek := lower(v_current.name);\n                    v_next_seek_at := COALESCE(v_current.archived_at, 'infinity'::timestamptz);\n                    v_next_seek_version := COALESCE(v_current.version, '');\n                ELSIF v_is_asc THEN\n                    -- Appending the delimiter as a fake lexical successor would\n                    -- skip a real key like `name || '!'` (or any character\n                    -- sorting below the delimiter), which sorts between `name`\n                    -- and `name || delimiter`. Track the real name and mark the\n                    -- next comparison strict instead - same fix as the\n                    -- exhausted-key case above.\n                    v_next_seek := lower(v_current.name);\n                    v_next_seek_strict := true;\n                ELSE\n                    v_next_seek := lower(v_current.name);\n                END IF;\n\n                EXIT WHEN v_count >= v_limit;\n            END LOOP;\n        END IF;\n\n        IF v_count = v_previous_count\n           AND v_skipped = v_previous_skipped\n           AND v_next_seek IS NOT DISTINCT FROM v_previous_seek\n           AND v_next_seek_at IS NOT DISTINCT FROM v_previous_seek_at\n           AND v_next_seek_version IS NOT DISTINCT FROM v_previous_seek_version THEN\n            RAISE EXCEPTION 'storage.search made no progress at seek (%, %, %)',\n                v_next_seek, v_next_seek_at, v_next_seek_version;\n        END IF;\n    END LOOP;\nEND;\n$function$\n",
            "return_type": "TABLE(name text, id uuid, updated_at timestamp with time zone, created_at timestamp with time zone, last_accessed_at timestamp with time zone, metadata jsonb, version text, archived_at timestamp with time zone, is_delete_marker boolean, is_versioned boolean)",
            "security_definer": false
        },
        {
            "name": "search_by_timestamp",
            "schema": "storage",
            "language": "plpgsql",
            "arguments": "p_prefix text, p_bucket_id text, p_limit integer, p_level integer, p_start_after text, p_sort_order text, p_sort_column text, p_sort_column_after text, noncurrent_versions text DEFAULT 'exclude'::text, delete_markers text DEFAULT 'exclude'::text, p_start_after_version text DEFAULT ''::text",
            "definition": "CREATE OR REPLACE FUNCTION storage.search_by_timestamp(p_prefix text, p_bucket_id text, p_limit integer, p_level integer, p_start_after text, p_sort_order text, p_sort_column text, p_sort_column_after text, noncurrent_versions text DEFAULT 'exclude'::text, delete_markers text DEFAULT 'exclude'::text, p_start_after_version text DEFAULT ''::text)\n RETURNS TABLE(key text, name text, id uuid, updated_at timestamp with time zone, created_at timestamp with time zone, last_accessed_at timestamp with time zone, metadata jsonb, version text, archived_at timestamp with time zone, is_delete_marker boolean, is_versioned boolean)\n LANGUAGE plpgsql\n STABLE\nAS $function$\nDECLARE\n    v_cursor_op text;\n    v_query text;\n    v_prefix text;\n    v_prefix_pattern text;\n    v_sort_order text;\n    v_sort_column text;\n    v_version_tiebreak text;\nBEGIN\n    v_prefix := coalesce(p_prefix, '');\n    -- Keep the raw prefix for common-prefix calculations and escape only LIKE metacharacters.\n    v_prefix_pattern := replace(v_prefix, chr(92), chr(92) || chr(92));\n    v_prefix_pattern := replace(v_prefix_pattern, '%', chr(92) || '%');\n    v_prefix_pattern := replace(v_prefix_pattern, '_', chr(92) || '_');\n\n    -- COALESCE first: NULL NOT IN (...) evaluates to NULL (not TRUE), so a\n    -- bare NOT IN check silently leaves an explicit NULL argument unreset.\n    noncurrent_versions := COALESCE(noncurrent_versions, 'exclude');\n    delete_markers := COALESCE(delete_markers, 'exclude');\n    IF noncurrent_versions NOT IN ('exclude', 'only', 'include') THEN\n        noncurrent_versions := 'exclude';\n    END IF;\n    IF delete_markers NOT IN ('exclude', 'only', 'include') THEN\n        delete_markers := 'exclude';\n    END IF;\n\n    -- $9 is only populated in multi-row mode; it's always '' otherwise, so\n    -- only use each row's real version as a tiebreak in multi-row mode.\n    v_version_tiebreak := CASE WHEN noncurrent_versions IN ('only', 'include') THEN 'COALESCE(version, '''')' ELSE '''''' END;\n\n    -- Defense-in-depth: this function is independently reachable and must\n    -- not trust p_sort_order/p_sort_column to already be validated by a\n    -- caller. Normalize to the same strict allow-list storage.search_v2\n    -- uses before interpolating anything into dynamic SQL below.\n    v_sort_order := lower(coalesce(p_sort_order, 'asc'));\n    IF v_sort_order NOT IN ('asc', 'desc') THEN\n        v_sort_order := 'asc';\n    END IF;\n\n    v_sort_column := lower(coalesce(p_sort_column, 'updated_at'));\n    IF v_sort_column NOT IN ('updated_at', 'created_at') THEN\n        v_sort_column := 'updated_at';\n    END IF;\n\n    IF v_sort_order = 'asc' THEN\n        v_cursor_op := '>';\n    ELSE\n        v_cursor_op := '<';\n    END IF;\n\n    v_query := format($sql$\n        WITH raw_objects AS (\n            SELECT\n                o.name AS obj_name,\n                o.id AS obj_id,\n                o.updated_at AS obj_updated_at,\n                o.created_at AS obj_created_at,\n                o.last_accessed_at AS obj_last_accessed_at,\n                o.metadata AS obj_metadata,\n                o.version AS obj_version,\n                o.archived_at AS obj_archived_at,\n                o.is_delete_marker AS obj_is_delete_marker,\n                o.is_versioned AS obj_is_versioned,\n                storage.get_common_prefix(o.name, $1, '/') AS common_prefix\n            FROM storage.objects o\n            WHERE o.bucket_id = $2\n              AND o.name COLLATE \"C\" LIKE $10 || '%%'\n              AND ($7 != 'exclude' OR o.archived_at IS NULL)\n              AND ($7 != 'only' OR o.archived_at IS NOT NULL)\n              AND ($8 != 'exclude' OR NOT o.is_delete_marker)\n              AND ($8 != 'only' OR o.is_delete_marker)\n        ),\n        -- Aggregate common prefixes (folders)\n        -- Both created_at and updated_at use MIN(obj_created_at) to match the old prefixes table behavior\n        aggregated_prefixes AS (\n            SELECT\n                common_prefix AS name,\n                NULL::uuid AS id,\n                MIN(obj_created_at) AS updated_at,\n                MIN(obj_created_at) AS created_at,\n                NULL::timestamptz AS last_accessed_at,\n                NULL::jsonb AS metadata,\n                NULL::text AS version,\n                NULL::timestamptz AS archived_at,\n                NULL::boolean AS is_delete_marker,\n                NULL::boolean AS is_versioned,\n                TRUE AS is_prefix\n            FROM raw_objects\n            WHERE common_prefix IS NOT NULL\n            GROUP BY common_prefix\n        ),\n        leaf_objects AS (\n            SELECT\n                obj_name AS name,\n                obj_id AS id,\n                obj_updated_at AS updated_at,\n                obj_created_at AS created_at,\n                obj_last_accessed_at AS last_accessed_at,\n                obj_metadata AS metadata,\n                obj_version AS version,\n                obj_archived_at AS archived_at,\n                obj_is_delete_marker AS is_delete_marker,\n                obj_is_versioned AS is_versioned,\n                FALSE AS is_prefix\n            FROM raw_objects\n            WHERE common_prefix IS NULL\n        ),\n        combined AS (\n            SELECT * FROM aggregated_prefixes\n            UNION ALL\n            SELECT * FROM leaf_objects\n        ),\n        filtered AS (\n            SELECT *\n            FROM combined\n            WHERE (\n                $5 = ''\n                OR ROW(\n                    COALESCE(date_trunc('milliseconds', %I), 'epoch'::timestamptz),\n                    name COLLATE \"C\",\n                    %s\n                ) %s ROW(\n                    -- truncated the same way as the stored value above\n                    date_trunc('milliseconds', COALESCE(NULLIF($6, '')::timestamptz, 'epoch'::timestamptz)),\n                    $5,\n                    $9\n                )\n            )\n        )\n        SELECT\n            split_part(name, '/', $3) AS key,\n            name,\n            id,\n            updated_at,\n            created_at,\n            last_accessed_at,\n            metadata,\n            version,\n            archived_at,\n            is_delete_marker,\n            is_versioned\n        FROM filtered\n        ORDER BY\n            COALESCE(date_trunc('milliseconds', %I), 'epoch'::timestamptz) %s,\n            name COLLATE \"C\" %s,\n            COALESCE(version, '') %s\n        LIMIT $4\n    $sql$,\n        v_sort_column,\n        v_version_tiebreak,\n        v_cursor_op,\n        v_sort_column,\n        v_sort_order,\n        v_sort_order,\n        v_sort_order\n    );\n\n    -- version is the third tiebreak component for two versions of the same\n    -- key tying on both timestamp and name (see filtered CTE / ORDER BY above)\n    RETURN QUERY EXECUTE v_query\n    USING v_prefix, p_bucket_id, p_level, p_limit, p_start_after, p_sort_column_after, noncurrent_versions, delete_markers, coalesce(p_start_after_version, ''), v_prefix_pattern;\nEND;\n$function$\n",
            "return_type": "TABLE(key text, name text, id uuid, updated_at timestamp with time zone, created_at timestamp with time zone, last_accessed_at timestamp with time zone, metadata jsonb, version text, archived_at timestamp with time zone, is_delete_marker boolean, is_versioned boolean)",
            "security_definer": false
        },
        {
            "name": "search_v2",
            "schema": "storage",
            "language": "plpgsql",
            "arguments": "prefix text, bucket_name text, limits integer DEFAULT 100, levels integer DEFAULT 1, start_after text DEFAULT ''::text, sort_order text DEFAULT 'asc'::text, sort_column text DEFAULT 'name'::text, sort_column_after text DEFAULT ''::text, noncurrent_versions text DEFAULT 'exclude'::text, delete_markers text DEFAULT 'exclude'::text, start_after_archived_at timestamp with time zone DEFAULT NULL::timestamp with time zone, start_after_version text DEFAULT ''::text, start_after_is_continuation boolean DEFAULT false",
            "definition": "CREATE OR REPLACE FUNCTION storage.search_v2(prefix text, bucket_name text, limits integer DEFAULT 100, levels integer DEFAULT 1, start_after text DEFAULT ''::text, sort_order text DEFAULT 'asc'::text, sort_column text DEFAULT 'name'::text, sort_column_after text DEFAULT ''::text, noncurrent_versions text DEFAULT 'exclude'::text, delete_markers text DEFAULT 'exclude'::text, start_after_archived_at timestamp with time zone DEFAULT NULL::timestamp with time zone, start_after_version text DEFAULT ''::text, start_after_is_continuation boolean DEFAULT false)\n RETURNS TABLE(key text, name text, id uuid, updated_at timestamp with time zone, created_at timestamp with time zone, last_accessed_at timestamp with time zone, metadata jsonb, version text, archived_at timestamp with time zone, is_delete_marker boolean, is_versioned boolean)\n LANGUAGE plpgsql\n STABLE\nAS $function$\nDECLARE\n    v_sort_col text;\n    v_sort_ord text;\n    v_limit int;\nBEGIN\n    -- Cap limit to maximum of 1500 records\n    v_limit := LEAST(coalesce(limits, 100), 1500);\n\n    -- Validate and normalize sort_order\n    v_sort_ord := lower(coalesce(sort_order, 'asc'));\n    IF v_sort_ord NOT IN ('asc', 'desc') THEN\n        v_sort_ord := 'asc';\n    END IF;\n\n    -- Validate and normalize sort_column\n    v_sort_col := lower(coalesce(sort_column, 'name'));\n    IF v_sort_col NOT IN ('name', 'updated_at', 'created_at') THEN\n        v_sort_col := 'name';\n    END IF;\n\n    -- Route to appropriate implementation\n    IF v_sort_col = 'name' THEN\n        -- Use list_objects_with_delimiter for name sorting (most efficient: O(k * log n))\n        RETURN QUERY\n        SELECT\n            split_part(l.name, '/', levels) AS key,\n            l.name AS name,\n            l.id,\n            l.updated_at,\n            l.created_at,\n            l.last_accessed_at,\n            l.metadata,\n            l.version,\n            l.archived_at,\n            l.is_delete_marker,\n            l.is_versioned\n        FROM storage.list_objects_with_delimiter(\n            bucket_name,\n            coalesce(prefix, ''),\n            '/',\n            v_limit,\n            CASE WHEN start_after_is_continuation THEN '' ELSE start_after END,\n            CASE WHEN start_after_is_continuation THEN start_after ELSE '' END,\n            v_sort_ord,\n            noncurrent_versions,\n            delete_markers,\n            start_after_archived_at,\n            start_after_version\n        ) l;\n    ELSE\n        -- Use aggregation approach for timestamp sorting\n        -- Not efficient for large datasets but supports correct pagination\n        RETURN QUERY SELECT * FROM storage.search_by_timestamp(\n            prefix, bucket_name, v_limit, levels, start_after,\n            v_sort_ord, v_sort_col, sort_column_after,\n            noncurrent_versions, delete_markers, start_after_version\n        );\n    END IF;\nEND;\n$function$\n",
            "return_type": "TABLE(key text, name text, id uuid, updated_at timestamp with time zone, created_at timestamp with time zone, last_accessed_at timestamp with time zone, metadata jsonb, version text, archived_at timestamp with time zone, is_delete_marker boolean, is_versioned boolean)",
            "security_definer": false
